access_roles_planner.cpp
```cpp
#include "access_roles_planner.h"

#include <algorithm>

namespace access_roles_planner {

AccessPlannerError::AccessPlannerError(const std::string& message)
    : std::runtime_error(message) {}

void AccessPlanner::add_role(const std::string& name, const std::string& parent) {
    if (!parent.empty() && roles_.find(parent) == roles_.end()) {
        throw AccessPlannerError("unknown role: " + parent);
    }
    if (roles_.find(name) != roles_.end()) {
        throw AccessPlannerError("role already exists: " + name);
    }
    RoleInfo info;
    info.parent = parent;
    roles_[name] = info;
}

void AccessPlanner::grant_permission(const std::string& role, const std::string& permission) {
    if (roles_.find(role) == roles_.end()) {
        throw AccessPlannerError("unknown role: " + role);
    }
    std::vector<std::string>& perms = grants_[role];
    if (std::find(perms.begin(), perms.end(), permission) != perms.end()) {
        throw AccessPlannerError("permission already granted: " + permission);
    }
    perms.push_back(permission);
}

void AccessPlanner::add_user(const std::string& name, const std::string& role, int max_hours) {
    if (roles_.find(role) == roles_.end()) {
        throw AccessPlannerError("unknown role: " + role);
    }
    if (users_.find(name) != users_.end()) {
        throw AccessPlannerError("user already exists: " + name);
    }
    if (max_hours < 0 || max_hours > 24) {
        throw AccessPlannerError("invalid hour limit");
    }
    UserInfo info;
    info.role = role;
    info.max_hours = max_hours;
    users_[name] = info;
}

void AccessPlanner::set_max_hours(const std::string& user, int max_hours) {
    if (users_.find(user) == users_.end()) {
        throw AccessPlannerError("unknown user: " + user);
    }
    if (max_hours < 0 || max_hours > 24) {
        throw AccessPlannerError("invalid hour limit");
    }
    users_[user].max_hours = max_hours;
}

bool AccessPlanner::role_has_permission(const std::string& role,
                                        const std::string& permission) const {
    std::string current = role;
    while (true) {
        std::map<std::string, std::vector<std::string>>::const_iterator it = grants_.find(current);
        if (it != grants_.end() &&
            std::find(it->second.begin(), it->second.end(), permission) != it->second.end()) {
            return true;
        }
        std::map<std::string, RoleInfo>::const_iterator rit = roles_.find(current);
        if (rit == roles_.end() || rit->second.parent.empty()) {
            return false;
        }
        current = rit->second.parent;
    }
}

bool AccessPlanner::has_permission(const std::string& user, const std::string& permission) const {
    std::map<std::string, UserInfo>::const_iterator it = users_.find(user);
    if (it == users_.end()) {
        throw AccessPlannerError("unknown user: " + user);
    }
    return role_has_permission(it->second.role, permission);
}

std::vector<std::string> AccessPlanner::users_with_permission(
    const std::string& permission) const {
    std::vector<std::string> result;
    for (std::map<std::string, UserInfo>::const_iterator it = users_.begin();
         it != users_.end(); ++it) {
        if (role_has_permission(it->second.role, permission)) {
            result.push_back(it->first);
        }
    }
    // users_ is a std::map keyed by name, so results are already ascending.
    return result;
}

void AccessPlanner::add_task(const std::string& id, const std::string& permission,
                             int start_hour, int end_hour, int min_staff, int priority) {
    for (std::size_t i = 0; i < tasks_.size(); ++i) {
        if (tasks_[i].id == id) {
            throw AccessPlannerError("task already exists: " + id);
        }
    }
    if (start_hour < 0 || start_hour >= end_hour || end_hour > 24) {
        throw AccessPlannerError("invalid time range");
    }
    if (min_staff < 1) {
        throw AccessPlannerError("invalid staff count");
    }
    TaskInfo info;
    info.id = id;
    info.permission = permission;
    info.start_hour = start_hour;
    info.end_hour = end_hour;
    info.min_staff = min_staff;
    info.priority = priority;
    tasks_.push_back(info);
}

Schedule AccessPlanner::plan() const {
    Schedule schedule;

    // Order tasks by priority descending, ties by id ascending.
    std::vector<TaskInfo> ordered = tasks_;
    std::sort(ordered.begin(), ordered.end(), [](const TaskInfo& a, const TaskInfo& b) {
        if (a.priority != b.priority) {
            return a.priority > b.priority;
        }
        return a.id < b.id;
    });

    // Per-user mutable scheduling state.
    struct UserState {
        std::string role;
        int remaining_hours;
        std::vector<std::pair<int, int> > windows;  // assigned [start, end) windows
    };
    std::map<std::string, UserState> state;
    for (std::map<std::string, UserInfo>::const_iterator it = users_.begin();
         it != users_.end(); ++it) {
        UserState us;
        us.role = it->second.role;
        us.remaining_hours = it->second.max_hours;
        state[it->first] = us;
    }

    for (std::size_t t = 0; t < ordered.size(); ++t) {
        const TaskInfo& task = ordered[t];
        int duration = task.end_hour - task.start_hour;

        // Collect eligible users in ascending lexicographic order (map order).
        std::vector<std::string> picked;
        for (std::map<std::string, UserState>::iterator it = state.begin();
             it != state.end() && static_cast<int>(picked.size()) < task.min_staff; ++it) {
            if (!role_has_permission(it->second.role, task.permission)) {
                continue;
            }
            if (it->second.remaining_hours < duration) {
                continue;
            }
            bool overlaps = false;
            for (std::size_t w = 0; w < it->second.windows.size(); ++w) {
                const std::pair<int, int>& win = it->second.windows[w];
                if (task.start_hour < win.second && win.first < task.end_hour) {
                    overlaps = true;
                    break;
                }
            }
            if (overlaps) {
                continue;
            }
            picked.push_back(it->first);
        }

        if (static_cast<int>(picked.size()) < task.min_staff) {
            schedule.unscheduled.push_back(task.id);
        } else {
            for (std::size_t p = 0; p < picked.size(); ++p) {
                UserState& us = state[picked[p]];
                us.remaining_hours -= duration;
                us.windows.push_back(std::make_pair(task.start_hour, task.end_hour));
            }
            schedule.assignments[task.id] = picked;
        }
    }

    return schedule;
}

}  // namespace access_roles_planner
```

Notes on the implementation:

- **Error ordering** is followed exactly as specified (e.g. `add_role` checks the parent before the duplicate-name check; `add_user` checks role, then name, then hour limit).
- **Permission inheritance** walks up the role chain at query time, so later grants take effect for existing users immediately, and permissions never flow downward.
- **`users_with_permission`** iterates the `std::map` of users (already name-ordered) and never throws.
- **`plan()`** is `const`: it copies the tasks, sorts by (priority desc, id asc), and works on a separate per-user state map so the planner itself is untouched and repeated calls give identical results.
- **Overlap** uses the half-open predicate `a < d && c < b`, so touching windows (e.g. `[9,12)` and `[12,14)`) don't conflict, and scheduling is all-or-nothing per task.

