#include <map>
#include <string>
#include <utility>
#include <vector>

namespace drawing_history_validator {

bool operator==(const Problem& lhs, const Problem& rhs) {
    return lhs.line == rhs.line
        && lhs.type == rhs.type
        && lhs.severity == rhs.severity
        && lhs.message == rhs.message;
}

bool operator!=(const Problem& lhs, const Problem& rhs) {
    return !(lhs == rhs);
}

namespace {

// A syntactically valid integer token: optional single leading '-'
// followed by one or more digits, nothing else.
bool is_integer_token(const std::string& token) {
    if (token.empty()) {
        return false;
    }
    std::size_t start = 0;
    if (token[0] == '-') {
        start = 1;
    }
    if (start == token.size()) {
        return false;
    }
    for (std::size_t i = start; i < token.size(); ++i) {
        if (token[i] < '0' || token[i] > '9') {
            return false;
        }
    }
    return true;
}

// Value of a syntactically valid integer token, saturated on overflow.
// Saturated values are always far out of every legal range, and positions
// never influence any rule, so saturation is unobservable.
long long parse_value(const std::string& token) {
    bool negative = false;
    std::size_t start = 0;
    if (token[0] == '-') {
        negative = true;
        start = 1;
    }
    long long value = 0;
    const std::size_t digits = token.size() - start;
    if (digits > 18) {
        value = 9223372036854775807LL;  // saturate (largest 18-digit value fits)
    } else {
        for (std::size_t i = start; i < token.size(); ++i) {
            value = value * 10 + (token[i] - '0');
        }
    }
    return negative ? -value : value;
}

// Split on arbitrary runs of whitespace; leading/trailing whitespace ignored.
std::vector<std::string> tokenize(const std::string& line) {
    std::vector<std::string> tokens;
    std::size_t i = 0;
    while (i < line.size()) {
        while (i < line.size()
               && std::isspace(static_cast<unsigned char>(line[i]))) {
            ++i;
        }
        const std::size_t start = i;
        while (i < line.size()
               && !std::isspace(static_cast<unsigned char>(line[i]))) {
            ++i;
        }
        if (i > start) {
            tokens.push_back(line.substr(start, i - start));
        }
    }
    return tokens;
}

struct Operation {
    enum class Kind { add, del, move };
    Kind kind;
    int id;
    long long x;  // x position, or dx for a move
    long long y;  // y position, or dy for a move
};

constexpr std::size_t kMaxStackSize = 10;

}  // namespace

std::vector<Problem> validate(const std::vector<std::string>& log_lines) {
    std::vector<Problem> problems;

    std::map<int, std::pair<long long, long long>> canvas;  // id -> (x, y)
    std::deque<Operation> undo_stack;
    std::deque<Operation> redo_stack;

    auto report = [&](std::size_t line, ProblemType type, Severity severity,
                      const std::string& message) {
        problems.push_back(Problem{line, type, severity, message});
    };

    auto push_undo = [&](Operation op) {
        undo_stack.push_back(op);
        if (undo_stack.size() > kMaxStackSize) {
            undo_stack.pop_front();  // silently discard the oldest
        }
        redo_stack.clear();
    };

    auto push_redo = [&](Operation op) {
        redo_stack.push_back(op);
        if (redo_stack.size() > kMaxStackSize) {
            redo_stack.pop_front();  // symmetric cap
        }
    };

    // Apply an operation to the canvas.
    auto apply = [&](const Operation& op) {
        switch (op.kind) {
            case Operation::Kind::add:
                canvas[op.id] = {op.x, op.y};
                break;
            case Operation::Kind::del:
                canvas.erase(op.id);
                break;
            case Operation::Kind::move: {
                auto it = canvas.find(op.id);
                if (it != canvas.end()) {
                    it->second.first += op.x;
                    it->second.second += op.y;
                }
                break;
            }
        }
    };

    // Apply the inverse of an operation to the canvas.
    auto invert = [&](const Operation& op) {
        switch (op.kind) {
            case Operation::Kind::add:
                canvas.erase(op.id);
                break;
            case Operation::Kind::del:
                canvas[op.id] = {op.x, op.y};
                break;
            case Operation::Kind::move: {
                auto it = canvas.find(op.id);
                if (it != canvas.end()) {
                    it->second.first -= op.x;
                    it->second.second -= op.y;
                }
                break;
            }
        }
    };

    for (std::size_t i = 0; i < log_lines.size(); ++i) {
        const std::size_t line_no = i + 1;

        const std::vector<std::string> tokens = tokenize(log_lines[i]);
        if (tokens.empty()) {
            continue;  // blank line: skipped silently
        }

        const std::string& cmd = tokens[0];

        // 1. Unknown command.
        const bool known = cmd == "add" || cmd == "del" || cmd == "move"
            || cmd == "undo" || cmd == "redo";
        if (!known) {
