// A syntactically valid integer token: optional single leading '-'
// followed by one or more digits, nothing else.
bool is_integer_token(const std::string& token) {
    if (token.empty()) {
        return false;
    }
    std::size_t start = 0;
    if (token[0] == '-') {
        start = 1;
    }
    if (start == token.size()) {
        return false;
    }
    for (std::size_t i = start; i < token.size(); ++i) {
        if (token[i] < '0' || token[i] > '9') {
            return false;
        }
    }
    return true;
}

// Value of a syntactically valid integer token, saturated on overflow.
// Saturated values are always far out of every legal range, and positions
// never influence any rule, so saturation is unobservable.
long long parse_value(const std::string& token) {
    bool negative = false;
    std::size_t start = 0;
    if (token[0] == '-') {
        negative = true;
        start = 1;
    }
    long long value = 0;
    const std::size_t digits = token.size() - start;
    if (digits > 18) {
        value = 9223372036854775807LL;  // saturate (largest 18-digit value fits)
    } else {
        for (std::size_t i = start; i < token.size(); ++i) {
            value = value * 10 + (token[i] - '0');
        }
    }
    return negative ? -value : value;
}

// Split on arbitrary runs of whitespace; leading/trailing whitespace ignored.
std::vector<std::string> tokenize(const std::string& line) {
    std::vector<std::string> tokens;
    std::size_t i = 0;
    while (i < line.size()) {
        while (i < line.size()
               && std::isspace(static_cast<unsigned char>(line[i]))) {
            ++i;
        }
        const std::size_t start = i;
        while (i < line.size()
               && !std::isspace(static_cast<unsigned char>(line[i]))) {
            ++i;
        }
        if (i > start) {
            tokens.push_back(line.substr(start, i - start));
        }
    }
    return tokens;
}

