        if (c == ',') {
            fields.push_back(current);
            current.clear();
        } else {
            current.push_back(c);
        }
    }
    // Always emit the final field, even when it is empty: a trailing
    // comma means "one more (empty) field", e.g. "a,b,c,d," has 5 fields.
    fields.push_back(current);
    return fields;
}

