```cpp
#include "stock_portfolio_report.h"

#include <iomanip>
#include <sstream>

namespace stock_portfolio_report {

namespace {

bool is_valid_symbol(const std::string& symbol)
{
    if (symbol.empty() || symbol.size() > 5) {
        return false;
    }
    for (char c : symbol) {
        if (c < 'A' || c > 'Z') {
            return false;
        }
    }
    return true;
}

std::string pad_left(const std::string& text, std::size_t width)
{
    if (text.size() >= width) {
        return text;
    }
    return std::string(width - text.size(), ' ') + text;
}

std::string pad_right(const std::string& text, std::size_t width)
{
    if (text.size() >= width) {
        return text;
    }
    return text + std::string(width - text.size(), ' ');
}

} // namespace

std::string format_money(long long cents)
{
    bool negative = cents < 0;
    unsigned long long magnitude = negative
        ? static_cast<unsigned long long>(-(cents + 1)) + 1ULL
        : static_cast<unsigned long long>(cents);

    unsigned long long dollars = magnitude / 100ULL;
    unsigned long long remainder = magnitude % 100ULL;

    std::string digits;
    if (dollars == 0) {
        digits = "0";
    } else {
        while (dollars > 0) {
            digits.push_back(static_cast<char>('0' + dollars % 10ULL));
            dollars /= 10ULL;
        }
        // Reverse the digits.
        for (std::size_t i = 0, j = digits.size(); i < j / 2; ++i) {
            char tmp = digits[i];
            digits[i] = digits[j - 1 - i];
            digits[j - 1 - i] = tmp;
        }
    }

    std::string result;
    if (negative) {
        result.push_back('-');
    }
    result.push_back('$');
    result += digits;
    result.push_back('.');
    result.push_back(static_cast<char>('0' + (remainder / 10ULL) % 10ULL));
    result.push_back(static_cast<char>('0' + remainder % 10ULL));
    return result;
}

void Portfolio::buy(const std::string& symbol, int quantity, long long price_cents)
{
    if (!is_valid_symbol(symbol)) {
        throw InvalidSymbol("invalid symbol: " + symbol);
    }
    if (quantity <= 0) {
        throw InvalidQuantity("quantity must be positive: " + std::to_string(quantity));
    }
    if (price_cents <= 0) {
        throw InvalidPrice("price must be positive: " + std::to_string(price_cents));
    }

    Lot& lot = lots_[symbol];
    lot.shares += quantity;
    lot.cost_basis_cents += static_cast<long long>(quantity) * price_cents;
}

void Portfolio::sell(const std::string& symbol, int quantity, long long price_cents)
{
    if (!is_valid_symbol(symbol)) {
        throw InvalidSymbol("invalid symbol: " + symbol);
    }
    if (quantity <= 0) {
        throw InvalidQuantity("quantity must be positive: " + std::to_string(quantity));
    }
    if (price_cents <= 0) {
        throw InvalidPrice("price must be positive: " + std::to_string(price_cents));
    }

    auto it = lots_.find(symbol);
    const long long held = (it == lots_.end()) ? 0 : it->second.shares;
    if (quantity > held) {
        throw InsufficientShares("insufficient shares of " + symbol
            + ": have " + std::to_string(held)
            + ", selling " + std::to_string(quantity));
    }

    Lot& lot = it->second;
    const long long removed_cost = lot.cost_basis_cents * static_cast<long long>(quantity) / lot.shares;

    lot.realized_gains_cents += static_cast<long long>(quantity) * price_cents - removed_cost;
    lot.cost_basis_cents -= removed_cost;
    lot.shares -= quantity;
    if (lot.shares == 0) {
        lot.cost_basis_cents = 0;
    }
}

long long Portfolio::position(const std::string& symbol) const
{
    auto it = lots_.find(symbol);
    return (it == lots_.end()) ? 0 : it->second.shares;
}

long long Portfolio::average_cost_cents(const std::string& symbol) const
{
    auto it = lots_.find(symbol);
    if (it == lots_.end() || it->second.shares == 0) {
        return 0;
    }
    return it->second.cost_basis_cents / it->second.shares;
}

long long Portfolio::realized_gains_cents(const std::string& symbol) const
{
    auto it = lots_.find(symbol);
    return (it == lots_.end()) ? 0 : it->second.realized_gains_cents;
}

long long Portfolio::total_realized_gains_cents() const
{
    long long total = 0;
    for (const auto& entry : lots_) {
        total += entry.second.realized_gains_cents;
    }
    return total;
}

std::string Portfolio::report() const
{
    std::string text = "PORTFOLIO REPORT\n";
    text += "----------------\n";

    // std::map iterates in ascending lexicographic (byte) order.
    for (const auto& entry : lots_) {
        const Lot& lot = entry.second;
        if (lot.shares == 0 && lot.realized_gains_cents == 0) {
            continue;
        }

        text += pad_right(entry.first, 6);
        text += pad_left(std::to_string(lot.shares), 6);
        text += pad_left(format_money(average_cost_cents(entry.first)), 12);
        text += pad_left(format_money(lot.realized_gains_cents), 12);
        text += "\n";
    }

    text += "TOTAL REALIZED: ";
    text += format_money(total_realized_gains_cents());
    text += "\n";

    return text;
}

} // namespace stock_portfolio_report
