#include "donation_matching_migrator.h"

#include <algorithm>
#include <cmath>
#include <cctype>
#include <string>
#include <unordered_map>
#include <vector>

namespace donation_matching_migrator {

namespace {

double round_to_cents(double v) {
    return std::round(v * 100.0) / 100.0;
}

bool is_finite_positive(double v) {
    return std::isfinite(v) && v > 0.0;
}

bool all_digits(const std::string& s, std::size_t from) {
    for (std::size_t i = from; i < s.size(); ++i) {
        if (!std::isdigit(static_cast<unsigned char>(s[i]))) {
            return false;
        }
    }
    return true;
}

bool is_valid_campaign_id(const std::string& id) {
    return id.size() >= 5 && id.compare(0, 2, "C-") == 0 &&
           all_digits(id, 2);
}

bool is_valid_donor_id(const std::string& id) {
    return id.size() >= 6 && id.compare(0, 2, "D-") == 0 &&
           all_digits(id, 2);
}

bool has_non_whitespace(const std::string& name) {
    for (char c : name) {
        if (!std::isspace(static_cast<unsigned char>(c))) {
            return true;
        }
    }
    return false;
}

bool is_leap_year(int year) {
    return (year % 4 == 0) && (year % 100 != 0 || year % 400 == 0);
}

int days_in_month(int year, int month) {
    static const int days[] = {31, 28, 31, 30, 31, 30,
                               31, 31, 30, 31, 30, 31};
    if (month == 2 && is_leap_year(year)) {
        return 29;
    }
    return days[month - 1];
}

// Parses "YYYY-MM-DD"; returns true iff the format is exact and the
// date exists in the proleptic Gregorian calendar (years 0000-9999).
bool is_valid_date(const std::string& date) {
    if (date.size() != 10) {
        return false;
    }
    if (date[4] != '-' || date[7] != '-') {
        return false;
    }
    for (std::size_t i = 0; i < date.size(); ++i) {
        if (i == 4 || i == 7) {
            continue;
        }
        if (!std::isdigit(static_cast<unsigned char>(date[i]))) {
            return false;
        }
    }

    const int year = std::stoi(date.substr(0, 4));
    const int month = std::stoi(date.substr(5, 2));
    const int day = std::stoi(date.substr(8, 2));

    if (year < 0 || year > 9999) {
        return false;
    }
    if (month < 1 || month > 12) {
        return false;
    }
    return day >= 1 && day <= days_in_month(year, month);
}

} // namespace

MigrationError::MigrationError(const std::string& message)
    : std::runtime_error(message) {
}

CampaignV2 migrate(const CampaignV1& campaign, const MigrationOptions& options) {
    // 1. Currency.
    if (options.currency.size() != 3) {
        throw MigrationError("invalid currency: " + options.currency);
    }
    for (char c : options.currency) {
        if (c < 'A' || c > 'Z') {
            throw MigrationError("invalid currency: " + options.currency);
        }
    }

    // 2. Campaign id.
    if (!is_valid_campaign_id(campaign.campaign_id)) {
        throw MigrationError("invalid campaign id: " + campaign.campaign_id);
    }

    // 3. Nonprofit name.
    if (!has_non_whitespace(campaign.nonprofit_name)) {
        throw MigrationError("empty nonprofit name");
    }

    // 4. Match ratio.
    if (!is_finite_positive(campaign.match_ratio)) {
        throw MigrationError("invalid match ratio");
    }

    // 5. Total match cap.
    if (!is_finite_positive(campaign.total_match_cap)) {
        throw MigrationError("invalid total match cap");
    }

    // 6. Per-donor cap.
    if (!std::isfinite(campaign.per_donor_cap) || campaign.per_donor_cap < 0.0) {
        throw MigrationError("invalid per-donor cap");
    }
    if (campaign.per_donor_cap > campaign.total_match_cap) {
        throw MigrationError("per-donor cap exceeds total match cap");
    }

    // 7. Start date.
    if (!is_valid_date(campaign.start_date)) {
        throw MigrationError("invalid start date: " + campaign.start_date);
    }

    // 8. End date.
    if (!is_valid_date(campaign.end_date)) {
        throw MigrationError("invalid end date: " + campaign.end_date);
    }

    // 9. Ordering (string comparison is correct for this fixed format).
    if (campaign.end_date < campaign.start_date) {
        throw MigrationError("end date before start date");
    }

    // 10. Pledges, in order.
    for (const PledgeV1& pledge : campaign.pledges) {
        if (!is_valid_donor_id(pledge.donor_id)) {
            throw MigrationError("invalid donor id: " + pledge.donor_id);
        }
        if (!is_finite_positive(pledge.amount)) {
            throw MigrationError("invalid pledge amount for donor: " +
                                 pledge.donor_id);
        }
    }

    // --- Replay the matching rules over the pledges, in order. ---

    // Per-donor running totals, plus first-appearance ordering.
    std::vector<std::string> donor_order;
    std::unordered_map<std::string, std::size_t> donor_index;
    std::vector<double> donor_donated; // raw sums
    std::vector<double> donor_matched; // sums of cent-rounded matches

    // Auto-register a donor on first appearance; returns its index.
    auto donor_slot = [&donor_order, &donor_index, &donor_donated,
                       &donor_matched](const std::string& donor_id) {
        auto it = donor_index.find(donor_id);
        if (it != donor_index.end()) {
            return it->second;
        }
        const std::size_t index = donor_order.size();
        donor_index.emplace(donor_id, index);
        donor_order.push_back(donor_id);
        donor_donated.push_back(0.0);
        donor_matched.push_back(0.0);
        return index;
    };

    const double per_donor_cap_cents =
        campaign.per_donor_cap > 0.0 ? round_to_cents(campaign.per_donor_cap)
                                     : 0.0;
    double remaining_budget = round_to_cents(campaign.total_match_cap);

    for (const PledgeV1& pledge : campaign.pledges) {
        const std::size_t slot = donor_slot(pledge.donor_id);
        donor_donated[slot] += pledge.amount;

        const double proposed = pledge.amount * campaign.match_ratio;

        double allowance = remaining_budget;
        if (campaign.per_donor_cap > 0.0) {
            const double donor_room =
                per_donor_cap_cents - donor_matched[slot];
            allowance = std::min(allowance, donor_room);
        }
        allowance = std::min(allowance, proposed);

        double match = round_to_cents(allowance);
        if (match < 0.0) {
            match = 0.0; // defensive clamp
        }

        donor_matched[slot] += match;
        remaining_budget -= match;
    }

    // --- Build the result. ---

    CampaignV2 result;
    result.campaign_id = campaign.campaign_id;
    result.nonprofit_name = campaign.nonprofit_name;
    result.currency = options.currency;
    result.match_ratio = campaign.match_ratio;
    result.total_match_cap = campaign.total_match_cap;
    result.per_donor_cap = campaign.per_donor_cap;
    result.start_date = campaign.start_date;
    result.end_date = campaign.end_date;

    result.pledges.reserve(donor_order.size());
    for (std::size_t i = 0; i < donor_order.size(); ++i) {
        PledgeV2 pledge;
        pledge.donor_id = donor_order[i];
        pledge.donated_amount = round_to_cents(donor_donated[i]);
        pledge.matched_amount = round_to_cents(donor_matched[i]);
        result.pledges.push_back(std::move(pledge));
    }

    double remaining_cap = round_to_cents(remaining_budget);
    if (remaining_cap < 0.0) {
        remaining_cap = 0.0;
    }
    if (remaining_cap > 0.0 && remaining_cap < 0.005) {
        remaining_cap = 0.0;
    }
    result.remaining_cap = remaining_cap;

    result.matched_total =
        round_to_cents(round_to_cents(campaign.total_match_cap) -
                       result.remaining_cap);
    result.fully_subscribed = (result.remaining_cap == 0.0);

    return result;
}

} // namespace donation_matching_migrator
