#include "address_normalization_engine.h"

#include <cctype>
#include <map>
#include <set>
#include <string>
#include <vector>

namespace address_normalization_engine {

namespace {

// ---------- string helpers ----------

std::string collapse(const std::string& input) {
    std::string out;
    out.reserve(input.size());
    bool pending_space = false;
    for (std::string::size_type i = 0; i < input.size(); ++i) {
        const unsigned char c = static_cast<unsigned char>(input[i]);
        if (std::isspace(c) != 0) {
            if (!out.empty()) {
                pending_space = true;
            }
        } else {
            if (pending_space) {
                out.push_back(' ');
                pending_space = false;
            }
            out.push_back(static_cast<char>(c));
        }
    }
    return out;
}

char upper_char(char c) {
    return static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
}

char lower_char(char c) {
    return static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
}

std::string to_upper(const std::string& s) {
    std::string out(s);
    for (std::string::size_type i = 0; i < out.size(); ++i) {
        out[i] = upper_char(out[i]);
    }
    return out;
}

std::string to_lower(const std::string& s) {
    std::string out(s);
    for (std::string::size_type i = 0; i < out.size(); ++i) {
        out[i] = lower_char(out[i]);
    }
    return out;
}

bool is_ascii_letter(char c) {
    return std::isalpha(static_cast<unsigned char>(c)) != 0;
}

bool is_ascii_digit(char c) {
    return std::isdigit(static_cast<unsigned char>(c)) != 0;
}

bool all_digits(const std::string& s) {
    if (s.empty()) {
        return false;
    }
    for (std::string::size_type i = 0; i < s.size(); ++i) {
        if (!is_ascii_digit(s[i])) {
            return false;
        }
    }
    return true;
}

std::vector<std::string> split_tokens(const std::string& s) {
    std::vector<std::string> tokens;
    std::string::size_type start = 0;
    while (start < s.size()) {
        std::string::size_type end = s.find(' ', start);
        if (end == std::string::npos) {
            end = s.size();
        }
        if (end > start) {
            tokens.push_back(s.substr(start, end - start));
        }
        start = (end == s.size()) ? end : end + 1;
    }
    return tokens;
}

// ---------- country handling ----------

bool is_supported_code(const std::string& upper_code) {
    static const std::set<std::string> kSupported = {
        "AT", "CH", "DE", "FR", "NL", "US"
    };
    return kSupported.count(upper_code) > 0;
}

std::string resolve_country(const std::string& country_code,
                            const std::string& fallback) {
    const std::string cc = collapse(country_code);
    if (cc.empty()) {
        return fallback;
    }
    if (cc.size() != 2 || !is_ascii_letter(cc[0]) || !is_ascii_letter(cc[1])) {
        throw AddressError("invalid country code: " + cc);
    }
    const std::string upper = to_upper(cc);
    if (!is_supported_code(upper)) {
        throw AddressError("unsupported country code: " + upper);
    }
    return upper;
}

// ---------- title casing ----------

const std::set<std::string>& connectors() {
    static const std::set<std::string> kConnectors = {
        "am", "an", "auf", "and", "de", "den", "der", "im", "in",
        "of", "the", "und", "van", "von", "zum", "zur"
    };
    return kConnectors;
}

std::string title_case(const std::vector<std::string>& tokens) {
    std::string out;
    for (std::vector<std::string>::size_type i = 0; i < tokens.size(); ++i) {
        if (i > 0) {
            out.push_back(' ');
        }
        std::string word = to_lower(tokens[i]);
        if (i == 0 || connectors().count(word) == 0) {
            if (!word.empty()) {
                word[0] = upper_char(word[0]);
            }
        }
        out += word;
    }
    return out;
}

// ---------- street ----------

const std::map<std::string, std::string>& abbreviations() {
    static const std::map<std::string, std::string> kAbbreviations = {
        {"st", "street"}, {"rd", "road"},   {"ave", "avenue"},
        {"blvd", "boulevard"}, {"dr", "drive"}, {"ln", "lane"},
        {"pl", "place"}, {"sq", "square"},  {"ter", "terrace"},
        {"ct", "court"}
    };
    return kAbbreviations;
}

std::string normalize_street(const std::string& input) {
    std::string s = collapse(input);
    if (s.empty()) {
        throw AddressError("missing street");
    }
    for (std::string::size_type i = 0; i < s.size(); ++i) {
        if (is_ascii_digit(s[i])) {
            throw AddressError("street must not contain digits: " + s);
        }
    }
    if (s[s.size() - 1] == '.') {
        s.erase(s.size() - 1);
    }
    std::vector<std::string> tokens = split_tokens(s);
    if (!tokens.empty()) {
        const std::string last_lower = to_lower(tokens.back());
        std::map<std::string, std::string>::const_iterator it =
            abbreviations().find(last_lower);
        if (it != abbreviations().end()) {
            tokens.back() = it->second;
        }
    }
    return title_case(tokens);
}

// ---------- house number ----------

std::string normalize_house_number(const std::string& input) {
    const std::string hn = collapse(input);
    if (hn.empty()) {
        throw AddressError("missing house number");
    }

    const AddressError invalid("invalid house number: " + hn);

    std::string::size_type i = 0;
    while (i < hn.size() && is_ascii_digit(hn[i])) {
        ++i;
    }
    if (i < 1 || i > 4) {
        throw invalid;
    }
    const std::string digits = hn.substr(0, i);

    std::string letters;
    if (i < hn.size()) {
        if (hn[i] != ' ') {
            throw invalid;
        }
        std::string::size_type j = i + 1;
        while (j < hn.size() && is_ascii_letter(hn[j])) {
            ++j;
        }
        const std::string::size_type letter_count = j - (i + 1);
        if (letter_count < 1 || letter_count > 2 || j != hn.size()) {
            throw invalid;
        }
        letters = to_upper(hn.substr(i + 1, letter_count));
    }
    return digits + letters;
}

// ---------- postal code ----------

std::string normalize_postal_code(const std::string& input,
                                  const std::string& cc) {
    const std::string pc = collapse(input);
    if (pc.empty()) {
        throw AddressError("missing postal code");
    }

    const AddressError invalid("invalid postal code for " + cc + ": " + pc);

    if (cc == "DE" || cc == "FR") {
        if (pc.size() == 5 && all_digits(pc)) {
            return pc;
        }
    } else if (cc == "AT" || cc == "CH") {
        if (pc.size() == 4 && all_digits(pc)) {
            return pc;
        }
    } else if (cc == "NL") {
        if (pc.size() == 6 || pc.size() == 7) {
            const std::string digits = pc.substr(0, 4);
            std::string letters;
            if (pc.size() == 6) {
                letters = pc.substr(4, 2);
            } else {
                if (pc[4] != ' ') {
                    throw invalid;
                }
                letters = pc.substr(5, 2);
            }
            if (all_digits(digits) && is_ascii_letter(letters[0]) &&
                is_ascii_letter(letters[1])) {
                return digits + " " + to_upper(letters);
            }
        }
    } else if (cc == "US") {
        if (pc.size() == 5 && all_digits(pc)) {
            return pc;
        }
        if (pc.size() == 10 && pc[5] == '-' && all_digits(pc.substr(0, 5)) &&
            all_digits(pc.substr(6, 4))) {
            return pc;
        }
    }
    throw invalid;
}

// ---------- city ----------

std::string normalize_city(const std::string& input) {
    const std::string city = collapse(input);
    if (city.empty()) {
        throw AddressError("missing city");
    }
    return title_case(split_tokens(city));
}

} // namespace

AddressError::AddressError(const std::string& message)
    : std::runtime_error(message) {}

std::string NormalizedAddress::to_line() const {
    return street + " " + house_number + ", " + postal_code + " " + city +
           ", " + country_code;
}

AddressNormalizer::AddressNormalizer() : default_country_("DE") {}

void AddressNormalizer::set_default_country(const std::string& country_code) {
    const std::string cc = collapse(country_code);
    if (cc.empty()) {
        throw AddressError("missing country code");
    }
    if (cc.size() != 2 || !is_ascii_letter(cc[0]) || !is_ascii_letter(cc[1])) {
        throw AddressError("invalid country code: " + cc);
    }
    const std::string upper = to_upper(cc);
    if (!is_supported_code(upper)) {
        throw AddressError("unsupported country code: " + upper);
    }
    default_country_ = upper;
}

const std::string& AddressNormalizer::default_country() const {
    return default_country_;
}

bool AddressNormalizer::is_supported_country(const std::string& country_code) {
    const std::string cc = collapse(country_code);
    if (cc.size() != 2 || !is_ascii_letter(cc[0]) || !is_ascii_letter(cc[1])) {
        return false;
    }
    return is_supported_code(to_upper(cc));
}

NormalizedAddress AddressNormalizer::normalize(
    const std::string& street_line,
    const std::string& house_number,
    const std::string& postal_code,
    const std::string& city,
    const std::string& country_code) const {

    NormalizedAddress result;

    // Step 1: country
    result.country_code = resolve_country(country_code, default_country_);

    // Step 2: street
    result.street = normalize_street(street_line);

    // Step 3: house number
    result.house_number = normalize_house_number(house_number);

    // Step 4: postal code
    result.postal_code = normalize_postal_code(postal_code,
                                               result.country_code);

    // Step 5: city
    result.city = normalize_city(city);

    return result;
}

} // namespace address_normalization_engine
