// The minimum version in which a canonical key is allowed.
// name/level/hp -> 1, mana/xp -> 2, pos_x/pos_y -> 3.
int min_version_for_index(int index) {
    if (index <= 2) return 1;
    if (index <= 4) return 2;
    return 3;
}

// Splits the input into lines. A trailing '\n' does not start a new line,
// but an empty line in the middle of the file does count. A single '\r'
// immediately preceding a line break (or ending the input) is ignored.
std::vector<std::string> split_lines(const std::string& text) {
    std::vector<std::string> lines;
    std::string current;
    for (char c : text) {
        if (c == '\n') {
            lines.push_back(current);
            current.clear();
        } else {
            current.push_back(c);
        }
    }
    // A trailing '\n' does not start a new line, so the (empty) remainder is
    // only appended when the input does not end with '\n'. Completely empty
    // input still produces a single (empty) line so the header check can
    // report line 1.
    if (text.empty() || text.back() != '\n') {
        lines.push_back(current);
    }
    // Every line now either precedes a '\n' or ends the input, so a single
    // trailing '\r' on any line is ignored.
    for (std::string& line : lines) {
        if (!line.empty() && line.back() == '\r') {
            line.pop_back();
        }
    }
    return lines;
}

// Parses a value of one or more digits (accumulating in long long, saturated
// once it is clearly beyond any supported version number).
long long parse_version_number(const std::string& token) {
    long long value = 0;
    for (char c : token) {
        if (value <= 1000000000LL) {
            value = value * 10 + (c - '0');
        }
    }
    return value;
}

// Validates and parses an integer value per the key's rules. Returns false if
// the value is not a valid int (bad characters, wrong sign, out of range).
bool parse_int_value(const std::string& value, bool allow_negative, int& out) {
    std::size_t i = 0;
    bool negative = false;
    if (allow_negative && !value.empty() && value[0] == '-') {
        negative = true;
        i = 1;
    }
    if (i >= value.size()) {
        return false;
    }
    long long acc = 0;
    for (; i < value.size(); ++i) {
        char c = value[i];
        if (c < '0' || c > '9') {
            return false;
        }
        acc = acc * 10 + (c - '0');
        // Anything beyond 2^31 cannot fit in an int (2^31 itself is only
        // valid as INT_MIN); bailing out early also prevents overflow.
        if (acc > 2147483648LL) {
            return false;
        }
    }
    const long long result = negative ? -acc : acc;
    if (result < -2147483648LL || result > 2147483647LL) {
        return false;
    }
    out = static_cast<int>(result);
    return true;
}

int clamp_to_int_max(long long value) {
    return value > 2147483647LL ? 2147483647 : static_cast<int>(value);
}

} // namespace

SaveData load_save(const std::string& text) {
    const std::vector<std::string> lines = split_lines(text);

    // ---- Header (line 1) ----
    const std::string& header = lines[0];
    const std::string kPrefix = "SAVEFILE ";
    if (header.rfind(kPrefix, 0) != 0) {
        throw SaveParseError(1, "missing header");
    }
    const std::string token = header.substr(kPrefix.size());
    bool all_digits = !token.empty();
    for (char c : token) {
        if (c < '0' || c > '9') {
            all_digits = false;
            break;
        }
    }
    if (!all_digits) {
        throw SaveParseError(1, "invalid version '" + token + "'");
    }
    const long long version = parse_version_number(token);
    if (version != 1 && version != 2 && version != 3) {
        throw SaveParseError(1, "unsupported version " + std::to_string(version));
    }

    // ---- Key/value lines ----
    SaveData data;
    bool seen[kKeyCount] = {false, false, false, false, false, false, false};

    for (std::size_t i = 1; i < lines.size(); ++i) {
        const std::string& line = lines[i];
        const int line_number = static_cast<int>(i) + 1;
        if (line.empty()) {
            continue;
        }

        const std::size_t eq = line.find('=');
        if (eq == std::string::npos) {
            throw SaveParseError(line_number,
                                 "expected key=value, got '" + line + "'");
        }
        const std::string key = line.substr(0, eq);
        const std::string value = line.substr(eq + 1);

        const int key_index = index_of_key(key);
        if (key_index < 0 || min_version_for_index(key_index) > version) {
            throw SaveParseError(line_number, "unknown key '" + key + "'");
        }
        if (seen[key_index]) {
            throw SaveParseError(line_number, "duplicate key '" + key + "'");
        }
        seen[key_index] = true;

        if (key_index == 0) { // name
            if (value.empty()) {
                throw SaveParseError(line_number, "empty value for 'name'");
            }
            data.name = value;
        } else {
            // pos_x and pos_y accept an optional leading '-'.
            const bool allow_negative =
                (key == "pos_x" || key == "pos_y");
            int parsed = 0;
            if (!parse_int_value(value, allow_negative, parsed)) {
                throw SaveParseError(line_number,
                                     "invalid integer '" + value + "' for '" + key + "'");
            }
            if (key == "level") data.level = parsed;
            else if (key == "hp") data.hp = parsed;
            else if (key == "mana") data.mana = parsed;
            else if (key == "xp") data.xp = parsed;
            else if (key == "pos_x") data.pos_x = parsed;
            else data.pos_y = parsed;
        }
    }

    // ---- Whole-file check: all allowed keys must be present ----
    const int total_lines = static_cast<int>(lines.size());
    for (int k = 0; k < kKeyCount; ++k) {
        if (!seen[k] && min_version_for_index(k) <= version) {
            throw SaveParseError(total_lines + 1,
                                 std::string("missing key '") + kCanonicalKeys[k] + "'");
        }
    }

    // ---- Migration to version 3 ----
    if (version == 1) {
        data.mana = clamp_to_int_max(static_cast<long long>(data.level) * 5);
        data.xp = clamp_to_int_max(static_cast<long long>(data.level) * 100);
    }
    if (version < 3) {
        data.pos_x = 0;
        data.pos_y = 0;
    }

    return data;
}

} // namespace save_files_parser
```

## Summary of changes

1. **`allow_negative` now covers both `pos_x` and `pos_y`**, so `pos_y=-7` parses to `-7` as the spec requires (and `-2147483648` still works via the existing `INT_MIN` handling in `parse_int_value`).
2. **`split_lines` no longer appends the empty remainder after a trailing `'\n'`** (with an explicit empty-input case so `lines[0]` still exists for the header check). Now a file's line count — and therefore the missing-key report at *L + 1* — is identical whether or not the file ends with a newline, and empty lines in the middle still count toward *L* as required.

