#include "config_linter_migrator.h"

#include <algorithm>
#include <set>

namespace config_linter_migrator {
namespace {

bool is_ws(char c) { return c == ' ' || c == '\t' || c == '\r'; }

std::string trim(const std::string& s) {
    std::size_t b = 0;
    std::size_t e = s.size();
    while (b < e && is_ws(s[b])) ++b;
    while (e > b && is_ws(s[e - 1])) --e;
    return s.substr(b, e - b);
}

char lower_char(char c) {
    return (c >= 'A' && c <= 'Z') ? static_cast<char>(c - 'A' + 'a') : c;
}

std::string to_lower(const std::string& s) {
    std::string r = s;
    for (char& c : r) c = lower_char(c);
    return r;
}

std::vector<std::string> split_lines(const std::string& text) {
    std::vector<std::string> lines;
    std::string current;
    for (char c : text) {
        if (c == '\n') {
            lines.push_back(current);
            current.clear();
        } else {
            current.push_back(c);
        }
    }
    lines.push_back(current);
    return lines;
}

struct ParsedLine {
    enum class Kind { Blank, Comment, Header, Entry, Error };
    int number = 0;
    Kind kind = Kind::Blank;
    std::string name;   // section name for a valid header
    std::string key;    // trimmed key for entries
    std::string value;  // trimmed value for entries
};

ParsedLine classify(int number, const std::string& raw) {
    ParsedLine pl;
    pl.number = number;
    const std::string t = trim(raw);
    if (t.empty()) {
        pl.kind = ParsedLine::Kind::Blank;
        return pl;
    }
    if (t[0] == '#') {
        pl.kind = ParsedLine::Kind::Comment;
        return pl;
    }
    if (t[0] == '[') {
        if (t.back() != ']') {
            pl.kind = ParsedLine::Kind::Error;
            return pl;
        }
        const std::string name = trim(t.substr(1, t.size() - 2));
        if (name.empty()) {
            pl.kind = ParsedLine::Kind::Error;
            return pl;
        }
        pl.kind = ParsedLine::Kind::Header;
        pl.name = name;
        return pl;
    }
    const std::size_t eq = t.find('=');
    if (eq == std::string::npos) {
        pl.kind = ParsedLine::Kind::Error;
        return pl;
    }
    pl.kind = ParsedLine::Kind::Entry;
    pl.key = trim(t.substr(0, eq));
    pl.value = trim(t.substr(eq + 1));
    return pl;
}

std::vector<ParsedLine> scan(const std::string& text) {
    std::vector<ParsedLine> result;
    const std::vector<std::string> lines = split_lines(text);
    for (std::size_t i = 0; i < lines.size(); ++i) {
        result.push_back(classify(static_cast<int>(i + 1), lines[i]));
    }
    return result;
}

bool known_section(const std::string& name) {
    return name.empty() || name == "server" || name == "logging";
}

bool known_key(const std::string& section, const std::string& key) {
    if (section.empty()) return key == "app_name" || key == "title" || key == "version";
    if (section == "server") return key == "host" || key == "port" || key == "debug";
    if (section == "logging") return key == "level" || key == "verbose";
    return false;
}

bool valid_key_name(const std::string& key) {
    if (key.empty()) return false;
    if (key[0] < 'a' || key[0] > 'z') return false;
    for (char c : key) {
        const bool ok = (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_';
        if (!ok) return false;
    }
    return true;
}

std::string section_display(const std::string& section) {
    return section.empty() ? std::string("(top-level)") : section;
}

bool valid_port(const std::string& value) {
    if (value.empty()) return false;
    for (char c : value) {
        if (c < '0' || c > '9') return false;
    }
    std::size_t b = 0;
    while (b + 1 < value.size() && value[b] == '0') ++b;
    const std::string digits = value.substr(b);
    if (digits.size() > 5) return false;
    unsigned long v = 0;
    for (char c : digits) v = v * 10 + static_cast<unsigned long>(c - '0');
    return v >= 1 && v <= 65535;
}

bool valid_bool_value(const std::string& value) {
    const std::string l = to_lower(value);
    return l == "yes" || l == "no" || l == "on" || l == "off" || l == "true" || l == "false";
}

std::string normalize_bool(const std::string& value) {
    const std::string l = to_lower(value);
    if (l == "yes" || l == "on" || l == "true") return "true";
    return "false";
}

bool valid_log_level(const std::string& value) {
    const std::string l = to_lower(value);
    return l == "debug" || l == "info" || l == "warn" || l == "error";
}

}  // namespace

ParseError::ParseError(int line_number, const std::string& message)
    : std::runtime_error(message), line(line_number) {}

Document parse(const std::string& text) {
    Document doc;
    Section current;  // implicit top level (name == "") until the first header
    bool top_pending = true;
    for (const ParsedLine& pl : scan(text)) {
        switch (pl.kind) {
        case ParsedLine::Kind::Error:
            throw ParseError(pl.number, "syntax error");
        case ParsedLine::Kind::Header:
            if (top_pending) {
                // Implicit top level is kept only if it has at least one entry.
                if (!current.entries.empty()) doc.sections.push_back(current);
                top_pending = false;
            } else {
                doc.sections.push_back(current);
            }
            current = Section{};
            current.name = pl.name;
            break;
        case ParsedLine::Kind::Entry:
            current.entries.push_back(Entry{pl.key, pl.value});
            break;
        default:
            break;
        }
    }
    if (!top_pending) {
        doc.sections.push_back(current);
    } else if (!current.entries.empty()) {
        doc.sections.push_back(current);
    }
    return doc;
}

std::vector<Issue> lint(const std::string& text, const LintConfig& config) {
    std::vector<Issue> issues;
    std::set<std::string> seen_sections;
    std::string current_section;
    std::set<std::string> current_keys;

    for (const ParsedLine& pl : scan(text)) {
        switch (pl.kind) {
        case ParsedLine::Kind::Error:
            issues.push_back(Issue{pl.number, "E001", "syntax error"});
            break;
        case ParsedLine::Kind::Header:
            if (config.check_duplicates && seen_sections.count(pl.name) > 0) {
                issues.push_back(Issue{pl.number, "E006", "duplicate section '" + pl.name + "'"});
            }
            seen_sections.insert(pl.name);
            if (config.check_schema && !known_section(pl.name)) {
                issues.push_back(Issue{pl.number, "E004", "unknown section '" + pl.name + "'"});
            }
            current_section = pl.name;
            current_keys.clear();
            break;
        case ParsedLine::Kind::Entry:
            if (config.check_key_names && !valid_key_name(pl.key)) {
                // When E003 fires, no other rule applies to that line.
                issues.push_back(Issue{pl.number, "E003", "invalid key name '" + pl.key + "'"});
                break;
            }
            if (config.check_duplicates && current_keys.count(pl.key) > 0) {
                issues.push_back(Issue{pl.number, "E002", "duplicate key '" + pl.key + "'"});
            }
            current_keys.insert(pl.key);
            if (config.check_schema && known_section(current_section) &&
                !known_key(current_section, pl.key)) {
                issues.push_back(Issue{pl.number, "E005",
                                       "unknown key '" + pl.key + "' in section '" +
                                           section_display(current_section) + "'"});
            }
            if (config.warn_empty_values && pl.value.empty()) {
                issues.push_back(Issue{pl.number, "W001", "empty value for key '" + pl.key + "'"});
            }
            if (config.warn_deprecated && current_section.empty() && pl.key == "title") {
                issues.push_back(Issue{pl.number, "W002", "deprecated key 'title'"});
            }
            break;
        default:
            break;
        }
    }
    return issues;
}

std::vector<Issue> lint(const std::string& text) {
    return lint(text, LintConfig{});
}

MigrationResult migrate(const std::string& text) {
    MigrationResult result;

    // Step 1: lint with all checks enabled.
    for (const Issue& issue : lint(text)) {
        if (!issue.code.empty() && issue.code[0] == 'E') {
            result.errors.push_back(issue);
        } else {
            result.warnings.push_back(issue);
        }
    }

    // Step 2: v2 semantic checks (known keys in known sections only).
    struct Semantic {
        int line;
        Issue issue;
    };
    std::vector<Semantic> semantics;

    int title_line = 0;
    bool has_app_name = false;
    int version_line = 0;
    bool has_version_value = false;
    std::string current_section;

    for (const ParsedLine& pl : scan(text)) {
        if (pl.kind == ParsedLine::Kind::Header) {
            current_section = pl.name;
            continue;
        }
        if (pl.kind != ParsedLine::Kind::Entry) {
            continue;
        }
        if (current_section.empty()) {
            if (pl.key == "title") {
                if (title_line == 0) title_line = pl.number;
            } else if (pl.key == "app_name") {
                has_app_name = true;
            } else if (pl.key == "version") {
                if (version_line == 0) version_line = pl.number;
                if (!pl.value.empty()) has_version_value = true;
            }
        } else if (current_section == "server") {
            if (pl.key == "port" && !valid_port(pl.value)) {
                semantics.push_back(
                    Semantic{pl.number, Issue{pl.number, "M002", "invalid port '" + pl.value + "'"}});
            } else if (pl.key == "debug" && !valid_bool_value(pl.value)) {
                semantics.push_back(Semantic{pl.number, Issue{pl.number, "M005",
                                                              "invalid boolean value '" + pl.value +
                                                                  "' for key '" + pl.key + "'"}});
            }
        } else if (current_section == "logging") {
            if (pl.key == "verbose" && !valid_bool_value(pl.value)) {
                semantics.push_back(Semantic{pl.number, Issue{pl.number, "M005",
                                                              "invalid boolean value '" + pl.value +
                                                                  "' for key '" + pl.key + "'"}});
            } else if (pl.key == "level" && !valid_log_level(pl.value)) {
                semantics.push_back(Semantic{pl.number,
                                             Issue{pl.number, "M003", "invalid log level '" + pl.value + "'"}});
            }
        }
    }

    if (title_line != 0 && has_app_name) {
        semantics.push_back(Semantic{title_line, Issue{title_line, "M001",
                                                       "conflicting keys: 'title' and 'app_name' both present"}});
    }

    std::stable_sort(semantics.begin(), semantics.end(),
                     [](const Semantic& a, const Semantic& b) { return a.line < b.line; });
    for (const Semantic& s : semantics) {
        result.errors.push_back(s.issue);
    }

    // M004 is always appended last.
    if (!has_version_value) {
        result.errors.push_back(Issue{version_line, "M004", "missing version"});
    }

    // Step 3: fail if any error was found.
    if (!result.errors.empty()) {
        result.status = MigrationStatus::Failed;
        result.migrated.clear();
        return result;
    }

    // Step 4: build the v2 text.
    const Document doc = parse(text);
    const Section* top = nullptr;
    const Section* server = nullptr;
    const Section* logging = nullptr;
    for (const Section& s : doc.sections) {
        if (s.name.empty()) {
            top = &s;
        } else if (s.name == "server") {
            server = &s;
        } else if (s.name == "logging") {
            logging = &s;
        }
    }

    std::vector<std::string> out;
    auto emit_section = [&out](const std::string& name, const Section* s) {
        if (!s || s->entries.empty()) return;
        if (!name.empty()) out.push_back("[" + name + "]");
        for (const Entry& e : s->entries) {
            std::string key = e.key;
            std::string value = e.value;
            if (name.empty() && key == "title") key = "app_name";
            if (name == "server" && key == "debug") value = normalize_bool(value);
            if (name == "logging" && key == "verbose") value = normalize_bool(value);
            if (name == "logging" && key == "level") value = to_lower(value);
            if (value.empty()) {
                out.push_back(key + " =");
            } else {
                out.push_back(key + " = " + value);
            }
        }
    };
    emit_section("", top);
    emit_section("server", server);
    emit_section("logging", logging);

    result.migrated.clear();
    for (std::size_t i = 0; i < out.size(); ++i) {
        if (i > 0) result.migrated.push_back('\n');
        result.migrated += out[i];
    }

    // Step 5: status.
    result.status = result.warnings.empty() ? MigrationStatus::Ok : MigrationStatus::CompletedWithWarnings;
    return result;
}

}  // namespace config_linter_migrator
```

Notes on the key design decisions:

- **Shared scanner**: `parse`, `lint`, and `migrate` all build on one line classifier (`classify`/`scan`), so blank/comment/header/entry/syntax-error handling is identical everywhere. Lines are classified by their first non-whitespace character: `#` → comment, `[` → section header attempt (which must end with `]` and have non-empty bracket content), anything else → entry (must contain `=`).
- **State model for lint**: a `seen_sections` set for E006, plus a per-section seen-key set that resets on *every* header (a repeated header starts a fresh section, matching `parse` producing separate `Section`s). A syntactically broken header changes no state, so following entries stay in the previous section.
- **Rule ordering**: within an entry line the emit order is E002 → E005 → W001 → W002, and E003 short-circuits all other rules on its line; headers emit E006 before E004.
- **Migration**: E-errors from lint come first, then M001–M005 stable-sorted by triggering line, then M004 always last. The v2 renderer only runs when there are no errors, so it can safely rely on the invariant that at most one known section of each kind exists and all keys are known/unique.

