```go
package lostandfoundvalidator

import (
	"errors"
	"fmt"
	"strings"
	"time"
	"unicode"
	"unicode/utf8"
)

// Report is a single lost-item claim or found-item report filed with the
// lost-and-found office.
type Report struct {
	ID          string // "L-dddd" for a lost report, "F-dddd" for a found report.
	Kind        string // "lost" or "found".
	Category    string
	Color       string
	Location    string
	Date        string // "YYYY-MM-DD".
	Description string
	Contact     string
	RewardCents int
	MatchedID   string // Optional ID of a matching report of the opposite kind.
}

var validCategories = map[string]bool{
	"keys":     true,
	"wallet":   true,
	"phone":    true,
	"bag":      true,
	"umbrella": true,
	"other":    true,
}

var validColors = map[string]bool{
	"black":   true,
	"white":   true,
	"red":     true,
	"green":   true,
	"blue":    true,
	"yellow":  true,
	"brown":   true,
	"grey":    true,
	"unknown": true,
}

// wellFormedID reports whether id has the form "L-dddd" or "F-dddd".
func wellFormedID(id string) bool {
	if len(id) != 6 {
		return false
	}
	if id[0] != 'L' && id[0] != 'F' {
		return false
	}
	if id[1] != '-' {
		return false
	}
	for i := 2; i < 6; i++ {
		if id[i] < '0' || id[i] > '9' {
			return false
		}
	}
	return true
}

// validEmail reports whether s is a valid email address according to the
// rules: no whitespace anywhere, exactly one '@', non-empty local part,
// non-empty domain, and a domain containing at least one '.' that is
// neither its first nor its last character.
func validEmail(s string) bool {
	if s == "" {
		return false
	}
	if strings.IndexFunc(s, unicode.IsSpace) >= 0 {
		return false
	}
	if strings.Count(s, "@") != 1 {
		return false
	}
	at := strings.Index(s, "@")
	local, domain := s[:at], s[at+1:]
	if local == "" || domain == "" {
		return false
	}
	for i := 0; i < len(domain); i++ {
		if domain[i] == '.' && i != 0 && i != len(domain)-1 {
			return true
		}
	}
	return false
}

// shareWord reports whether a and b have at least one whitespace-separated
// word in common, comparing lowercased words.
func shareWord(a, b string) bool {
	words := make(map[string]bool)
	for _, w := range strings.Fields(a) {
		words[strings.ToLower(w)] = true
	}
	for _, w := range strings.Fields(b) {
		if words[strings.ToLower(w)] {
			return true
		}
	}
	return false
}

// ValidateReport checks a single report and returns one error per violated
// rule, in the documented rule order.
func ValidateReport(r Report) []error {
	var errs []error

	// Rule 1: ID format.
	idOK := wellFormedID(r.ID)
	if !idOK {
		errs = append(errs, fmt.Errorf("invalid id \"%s\"", r.ID))
	}

	// Rule 2: Kind.
	kindValid := r.Kind == "lost" || r.Kind == "found"
	if !kindValid {
		errs = append(errs, fmt.Errorf("invalid kind \"%s\"", r.Kind))
	}

	// Rule 3: ID prefix matches kind (only if kind valid and ID well-formed).
	if kindValid && idOK {
		wantPrefix := "L-"
		if r.Kind == "found" {
			wantPrefix = "F-"
		}
		if !strings.HasPrefix(r.ID, wantPrefix) {
			errs = append(errs, fmt.Errorf("id \"%s\" does not match kind \"%s\"", r.ID, r.Kind))
		}
	}

	// Rule 4: Category.
	if !validCategories[r.Category] {
		errs = append(errs, fmt.Errorf("invalid category \"%s\"", r.Category))
	}

	// Rule 5: Color.
	if !validColors[r.Color] {
		errs = append(errs, fmt.Errorf("invalid color \"%s\"", r.Color))
	}

	// Rule 6: Location.
	loc := strings.TrimSpace(r.Location)
	if loc == "" {
		errs = append(errs, errors.New("empty location"))
	} else if n := utf8.RuneCountInString(loc); n > 100 {
		errs = append(errs, fmt.Errorf("location too long: %d characters", n))
	}

	// Rule 7: Date.
	if t, err := time.Parse("2006-01-02", r.Date); err != nil {
		errs = append(errs, fmt.Errorf("invalid date \"%s\"", r.Date))
	} else if y := t.Year(); y < 2000 || y > 2099 {
		errs = append(errs, fmt.Errorf("date out of range \"%s\"", r.Date))
	}

	// Rule 8: Description (three independent checks, in order).
	if strings.Contains(r.Description, "@") {
		errs = append(errs, errors.New("description contains an email address"))
	}
	if n := utf8.RuneCountInString(r.Description); n < 10 {
		errs = append(errs, fmt.Errorf("description too short: %d characters", n))
	} else if n > 300 {
		errs = append(errs, fmt.Errorf("description too long: %d characters", n))
	}

	// Rule 9: Contact.
	if !validEmail(r.Contact) {
		errs = append(errs, fmt.Errorf("invalid contact \"%s\"", r.Contact))
	}

	// Rule 10: Reward (only when the kind is valid).
	if kindValid {
		if r.Kind == "lost" {
			if r.RewardCents < 0 || r.RewardCents > 100000 {
				errs = append(errs, fmt.Errorf("reward out of range: %d", r.RewardCents))
			}
		} else { // found
			if r.RewardCents != 0 {
				errs = append(errs, fmt.Errorf("found report offers a reward: %d", r.RewardCents))
			}
		}
	}

	// Rule 11: MatchedID.
	if r.MatchedID != "" {
		if !wellFormedID(r.MatchedID) {
			errs = append(errs, fmt.Errorf("invalid matched id \"%s\"", r.MatchedID))
		} else {
			if r.MatchedID == r.ID {
				errs = append(errs, errors.New("matched id equals own id"))
			}
			if kindValid {
				if r.Kind == "lost" {
					if !strings.HasPrefix(r.MatchedID, "F-") {
						errs = append(errs, fmt.Errorf("matched id \"%s\" must reference a found report", r.MatchedID))
					}
				} else {
					if !strings.HasPrefix(r.MatchedID, "L-") {
						errs = append(errs, fmt.Errorf("matched id \"%s\" must reference a lost report", r.MatchedID))
					}
				}
			}
		}
	}

	return errs
}

// CheckMatch checks whether a lost claim and a found report are compatible
// and returns one error per violated rule, in the documented rule order.
func CheckMatch(lost, found Report) []error {
	var errs []error

	// Rule 1: first report must be a lost report.
	if lost.Kind != "lost" {
		errs = append(errs, errors.New("first report is not a lost report"))
	}

	// Rule 2: second report must be a found report.
	if found.Kind != "found" {
		errs = append(errs, errors.New("second report is not a found report"))
	}

	// Rule 3: categories must be equal.
	if lost.Category != found.Category {
		errs = append(errs, fmt.Errorf("category mismatch: \"%s\" vs \"%s\"", lost.Category, found.Category))
	}

