package shippingratesmigrator

import "fmt"

// RateV1 is a single weight-tier price in the legacy (v1) rate table format.
type RateV1 struct {
	Zone       string
	MaxWeightG int
	PriceCents int
}

// RateTableV1 is a carrier's rate table in the legacy (v1) format.
type RateTableV1 struct {
	Carrier string
	Rates   []RateV1
}

// RateV2 is a single weight-tier price in the current (v2) rate table format.
type RateV2 struct {
	Zone             string
	MaxWeightG       int
	BaseCents        int
	FuelSurchargePct int
}

// RateTableV2 is a carrier's rate table in the current (v2) format.
type RateTableV2 struct {
	Carrier  string
	Currency string
	Rates    []RateV2
}

// fuelSurchargePct maps a zone to its fuel surcharge percentage.
var fuelSurchargePct = map[string]int{
	"DOM": 0,
	"EU":  5,
	"WW":  12,
}

// Migrate upgrades a v1 rate table to the v2 format, validating it first.
func Migrate(t RateTableV1) (RateTableV2, error) {
	if t.Carrier == "" {
		return RateTableV2{}, fmt.Errorf("missing carrier")
	}
	if len(t.Rates) == 0 {
		return RateTableV2{}, fmt.Errorf("no rates")
	}

	// lastWeight tracks the most recent MaxWeightG seen per zone.
	lastWeight := make(map[string]int)

	for i, r := range t.Rates {
		pct, ok := fuelSurchargePct[r.Zone]
		if !ok {
			return RateTableV2{}, fmt.Errorf("rate %d: unknown zone %q", i, r.Zone)
		}
		if r.MaxWeightG <= 0 {
			return RateTableV2{}, fmt.Errorf("rate %d: max weight must be positive", i)
		}
		if r.PriceCents < 0 {
			return RateTableV2{}, fmt.Errorf("rate %d: price must be non-negative", i)
		}
		if prev, seen := lastWeight[r.Zone]; seen && r.MaxWeightG <= prev {
			return RateTableV2{}, fmt.Errorf(
				"rate %d: max weight must be greater than previous rate for zone %s",
				i, r.Zone)
		}
		lastWeight[r.Zone] = r.MaxWeightG
	}

	rates := make([]RateV2, len(t.Rates))
	for i, r := range t.Rates {
		rates[i] = RateV2{
			Zone:             r.Zone,
			MaxWeightG:       r.MaxWeightG,
			BaseCents:        r.PriceCents,
			FuelSurchargePct: fuelSurchargePct[r.Zone],
		}
	}

	return RateTableV2{
		Carrier:  t.Carrier,
		Currency: "USD",
		Rates:    rates,
	}, nil
}

// Quote returns the shipping cost in cents for the given zone and weight
// using a v2 rate table.
func Quote(t RateTableV2, zone string, weightG int) (int, error) {
	if weightG <= 0 {
		return 0, fmt.Errorf("weight must be positive")
	}

	var maxWeight int
	found := false
	for _, r := range t.Rates {
		if r.Zone != zone {
			continue
		}
		if !found || r.MaxWeightG > maxWeight {
			maxWeight = r.MaxWeightG
			found = true
		}
		if r.MaxWeightG >= weightG {
			return r.BaseCents * (100 + r.FuelSurchargePct) / 100, nil
		}
	}

	if !found {
		return 0, fmt.Errorf("unknown zone %q", zone)
	}
	return 0, fmt.Errorf("weight %dg exceeds maximum %dg for zone %s", weightG, maxWeight, zone)
}
```

A few notes on the implementation:

- **Validation order in `Migrate`** matches the spec exactly: carrier, then rates presence, then per-rate checks (zone → weight → price → per-zone monotonicity), with the first failure short-circuiting via early returns of `RateTableV2{}` and the error.
- **Per-zone weight tracking** uses a `map[string]int` storing the most recent `MaxWeightG` per zone, so interleaved zones work correctly.
- **`Quote`** scans in table order so the first tier with `MaxWeightG >= weightG` wins (exact matches fall into that tier), while simultaneously tracking the zone's overall maximum for the "exceeds maximum" error message.
- **Integer arithmetic**: the cost uses truncating division `BaseCents * (100 + FuelSurchargePct) / 100`, exactly as specified (e.g. 500 × 105 / 100 = 525).
- Quoted zone strings in errors use `%q`, plain ones use `%s`, matching the examples like `rate 0: unknown zone "APAC"` and `rate 2: max weight must be greater than previous rate for zone DOM`.

The problem is in the validation loop of `Migrate`: I declared `pct, ok := fuelSurchargePct[r.Zone]` but only used `ok`, so Go complains that `pct` is declared and not used. The fix is to discard the value with `_` during validation (it's looked up again properly when building the v2 rates).

