package busyblockssimulator

import (
	"errors"
	"fmt"
	"sort"
)

// Block describes a recurring busy block on the weekly grid.
type Block struct {
	ID        string // unique, non-empty
	Day       int    // 0 = Monday ... 6 = Sunday
	Start     int    // minute of day, 0..1439
	End       int    // minute of day, 1..1440, Start < End
	EveryN    int    // recurrence period in weeks
	SkipWeeks []int  // occurrence weeks that are cancelled
}

// Meeting describes a single meeting on the weekly grid.
type Meeting struct {
	Week  int // 0..weeks-1
	Day   int // 0..6
	Start int // 0..1439
	End   int // 1..1440, Start < End
}

const (
	minutesPerDay  = 1440
	minutesPerWeek = 10080
)

// Simulator answers conflict queries about meetings versus busy blocks.
type Simulator struct {
	weeks  int
	blocks []Block
	ids    map[string]struct{}
}

// NewSimulator creates a simulator covering the given number of weeks.
func NewSimulator(weeks int) (*Simulator, error) {
	if weeks < 1 {
		return nil, errors.New("weeks must be at least 1")
	}
	return &Simulator{
		weeks: weeks,
		ids:   make(map[string]struct{}),
	}, nil
}

// AddBlock validates and registers a recurring busy block.
func (s *Simulator) AddBlock(b Block) error {
	if b.ID == "" {
		return errors.New("block ID must not be empty")
	}
	if _, dup := s.ids[b.ID]; dup {
		return fmt.Errorf("duplicate block ID %q", b.ID)
	}
	if b.Day < 0 || b.Day > 6 {
		return errors.New("day must be in 0..6")
	}
	if b.Start < 0 || b.Start > 1439 {
		return errors.New("start must be in 0..1439")
	}
	if b.End < 1 || b.End > 1440 {
		return errors.New("end must be in 1..1440")
	}
	if b.Start >= b.End {
		return errors.New("start must be before end")
	}
	if b.EveryN < 1 {
		return errors.New("EveryN must be at least 1")
	}
	for _, w := range b.SkipWeeks {
		if w < 0 || w >= s.weeks {
			return fmt.Errorf("skip week %d out of range 0..%d", w, s.weeks-1)
		}
	}

	// Store a deep copy so later external mutation of SkipWeeks cannot
	// affect the simulator.
	sk := make([]int, len(b.SkipWeeks))
	copy(sk, b.SkipWeeks)
	b.SkipWeeks = sk

	s.blocks = append(s.blocks, b)
	s.ids[b.ID] = struct{}{}
	return nil
}

// occursInWeek reports whether the block has an occurrence in week w,
// assuming w is within the horizon.
func (b *Block) occursInWeek(w int) bool {
	if w%b.EveryN != 0 {
		return false
	}
	for _, sw := range b.SkipWeeks {
		if sw == w {
			return false
		}
	}
	return true
}

func (s *Simulator) validateMeeting(m Meeting) error {
	if m.Week < 0 || m.Week >= s.weeks {
		return fmt.Errorf("week %d out of range 0..%d", m.Week, s.weeks-1)
	}
	if m.Day < 0 || m.Day > 6 {
		return errors.New("day must be in 0..6")
	}
	if m.Start < 0 || m.Start > 1439 {
		return errors.New("start must be in 0..1439")
	}
	if m.End < 1 || m.End > 1440 {
		return errors.New("end must be in 1..1440")
	}
	if m.Start >= m.End {
		return errors.New("start must be before end")
	}
	return nil
}

// mergeIntervals sorts the half-open intervals and merges overlapping or
// touching ones.
func mergeIntervals(intervals [][2]int) [][2]int {
	sort.Slice(intervals, func(i, j int) bool {
		if intervals[i][0] != intervals[j][0] {
			return intervals[i][0] < intervals[j][0]
		}
		return intervals[i][1] < intervals[j][1]
	})
	merged := make([][2]int, 0, len(intervals))
	for _, iv := range intervals {
		if n := len(merged); n > 0 && iv[0] <= merged[n-1][1] {
			if iv[1] > merged[n-1][1] {
				merged[n-1][1] = iv[1]
			}
			continue
		}
		merged = append(merged, iv)
	}
	return merged
}

func unionLength(intervals [][2]int) int {
	total := 0
	for _, iv := range mergeIntervals(intervals) {
		total += iv[1] - iv[0]
	}
	return total
}

// BusyMinutes reports how many minutes of the meeting fall inside busy blocks.
func (s *Simulator) BusyMinutes(m Meeting) (int, error) {
	if err := s.validateMeeting(m); err != nil {
		return 0, err
	}
	// Blocks never cross midnight, so only blocks on the same day of the
	// same week can intersect the meeting.
	var clipped [][2]int
	for i := range s.blocks {
		b := &s.blocks[i]
		if b.Day != m.Day || !b.occursInWeek(m.Week) {
			continue
		}
		lo := max(b.Start, m.Start)
		hi := min(b.End, m.End)
		if lo < hi {
			clipped = append(clipped, [2]int{lo, hi})
		}
	}
	return unionLength(clipped), nil
}

// Conflicts returns the sorted IDs of all blocks overlapping the meeting.
func (s *Simulator) Conflicts(m Meeting) ([]string, error) {
	if err := s.validateMeeting(m); err != nil {
		return nil, err
	}
	var ids []string
	for i := range s.blocks {
		b := &s.blocks[i]
		if b.Day == m.Day && b.occursInWeek(m.Week) &&
			b.Start < m.End && m.Start < b.End {
			ids = append(ids, b.ID)
		}
	}
	sort.Strings(ids)
	return ids, nil
}

// BusyMinutesInWeek reports the total busy minutes in the given week.
func (s *Simulator) BusyMinutesInWeek(week int) (int, error) {
	if week < 0 || week >= s.weeks {
		return 0, fmt.Errorf("week %d out of range 0..%d", week, s.weeks-1)
	}
	// Every occurrence lies entirely inside a single week (no midnight
	// crossing), so all occurrences of the week contribute directly.
	var intervals [][2]int
	for i := range s.blocks {
		b := &s.blocks[i]
		if b.occursInWeek(week) {
			intervals = append(intervals, [2]int{b.Start, b.End})
		}
	}
	return unionLength(intervals), nil
}

// FindSlot finds the earliest start on the given day that fits a meeting.
func (s *Simulator) FindSlot(week, day, duration, buffer int) (int, bool, error) {
	if week < 0 || week >= s.weeks {
		return 0, false, fmt.Errorf("week %d out of range 0..%d", week, s.weeks-1)
	}
	if day < 0 || day > 6 {
		return 0, false, errors.New("day must be in 0..6")
	}
	if duration <= 0 {
		return 0, false, errors.New("duration must be positive")
	}
	if duration > minutesPerDay {
		return 0, false, errors.New("duration must not exceed 1440")
	}
	if buffer < 0 {
		return 0, false, errors.New("buffer must not be negative")
	}

	// Collect every occurrence in the whole horizon, widened by the buffer
	// on both sides (absolute minutes, not clamped).
	var widened [][2]int
	for i := range s.blocks {
		b := &s.blocks[i]
		for w := 0; w < s.weeks; w++ {
			if !b.occursInWeek(w) {
				continue
			}
			base := w*minutesPerWeek + b.Day*minutesPerDay
			widened = append(widened, [2]int{base + b.Start - buffer, base + b.End + buffer})
		}
	}
	merged := mergeIntervals(widened)

	dayStart := week*minutesPerWeek + day*minutesPerDay
	limit := dayStart + minutesPerDay - duration // largest allowed start

	// Sweep: keep the earliest candidate start that does not conflict with
	// any widened interval processed so far.
	c := dayStart
	for _, iv := range merged {
		if c+duration < iv[0] {
			// The candidate ends before this interval begins; since the
			// intervals are sorted, no later interval can conflict either.
			break
		}
		if c < iv[1] {
			c = iv[1]
		}
	}
	if c <= limit {
		return c - dayStart, true, nil
	}
	return 0, false, nil
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}
