```go
package gymlockersplanner

import "fmt"

// booking records that a member holds a specific locker for the
// inclusive week range [startWeek, endWeek].
type booking struct {
	member    string
	locker    int
	startWeek int
	endWeek   int
}

// Planner assigns gym lockers to members for weekly terms and
// handles renewals and cancellations.
type Planner struct {
	numLockers int
	bookings   []booking // current bookings, in creation order
}

// NewPlanner creates a planner managing lockers numbered 1 to numLockers.
func NewPlanner(numLockers int) (*Planner, error) {
	if numLockers < 1 {
		return nil, fmt.Errorf("number of lockers must be positive")
	}
	return &Planner{numLockers: numLockers}, nil
}

// findBooking returns the index of the member's booking, or -1.
func (p *Planner) findBooking(member string) int {
	for i, b := range p.bookings {
		if b.member == member {
			return i
		}
	}
	return -1
}

// overlaps reports whether the inclusive week ranges [aStart, aEnd]
// and [bStart, bEnd] overlap.
func overlaps(aStart, aEnd, bStart, bEnd int) bool {
	return aStart < bEnd && bStart < aEnd
}

// Request assigns the lowest-numbered locker that is free for the whole
// inclusive week range [startWeek, endWeek] to the given member.
func (p *Planner) Request(member string, startWeek, endWeek int) (int, error) {
	if member == "" {
		return 0, fmt.Errorf("member name must not be empty")
	}
	if startWeek < 1 {
		return 0, fmt.Errorf("start week must be at least 1")
	}
	if endWeek < startWeek {
		return 0, fmt.Errorf("end week must not be before start week")
	}
	if i := p.findBooking(member); i >= 0 {
		return 0, fmt.Errorf("member %q already has locker %d", member, p.bookings[i].locker)
	}

	for locker := 1; locker <= p.numLockers; locker++ {
		free := true
		for _, b := range p.bookings {
			if b.locker == locker && overlaps(startWeek, endWeek, b.startWeek, b.endWeek) {
				free = false
				break
			}
		}
		if free {
			p.bookings = append(p.bookings, booking{member, locker, startWeek, endWeek})
			return locker, nil
		}
	}
	return 0, fmt.Errorf("no locker available for weeks %d-%d", startWeek, endWeek)
}

// Renew extends the member's current booking by extraWeeks weeks in place.
func (p *Planner) Renew(member string, extraWeeks int) (int, error) {
	if extraWeeks < 1 {
		return 0, fmt.Errorf("extra weeks must be at least 1")
	}
	i := p.findBooking(member)
	if i < 0 {
		return 0, fmt.Errorf("unknown member %q", member)
	}
	b := p.bookings[i]
	newEnd := b.endWeek + extraWeeks
	extStart := b.endWeek + 1
	for _, other := range p.bookings {
		if other.locker == b.locker && other.member != member &&
			overlaps(extStart, newEnd, other.startWeek, other.endWeek) {
			return 0, fmt.Errorf("locker %d is not available for weeks %d-%d", b.locker, extStart, newEnd)
		}
	}
	p.bookings[i].endWeek = newEnd
	return b.locker, nil
}

// Cancel removes the member's booking, freeing the locker and the member.
func (p *Planner) Cancel(member string) error {
	i := p.findBooking(member)
	if i < 0 {
		return fmt.Errorf("unknown member %q", member)
	}
	p.bookings = append(p.bookings[:i], p.bookings[i+1:]...)
	return nil
}

// LockerOf reports the locker held by the member, if any.
func (p *Planner) LockerOf(member string) (int, bool) {
	if i := p.findBooking(member); i >= 0 {
		return p.bookings[i].locker, true
	}
	return 0, false
}

// WeeklyLoad reports how many bookings cover the given week.
func (p *Planner) WeeklyLoad(week int) (int, error) {
	if week < 1 {
		return 0, fmt.Errorf("week must be at least 1")
	}
	count := 0
	for _, b := range p.bookings {
		if b.startWeek <= week && week <= b.endWeek {
			count++
		}
	}
	return count, nil
}
```

