// Package releaseversionsvalidator checks that a proposed release version
// is the correct bump for a set of change entries.
package releaseversionsvalidator

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// Version is a release version of the form MAJOR.MINOR.PATCH.
type Version struct {
	Major, Minor, Patch int
}

// String formats the version as "MAJOR.MINOR.PATCH".
func (v Version) String() string {
	return fmt.Sprintf("%d.%d.%d", v.Major, v.Minor, v.Patch)
}

// Compare returns -1 if v is older than o, 0 if they are equal and
// 1 if v is newer than o.
func (v Version) Compare(o Version) int {
	if v.Major != o.Major {
		if v.Major < o.Major {
			return -1
		}
		return 1
	}
	if v.Minor != o.Minor {
		if v.Minor < o.Minor {
			return -1
		}
		return 1
	}
	if v.Patch != o.Patch {
		if v.Patch < o.Patch {
			return -1
		}
		return 1
	}
	return 0
}

// ParseVersion parses a MAJOR.MINOR.PATCH version string.
func ParseVersion(s string) (Version, error) {
	parts := strings.Split(s, ".")
	if len(parts) != 3 {
		return Version{}, errors.New("not in MAJOR.MINOR.PATCH format")
	}
	// All components must be non-empty and consist only of decimal digits.
	for _, p := range parts {
		if p == "" {
			return Version{}, errors.New("not in MAJOR.MINOR.PATCH format")
		}
		for i := 0; i < len(p); i++ {
			if p[i] < '0' || p[i] > '9' {
				return Version{}, errors.New("not in MAJOR.MINOR.PATCH format")
			}
		}
	}
	// Only now check for leading zeros in multi-digit components.
	for _, p := range parts {
		if len(p) >= 2 && p[0] == '0' {
			return Version{}, errors.New("leading zero in version component")
		}
	}
	var nums [3]int
	for i, p := range parts {
		n, _ := strconv.Atoi(p) // digits only, cannot fail
		nums[i] = n
	}
	return Version{nums[0], nums[1], nums[2]}, nil
}

// ChangeKind classifies a change entry.
type ChangeKind int

// The kinds of change entries. KindUnknown is the zero value and is
// never returned for a successfully parsed entry.
const (
	KindUnknown ChangeKind = iota
	KindBreaking
	KindFeature
	KindFix
	KindDocs
	KindChore
)

// Problem describes one detected problem. Line is the 1-based index of
// the offending change entry, or 0 for a release-level problem.
type Problem struct {
	Line   int
	Reason string
}

var typeKinds = map[string]ChangeKind{
	"feat":  KindFeature,
	"fix":   KindFix,
	"docs":  KindDocs,
	"chore": KindChore,
}

func validScope(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '-') {
			return false
		}
	}
	return true
}

// checkDescription validates the text after the ':' separator.
func checkDescription(rest string) error {
	if len(rest) < 2 || rest[0] != ' ' || rest[1] == ' ' || rest[1] == '\t' {
		return errors.New("expected single space after ':'")
	}
	desc := rest[1:]
	last := desc[len(desc)-1]
	if last == ' ' || last == '\t' {
		return errors.New("description has trailing whitespace")
	}
	if last == '.' {
		return errors.New("description must not end with '.'")
	}
	return nil
}

// ParseChange validates a single change entry and returns its kind.
// On error the returned kind is KindUnknown.
func ParseChange(line string) (ChangeKind, error) {
	idx := strings.Index(line, ":")
	if idx < 0 {
		return KindUnknown, errors.New("no ':' separator")
	}
	head, rest := line[:idx], line[idx+1:]

	// The exact breaking-note form.
	if head == "BREAKING CHANGE" {
		if err := checkDescription(rest); err != nil {
			return KindUnknown, err
		}
		return KindBreaking, nil
	}

	breaking := false
	h := head
	if strings.HasSuffix(h, "!") {
		h = h[:len(h)-1]
		breaking = true
	}

	var kind ChangeKind
	if strings.HasSuffix(h, ")") && strings.Contains(h, "(") {
		op := strings.LastIndex(h, "(")
		typ, scope := h[:op], h[op+1:len(h)-1]
		k, ok := typeKinds[typ]
		if !ok {
			return KindUnknown, fmt.Errorf("unknown change type %q", typ)
		}
		if !validScope(scope) {
			return KindUnknown, fmt.Errorf("invalid scope %q", scope)
		}
		kind = k
	} else {
		typ := h
		k, ok := typeKinds[typ]
		if !ok {
			return KindUnknown, fmt.Errorf("unknown change type %q", typ)
		}
		kind = k
	}

	if err := checkDescription(rest); err != nil {
		return KindUnknown, err
	}
	if breaking {
		return KindBreaking, nil
	}
	return kind, nil
}

// nextVersion computes the version required by the bump rules.
func nextVersion(p Version, kinds []ChangeKind) Version {
	hasBreaking, hasFeat, hasFix := false, false, false
	for _, k := range kinds {
		switch k {
		case KindBreaking:
			hasBreaking = true
		case KindFeature:
			hasFeat = true
		case KindFix:
			hasFix = true
		}
	}
	switch {
	case hasBreaking:
		if p.Major == 0 {
			return Version{0, p.Minor + 1, 0}
		}
		return Version{p.Major + 1, 0, 0}
	case hasFeat:
		return Version{p.Major, p.Minor + 1, 0}
	case hasFix:
		return Version{p.Major, p.Minor, p.Patch + 1}
	default:
		return p
	}
}

// Validate checks a release proposal and returns all detected problems
// in a fixed order, or nil when the proposal is valid.
func Validate(previous, proposed string, changes []string) []Problem {
	prev, err := ParseVersion(previous)
	if err != nil {
		return []Problem{{Line: 0, Reason: fmt.Sprintf("invalid previous version %q: %s", previous, err)}}
	}

	var problems []Problem
	kinds := make([]ChangeKind, len(changes))
	for i, c := range changes {
		k, err := ParseChange(c)
		if err != nil {
			problems = append(problems, Problem{Line: i + 1, Reason: err.Error()})
		}
		kinds[i] = k
	}
	if len(problems) > 0 {
		return problems
	}

	prop, err := ParseVersion(proposed)
	if err != nil {
		return []Problem{{Line: 0, Reason: fmt.Sprintf("invalid proposed version %q: %s", proposed, err)}}
	}

	next := nextVersion(prev, kinds)
	if prop.Compare(next) != 0 {
		return []Problem{{Line: 0, Reason: fmt.Sprintf("expected next version %s, proposed %s", next, prop)}}
	}
	return nil
}
```

A few notes on the implementation:

- **ParseVersion** checks digit-validity for *all* components before checking leading zeros, so e.g. `"01.a.3"` reports the format error, not the leading-zero error.
- **ParseChange** handles the exact `BREAKING CHANGE` head first, then strips a trailing `!`, then applies scope/type checks in the specified order (type before scope, head before description), so `"feat(!bad scope): x"` reports the type error first if the type is unknown.
- **Validate** short-circuits exactly as specified: an unparseable previous version returns one problem; otherwise invalid change entries return only those problems; only then is the proposed version parsed and compared against the computed bump.
- `Version.String()` makes the final mismatch message format both versions via `%s` automatically.

