```go
package budgetenvelopescodec

import (
	"fmt"
	"strconv"
	"strings"
)

const maxAmount = int64(1000000)

// Envelope is a named budget envelope with an optional rollover cap.
type Envelope struct {
	Name string
	Cap  int64 // rollover cap in cents; 0 means no cap
}

// Entry is the allocation and spending of one envelope in one month.
type Entry struct {
	Name  string // envelope name
	Month string // "YYYY-MM"
	Alloc int64  // cents allocated in that month
	Spent int64  // cents spent in that month
}

// Ledger is a full envelope budget: envelopes, months and entries.
type Ledger struct {
	Envelopes []Envelope // declaration order; names unique
	Months    []string   // "YYYY-MM", consecutive calendar months
	Entries   []Entry    // arbitrary order; at most one per (Name, Month)
}

// EnvelopeSummary reports totals and carry-over results for one envelope.
type EnvelopeSummary struct {
	Name            string
	TotalAlloc      int64
	TotalSpent      int64
	TotalSwept      int64
	TotalOverspent  int64
	FinalCarry      int64
	OverspentMonths []string // months in which the envelope overspent
	SweptMonths     []string // months in which surplus above the cap was swept away
}

func validName(name string) bool {
	if len(name) < 1 || len(name) > 20 {
		return false
	}
	c := name[0]
	if !(('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z')) {
		return false
	}
	for i := 1; i < len(name); i++ {
		c := name[i]
		if !(('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z') ||
			('0' <= c && c <= '9') || c == '-' || c == '_') {
			return false
		}
	}
	if name == "E" || name == "M" {
		return false
	}
	return true
}

// parseMonth validates "YYYY-MM" and returns an absolute month index
// (year*12 + month) for sequence checking.
func parseMonth(s string) (int, bool) {
	if len(s) != 7 || s[4] != '-' {
		return 0, false
	}
	for i := 0; i < 4; i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
	}
	for i := 5; i < 7; i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
	}
	year, err1 := strconv.Atoi(s[:4])
	month, err2 := strconv.Atoi(s[5:7])
	if err1 != nil || err2 != nil {
		return 0, false
	}
	if year < 2000 || year > 2999 || month < 1 || month > 12 {
		return 0, false
	}
	return year*12 + month, true
}

func isDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

// parseAmount parses a digits-only string in 0..maxAmount (leading zeros ok).
func parseAmount(s string) (int64, bool) {
	if !isDigits(s) {
		return 0, false
	}
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil || v < 0 || v > maxAmount {
		return 0, false
	}
	return v, true
}

// Decode parses the compact envelope ledger text format.
func Decode(s string) (Ledger, error) {
	var l Ledger
	declared := map[string]bool{}
	entrySeen := map[string]bool{} // key: name + " " + month
	headerSeen := false
	seenMonth := false
	prevIdx := 0

	for _, raw := range strings.Split(s, "\n") {
		line := strings.TrimSuffix(raw, "\r")
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if !headerSeen {
			if line != "envelopes:1" {
				return Ledger{}, fmt.Errorf("bad header: %q", line)
			}
			headerSeen = true
			continue
		}
		fields := strings.Split(line, " ")

		if strings.HasPrefix(line, "E ") {
			name := fields[1]
			if seenMonth {
				return Ledger{}, fmt.Errorf("envelope declared after month: %s", name)
			}
			if len(fields) != 2 && len(fields) != 3 {
				return Ledger{}, fmt.Errorf("bad line: %q", line)
			}
			if !validName(name) {
				return Ledger{}, fmt.Errorf("bad name: %q", name)
			}
			if declared[name] {
				return Ledger{}, fmt.Errorf("duplicate envelope: %s", name)
			}
			var cap int64
			if len(fields) == 3 {
				tok := fields[2]
				if !strings.HasPrefix(tok, "cap:") {
					return Ledger{}, fmt.Errorf("bad line: %q", line)
				}
				v, ok := parseAmount(tok[len("cap:"):])
				if !ok || v < 1 {
					return Ledger{}, fmt.Errorf("bad cap: %q", tok)
				}
				cap = v
			}
			declared[name] = true
			l.Envelopes = append(l.Envelopes, Envelope{Name: name, Cap: cap})
			continue
		}

		if strings.HasPrefix(line, "M ") {
			if len(fields) != 2 {
				return Ledger{}, fmt.Errorf("bad line: %q", line)
			}
			m := fields[1]
			idx, ok := parseMonth(m)
			if !ok {
				return Ledger{}, fmt.Errorf("bad month: %q", m)
			}
			if len(l.Months) > 0 && idx <= prevIdx {
				return Ledger{}, fmt.Errorf("month out of sequence: %s after %s",
					m, l.Months[len(l.Months)-1])
			}
			prevIdx = idx
			seenMonth = true
			l.Months = append(l.Months, m)
			continue
		}

		// Entry line.
		if !seenMonth {
			return Ledger{}, fmt.Errorf("entry before any month: %q", line)
		}
		if len(fields) != 3 {
			return Ledger{}, fmt.Errorf("bad line: %q", line)
		}
		name := fields[0]
		if !validName(name) {
			return Ledger{}, fmt.Errorf("bad name: %q", name)
		}
		if !declared[name] {
			return Ledger{}, fmt.Errorf("undeclared envelope: %s", name)
		}
		alloc, ok := parseAmount(fields[1])
		if !ok {
			return Ledger{}, fmt.Errorf("bad amount: %q", fields[1])
		}
		spent, ok := parseAmount(fields[2])
		if !ok {
			return Ledger{}, fmt.Errorf("bad amount: %q", fields[2])
		}
		month := l.Months[len(l.Months)-1]
		key := name + " " + month
		if entrySeen[key] {
			return Ledger{}, fmt.Errorf("duplicate entry: %s %s", name, month)
		}
		entrySeen[key] = true
		l.Entries = append(l.Entries, Entry{Name: name, Month: month, Alloc: alloc, Spent: spent})
	}

	if !headerSeen {
		return Ledger{}, fmt.Errorf("empty ledger")
	}
	if !seenMonth {
		return Ledger{}, fmt.Errorf("no months")
	}
	return l, nil
}

// validate performs the shared validation used by Encode and Summarize.
func validate(l Ledger) error {
	if len(l.Months) == 0 {
		return fmt.Errorf("no months")
	}
	declared := map[string]bool{}
	for _, e := range l.Envelopes {
		if !validName(e.Name) {
			return fmt.Errorf("bad name: %q", e.Name)
		}
		if e.Cap < 0 || e.Cap > maxAmount {
			return fmt.Errorf("bad cap: %d", e.Cap)
		}
		if declared[e.Name] {
			return fmt.Errorf("duplicate envelope: %s", e.Name)
		}
		declared[e.Name] = true
	}
	monthSet := map[string]bool{}
	prev := 0
	for i, m := range l.Months {
		idx, ok := parseMonth(m)
		if !ok {
			return fmt.Errorf("bad month: %q", m)
		}
		if i > 0 && idx != prev+1 {
			return fmt.Errorf("month out of sequence: %s after %s", m, l.Months[i-1])
		}
		prev = idx
		monthSet[m] = true
	}
	seen := map[string]bool{}
	for _, e := range l.Entries {
		if !declared[e.Name] {
			return fmt.Errorf("undeclared envelope: %s", e.Name)
		}
		if !monthSet[e.Month] {
			return fmt.Errorf("unknown month: %s", e.Month)
		}
		if e.Alloc < 0 || e.Alloc > maxAmount {
			return fmt.Errorf("bad amount: %d", e.Alloc)
		}
		if e.Spent < 0 || e.Spent > maxAmount {
			return fmt.Errorf("bad amount: %d", e.Spent)
		}
		key := e.Name + " " + e.Month
		if seen[key] {
			return fmt.Errorf("duplicate entry: %s %s", e.Name, e.Month)
		}
		seen[key] = true
	}
	return nil
}

// Encode writes a Ledger in the canonical compact text format.
func Encode(l Ledger) (string, error) {
	if err := validate(l); err != nil {
		return "", err
	}
	var b strings.Builder
	b.WriteString("envelopes:1\n")
	for _, e := range l.Envelopes {
		if e.Cap == 0 {
			fmt.Fprintf(&b, "E %s\n", e.Name)
		} else {
			fmt.Fprintf(&b, "E %s cap:%d\n", e.Name, e.Cap)
		}
	}
	byMonth := make(map[string]map[string]Entry, len(l.Months))
	for _, e := range l.Entries {
		if byMonth[e.Month] == nil {
			byMonth[e.Month] = make(map[string]Entry)
		}
		byMonth[e.Month][e.Name] = e
	}
	for _, m := range l.Months {
		fmt.Fprintf(&b, "M %s\n", m)
		em := byMonth[m]
		for _, env := range l.Envelopes {
			if e, ok := em[env.Name]; ok {
				fmt.Fprintf(&b, "%s %d %d\n", e.Name, e.Alloc, e.Spent)
			}
		}
	}
	return b.String(), nil
}

// Summarize computes per-envelope totals and carry-over results.
func Summarize(l Ledger) ([]EnvelopeSummary, error) {
	if err := validate(l); err != nil {
		return nil, err
	}
	type key struct {
		name  string
		month string
	}
	entryMap := make(map[key]Entry, len(l.Entries))
	for _, e := range l.Entries {
		entryMap[key{e.Name, e.Month}] = e
	}
	sums := make([]EnvelopeSummary, 0, len(l.Envelopes))
	for _, env := range l.Envelopes {
		s := EnvelopeSummary{Name: env.Name}
		var carry int64
		for _, m := range l.Months {
			var alloc, spent int64
			if e, ok := entryMap[key{env.Name, m}]; ok {
				alloc, spent = e.Alloc, e.Spent
			}
			s.TotalAlloc += alloc
			s.TotalSpent += spent
			avail := carry + alloc
			if spent > avail {
				s.TotalOverspent += spent - avail
				s.OverspentMonths = append(s.OverspentMonths, m)
				carry = 0
			} else {
				bal := avail - spent
				if env.Cap > 0 && bal > env.Cap {
					s.TotalSwept += bal - env.Cap
					s.SweptMonths = append(s.SweptMonths, m)
				}
				carry = bal
			}
		}
		s.FinalCarry = carry
		sums = append(sums, s)
	}
	return sums, nil
}
