```go
package recordfilterscodec

import (
	"errors"
	"fmt"
	"strings"
)

// Op is the comparison operator of a condition.
type Op string

// The supported operators.
const (
	OpEq          Op = "="
	OpNotEq       Op = "!="
	OpLt          Op = "<"
	OpLtEq        Op = "<="
	OpGt          Op = ">"
	OpGtEq        Op = ">="
	OpContains    Op = "~"
	OpNotContains Op = "!~"
)

// Kind describes the shape of an Expr node.
type Kind int

// The supported expression kinds.
const (
	KindCondition Kind = iota
	KindAnd
	KindOr
	KindNot
)

// Condition compares a record field against a value.
type Condition struct {
	Field string
	Op    Op
	Value string
}

// Expr is a filter expression tree. A KindCondition node uses Condition;
// KindAnd, KindOr and KindNot nodes use Operands.
type Expr struct {
	Kind      Kind
	Condition *Condition
	Operands  []*Expr
}

// Parse decodes a wire-format filter expression into an Expr tree.
func Parse(s string) (*Expr, error) {
	p := &parser{s: s}
	p.skipWS()
	if p.eof() {
		return nil, errors.New("empty expression")
	}
	e, err := p.parseOr()
	if err != nil {
		return nil, err
	}
	p.skipWS()
	if !p.eof() {
		c := p.s[p.pos]
		if c == ')' {
			return nil, fmt.Errorf("unexpected ')' at position %d", p.pos+1)
		}
		return nil, fmt.Errorf("unexpected character %q at position %d", c, p.pos+1)
	}
	return e, nil
}

// parser holds the state of a single parse.
type parser struct {
	s   string
	pos int // current byte offset in s
}

func (p *parser) eof() bool { return p.pos >= len(p.s) }

// skipWS advances past spaces and tabs.
func (p *parser) skipWS() {
	for p.pos < len(p.s) && (p.s[p.pos] == ' ' || p.s[p.pos] == '\t') {
		p.pos++
	}
}

// parseOr parses or := and ('|' and)*.
func (p *parser) parseOr() (*Expr, error) {
	first, err := p.parseAnd()
	if err != nil {
		return nil, err
	}
	operands := []*Expr{first}
	for {
		p.skipWS()
		if p.eof() || p.s[p.pos] != '|' {
			break
		}
		p.pos++
		next, err := p.parseAnd()
		if err != nil {
			return nil, err
		}
		operands = append(operands, next)
	}
	if len(operands) == 1 {
		return first, nil
	}
	return &Expr{Kind: KindOr, Operands: operands}, nil
}

// parseAnd parses and := unary ('&' unary)*.
func (p *parser) parseAnd() (*Expr, error) {
	first, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	operands := []*Expr{first}
	for {
		p.skipWS()
		if p.eof() || p.s[p.pos] != '&' {
			break
		}
		p.pos++
		next, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		operands = append(operands, next)
	}
	if len(operands) == 1 {
		return first, nil
	}
	return &Expr{Kind: KindAnd, Operands: operands}, nil
}

// parseUnary parses unary := '!' unary | primary.
func (p *parser) parseUnary() (*Expr, error) {
	p.skipWS()
	if !p.eof() && p.s[p.pos] == '!' {
		p.pos++
		operand, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &Expr{Kind: KindNot, Operands: []*Expr{operand}}, nil
	}
	return p.parsePrimary()
}

// parsePrimary parses primary := '(' expr ')' | field op value.
func (p *parser) parsePrimary() (*Expr, error) {
	p.skipWS()
	if p.eof() {
		return nil, fmt.Errorf("unexpected end of expression at position %d", p.pos+1)
	}
	c := p.s[p.pos]
	if c == '(' {
		open := p.pos
		p.pos++
		e, err := p.parseOr()
		if err != nil {
			return nil, err
		}
		p.skipWS()
		if p.eof() {
			return nil, fmt.Errorf("unclosed '(' at position %d", open+1)
		}
		if p.s[p.pos] != ')' {
			return nil, fmt.Errorf("unexpected character %q at position %d", p.s[p.pos], p.pos+1)
		}
		p.pos++
		return e, nil
	}
	if isFieldStart(c) {
		start := p.pos
		for p.pos < len(p.s) && isFieldChar(p.s[p.pos]) {
			p.pos++
		}
		field := p.s[start:p.pos]
		p.skipWS()
		op, ok := p.parseOp()
		if !ok {
			return nil, fmt.Errorf("expected operator after field %q at position %d", field, p.pos+1)
		}
		p.skipWS()
		value, err := p.parseValue(field)
		if err != nil {
			return nil, err
		}
		return &Expr{Kind: KindCondition, Condition: &Condition{Field: field, Op: op, Value: value}}, nil
	}
	return nil, fmt.Errorf("unexpected character %q at position %d", c, p.pos+1)
}

// parseOp reads an operator at the current position.
func (p *parser) parseOp() (Op, bool) {
	rest := p.s[p.pos:]
	for _, o := range []string{"!=", "!~", "<=", ">="} {
		if strings.HasPrefix(rest, o) {
			p.pos += 2
			return Op(o), true
		}
	}
	for _, o := range []string{"=", "<", ">", "~"} {
		if strings.HasPrefix(rest, o) {
			p.pos++
			return Op(o), true
		}
	}
	return "", false
}

// parseValue reads a bare or quoted value for the given field.
func (p *parser) parseValue(field string) (string, error) {
	if p.eof() {
		return "", fmt.Errorf("missing value for field %q at position %d", field, p.pos+1)
	}
	switch p.s[p.pos] {
	case '&', '|', '(', ')':
		return "", fmt.Errorf("missing value for field %q at position %d", field, p.pos+1)
	case '"':
		return p.parseQuotedValue(field)
	}
	start := p.pos
	for p.pos < len(p.s) && !isValueDelim(p.s[p.pos]) {
		p.pos++
	}
	return p.s[start:p.pos], nil
}

// parseQuotedValue reads a quoted value; p.pos is on the opening quote.
func (p *parser) parseQuotedValue(field string) (string, error) {
	open := p.pos
	p.pos++ // consume opening quote
	var sb strings.Builder
	for {
		if p.eof() {
			return "", fmt.Errorf("unclosed quote in value of field %q at position %d", field, open+1)
		}
		c := p.s[p.pos]
		if c == '"' {
			p.pos++
			return sb.String(), nil
		}
		if c == '\\' {
			esc := p.pos
			p.pos++
			if p.eof() {
				return "", fmt.Errorf("invalid escape sequence at position %d", esc+1)
			}
			switch p.s[p.pos] {
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			default:
				return "", fmt.Errorf("invalid escape sequence at position %d", esc+1)
			}
			p.pos++
			continue
		}
		sb.WriteByte(c)
		p.pos++
	}
}

func isFieldStart(c byte) bool {
	return c == '_' || ('A' <= c && c <= 'Z') || ('a' <= c && c <= 'z')
}

func isFieldChar(c byte) bool {
	return isFieldStart(c) || ('0' <= c && c <= '9')
}

func isValueDelim(c byte) bool {
	switch c {
	case ' ', '\t', '&', '|', '(', ')', '"':
		return true
	}
	return false
}

// Encode renders e in the canonical wire format.
func (e *Expr) Encode() (string, error) {
	if err := e.validate(); err != nil {
		return "", err
	}
	return e.encode(), nil
}

func (e *Expr) encode() string {
	switch e.Kind {
	case KindCondition:
		c := e.Condition
		return c.Field + string(c.Op) + encodeValue(c.Value)
	case KindAnd:
		parts := make([]string, len(e.Operands))
		for i, operand := range e.Operands {
			s := operand.encode()
			if operand.Kind == KindOr {
				s = "(" + s + ")"
			}
			parts[i] = s
		}
		return strings.Join(parts, "&")
	case KindOr:
		parts := make([]string, len(e.Operands))
		for i, operand := range e.Operands {
			parts[i] = operand.encode()
		}
		return strings.Join(parts, "|")
	case KindNot:
		operand := e.Operands[0]
		s := operand.encode()
		if operand.Kind == KindAnd || operand.Kind == KindOr {
			s = "(" + s + ")"
		}
		return "!" + s
	default:
		return "" // unreachable after validation
	}
}

// encodeValue renders a condition value, bare when possible.
func encodeValue(v string) string {
	if v == "" {
		return `""`
	}
	bare := true
	for i := 0; i < len(v); i++ {
		if !isBareValueByte(v[i]) {
			bare = false
			break
		}
	}
	if bare {
		return v
	}
	var sb strings.Builder
	sb.WriteByte('"')
	for i := 0; i < len(v); i++ {
		switch v[i] {
		case '\\':
			sb.WriteString(`\\`)
		case '"':
			sb.WriteString(`\"`)
		case '\n':
			sb.WriteString(`\n`)
		case '\t':
			sb.WriteString(`\t`)
		default:
			sb.WriteByte(v[i])
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

func isBareValueByte(c byte) bool {
	if ('A' <= c && c <= 'Z') || ('a' <= c && c <= 'z') || ('0' <= c && c <= '9') {
		return true
	}
	switch c {
	case '_', '.', ':', '@', '/', '-':
		return true
	}
	return false
}

// Match reports whether record satisfies the filter e.
func (e *Expr) Match(record map[string]string) (bool, error) {
	if err := e.validate(); err != nil {
		return false, err
	}
	return e.match(record), nil
}

func (e *Expr) match(record map[string]string) bool {
	switch e.Kind {
	case KindCondition:
		c := e.Condition
		a := record[c.Field]
		switch c.Op {
		case OpEq:
			return a == c.Value
		case OpNotEq:
			return a != c.Value
		case OpLt:
			return a < c.Value
		case OpLtEq:
			return a <= c.Value
		case OpGt:
			return a > c.Value
		case OpGtEq:
			return a >= c.Value
		case OpContains:
			return strings.Contains(a, c.Value)
		case OpNotContains:
			return !strings.Contains(a, c.Value)
		default:
			return false // unreachable after validation
		}
	case KindAnd:
		for _, operand := range e.Operands {
			if !operand.match(record) {
				return false
			}
		}
		return true
	case KindOr:
		for _, operand := range e.Operands {
			if operand.match(record) {
				return true
			}
		}
		return false
	case KindNot:
		return !e.Operands[0].match(record)
	default:
		return false // unreachable after validation
	}
}

// validate checks the whole tree depth-first, in operand order.
func (e *Expr) validate() error {
	if e == nil {
		return errors.New("nil expression")
	}
	switch e.Kind {
	case KindCondition:
		if e.Condition == nil {
			return errors.New("condition expression has no condition")
		}
		if !validField(e.Condition.Field) {
			return fmt.Errorf("invalid field name %q", e.Condition.Field)
		}
		if !validOp(e.Condition.Op) {
			return fmt.Errorf("unknown operator %q", string(e.Condition.Op))
		}
		return nil
	case KindAnd:
		if len(e.Operands) < 2 {
			return errors.New("AND expression needs at least 2 operands")
		}
		return validateOperands("AND", e.Operands)
	case KindOr:
		if len(e.Operands) < 2 {
			return errors.New("OR expression needs at least 2 operands")
		}
		return validateOperands("OR", e.Operands)
	case KindNot:
		if len(e.Operands) != 1 {
			return errors.New("NOT expression needs exactly 1 operand")
		}
		return validateOperands("NOT", e.Operands)
	default:
		return fmt.Errorf("unknown expression kind %d", int(e.Kind))
	}
}

func validateOperands(kind string, operands []*Expr) error {
	for _, operand := range operands {
		if operand == nil {
			return fmt.Errorf("nil operand in %s expression", kind)
		}
		if err := operand.validate(); err != nil {
			return err
		}
	}
	return nil
}

func validField(f string) bool {
	if f == "" || !isFieldStart(f[0]) {
		return false
	}
	for i := 1; i < len(f); i++ {
		if !isFieldChar(f[i]) {
			return false
		}
	}
	return true
}

func validOp(op Op) bool {
	switch op {
	case OpEq, OpNotEq, OpLt, OpLtEq, OpGt, OpGtEq, OpContains, OpNotContains:
		return true
	default:
		return false
	}
}
```

A few notes on the implementation:

- **Parsing** is a straightforward recursive descent mirroring the grammar (`parseOr` → `parseAnd` → `parseUnary` → `parsePrimary`), so single-operand chains naturally collapse to the operand itself with no wrapper node. All error positions are 1-based byte offsets, using `len(s)+1` when the input ended.
- **Operator recognition** tries the two-character operators (`!=`, `!~`, `<=`, `>=`) before the single-character ones, and only right after a field name — a `!` in operand position is always negation.
- **Values**: bare values are the longest run of non-delimiter bytes (so `=`, `<`, `!`, `~` etc. are legal inside them); quoted values handle exactly `\"`, `\\`, `\n`, `\t` and report the backslash position on bad escapes.
- **Parentheses**: an unclosed `(` is reported at end of input with the `(`'s position; any junk inside parens or trailing the top-level expression is reported as `unexpected character 'X'`, except a trailing unmatched `)` which gets its own `unexpected ')'` message.
- **`Encode`/`Match`** share the `validate` walk (depth-first, operand order, first error wins) and only then render/evaluate. Parenthesisation in `Encode` follows the precedence rules exactly, so `a=1|(b=2&c=3)` round-trips to `a=1|b=2&c=3` while `(a=1|b=2)&c=3` and `!(a=1&b=2)` keep their parentheses.

