func (p *parser) parseOp() (Op, error) {
	if p.pos >= len(p.s) { return "", err }
	rest := p.s[p.pos:]
	// two-char first
	for _, o := range []string{"!=", "!~", "<=", ">="} {
		if strings.HasPrefix(rest, o) { p.pos += 2; return Op(o), nil }
	}
	for _, o := range []string{"=", "<", ">", "~"} {
		if strings.HasPrefix(rest, o) { p.pos += 1; return Op(o), nil }
	}
	return "", err
}
```

