func (p *parser) parseValue(field string) (string, error) {
	if p.pos >= len(p.s) || p.s[p.pos] == '"' {
		// quoted
		if p.pos >= len(p.s) {
			return "", fmt.Errorf("missing value for field %q at position %d", field, p.pos+1)
		}
		open := p.pos
		p.pos++ // skip "
		var sb strings.Builder
		for {
			if p.pos >= len(p.s) {
				return "", fmt.Errorf("unclosed quote in value of field %q at position %d", field, open+1)
			}
			c := p.s[p.pos]
			if c == '"' { p.pos++; return sb.String(), nil }
			if c == '\\' {
				escPos := p.pos
				p.pos++
				if p.pos >= len(p.s) {
					return "", fmt.Errorf("invalid escape sequence at position %d", escPos+1)
				}
				switch p.s[p.pos] {
				case '"': sb.WriteByte('"')
				case '\\': sb.WriteByte('\\')
				case 'n': sb.WriteByte('\n')
				case 't': sb.WriteByte('\t')
				default: return "", fmt.Errorf("invalid escape sequence at position %d", escPos+1)
				}
				p.pos++
				continue
			}
			sb.WriteByte(c)
			p.pos++
		}
	}
	// bare
	start := p.pos
	for p.pos < len(p.s) && !isValueDelim(p.s[p.pos]) { p.pos++ }
	return p.s[start:p.pos], nil
}
```

