Value bare charset: `[A-Za-z0-9_.:@/-]` — bytes: letters, digits, `_`, `.`, `:`, `@`, `/`, `-`. 

```go
func encodeValue(v string) string {
	if v == "" { return `""` }
	bare := true
	for i := 0; i < len(v); i++ {
		c := v[i]
		if c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' || c >= '0' && c <= '9' { continue }
		switch c {
		case '_', '.', ':', '@', '/', '-': continue
		}
		bare = false
		break
	}
	if bare { return v }
	var sb strings.Builder
	sb.WriteByte('"')
	for i := 0; i < len(v); i++ {
		switch v[i] {
		case '\\': sb.WriteString(`\\`)
		case '"': sb.WriteString(`\"`)
		case '\n': sb.WriteString(`\n`)
		case '\t': sb.WriteString(`\t`)
		default: sb.WriteByte(v[i])
		}
	}
	sb.WriteByte('"')
	return sb.String()
}
```

Encode expression:

```go
func (e *Expr) encode() string {
	switch e.Kind {
	case KindCondition:
		return e.Condition.Field + string(e.Condition.Op) + encodeValue(e.Condition.Value)
	case KindAnd:
		parts := make([]string, len(e.Operands))
		for i, o := range e.Operands {
			s := o.encode()
			if o.Kind == KindOr { s = "(" + s + ")" }
			parts[i] = s
		}
		return strings.Join(parts, "&")
	case KindOr:
		parts...join "|"
	case KindNot:
		s := e.Operands[0].encode()
		if e.Operands[0].Kind == KindAnd || e.Operands[0].Kind == KindOr { s = "(" + s + ")" }
		return "!" + s
	}
	// unreachable after validation
	return ""
}
```

Match:

```go
func (e *Expr) match(record map[string]string) bool {
	switch e.Kind {
	case KindCondition:
		c := e.Condition
		a := record[c.Field]
		v := c.Value
		switch c.Op {
		case OpEq: return a == v
		case OpNotEq: return a != v
		case OpLt: return a < v
		case OpLtEq: return a <= v
		case OpGt: return a > v
		case OpGtEq: return a >= v
		case OpContains: return strings.Contains(a, v)
		case OpNotContains: return !strings.Contains(a, v)
		}
		return false // unreachable
	case KindAnd:
		for _, o := range e.Operands { if !o.match(record) { return false } }
		return true
	case KindOr:
		for _, o := range e.Operands { if o.match(record) { return true } }
		return false
	case KindNot:
		return !e.Operands[0].match(record)
	}
	return false
}
```

Validation:

```go
func validOp(op Op) bool {
	switch op {
	case OpEq, OpNotEq, OpLt, OpLtEq, OpGt, OpGtEq, OpContains, OpNotContains:
		return true
	}
	return false
}

func (e *Expr) validate() error {
	if e == nil { return errors.New("nil expression") }
	switch e.Kind {
	case KindCondition:
		if e.Condition == nil { return errors.New("condition expression has no condition") }
		if !validField(e.Condition.Field) {
			return fmt.Errorf("invalid field name %q", e.Condition.Field)
		}
		if !validOp(e.Condition.Op) {
			return fmt.Errorf("unknown operator %q", string(e.Condition.Op))
		}
		return nil
	case KindAnd:
		if len(e.Operands) < 2 { return errors.New("AND expression needs at least 2 operands") }
		return validateOperands("AND", e.Operands)
	case KindOr:
		if len(e.Operands) < 2 { return errors.New("OR expression needs at least 2 operands") }
		return validateOperands("OR", e.Operands)
	case KindNot:
		if len(e.Operands) != 1 { return errors.New("NOT expression needs exactly 1 operand") }
		return validateOperands("NOT", e.Operands)
	default:
		return fmt.Errorf("unknown expression kind %d", int(e.Kind))
	}
}

func validateOperands(kind string, operands []*Expr) error {
	for _, o := range operands {
		if o == nil { return fmt.Errorf("nil operand in %s expression", kind) }
		if err := o.validate(); err != nil { return err }
	}
	return nil
}
