		return nil, fmt.Errorf("unexpected character %q at position %d", c, p.pos+1)
	}
	return e, nil
}

func (p *parser) eof() bool { return p.pos >= len(p.s) }

func (p *parser) skipWS() {
	for p.pos < len(p.s) && (p.s[p.pos] == ' ' || p.s[p.pos] == '\t') {
		p.pos++
	}
