	if isFieldStart(c) {
		start := p.pos
		for p.pos < len(p.s) && isFieldChar(p.s[p.pos]) {
			p.pos++
		}
		field := p.s[start:p.pos]
		p.skipWS()
		op, ok := p.parseOp()
		if !ok {
			return nil, fmt.Errorf("expected operator after field %q at position %d", field, p.pos+1)
