func (p *parser) parseQuotedValue(field string) (string, error) {
	open := p.pos
	p.pos++ // opening quote
	var sb strings.Builder
	for {
		if p.eof() {
			return "", fmt.Errorf("unclosed quote in value of field %q at position %d", field, open+1)
		}
		c := p.s[p.pos]
		if c == '"' {
			p.pos++
			return sb.String(), nil
		}
		if c == '\\' {
			esc := p.pos
			p.pos++
			if p.eof() {
				return "", fmt.Errorf("invalid escape sequence at position %d", esc+1)
			}
			switch p.s[p.pos] {
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			default:
				return "", fmt.Errorf("invalid escape sequence at position %d", esc+1)
			}
			p.pos++
			continue
		}
		sb.WriteByte(c)
		p.pos++
	}
}
