package recordfilterscodec

import (
	"errors"
	"fmt"
	"strings"
)

// Op is the comparison operator of a condition.
type Op string

// The supported operators.
const (
	OpEq          Op = "="
	OpNotEq       Op = "!="
	OpLt          Op = "<"
	OpLtEq        Op = "<="
	OpGt          Op = ">"
	OpGtEq        Op = ">="
	OpContains    Op = "~"
	OpNotContains Op = "!~"
)

// Kind describes the shape of an Expr node.
type Kind int

// The supported expression kinds.
const (
	KindCondition Kind = iota
	KindAnd
	KindOr
	KindNot
)

// Condition compares a record field against a value.
type Condition struct {
	Field string
	Op    Op
	Value string
}

// Expr is a filter expression tree. A KindCondition node uses Condition;
// KindAnd, KindOr and KindNot nodes use Operands.
type Expr struct {
	Kind      Kind
	Condition *Condition
	Operands  []*Expr
}

// Parse decodes a wire-format filter expression into an Expr tree.
func Parse(s string) (*Expr, error) {
	p := &parser{s: s}
	p.skipWS()
	if p.eof() {
		return nil, errors.New("empty expression")
	}
	e, err := p.parseOr()
	if err != nil {
		return nil, err
	}
	p.skipWS()
	if !p.eof() {
		c := p.s[p.pos]
		if c == ')' {
			return nil, fmt.Errorf("unexpected ')' at position %d", p.pos+1)
		}
		return nil, fmt.Errorf("unexpected character %q at position %d", c, p.pos+1)
	}
	return e, nil
}
