// Match reports whether record satisfies the filter e.
func (e *Expr) Match(record map[string]string) (bool, error) {
	if err := e.validate(); err != nil {
		return false, err
	}
	return e.match(record), nil
}

func (e *Expr) match(record map[string]string) bool {
	switch e.Kind {
	case KindCondition:
		c := e.Condition
		a := record[c.Field]
		switch c.Op {
		case OpEq:
			return a == c.Value
		case OpNotEq:
			return a != c.Value
		case OpLt:
			return a < c.Value
		case OpLtEq:
			return a <= c.Value
		case OpGt:
			return a > c.Value
		case OpGtEq:
			return a >= c.Value
		case OpContains:
			return strings.Contains(a, c.Value)
		case OpNotContains:
			return !strings.Contains(a, c.Value)
		default:
			return false // unreachable after validation
		}
	case KindAnd:
		for _, operand := range e.Operands {
			if !operand.match(record) {
				return false
			}
		}
		return true
	case KindOr:
		for _, operand := range e.Operands {
			if operand.match(record) {
				return true
			}
		}
		return false
	case KindNot:
		return !e.Operands[0].match(record)
	default:
		return false // unreachable after validation
	}
}
