package vaccinationrecordscodec

import (
	"fmt"
	"strconv"
	"strings"
	"time"
)

const dateLayout = "2006-01-02"

// Dose is a single administered vaccine dose.
type Dose struct {
	VaccineCode string
	DoseNumber  int
	Date        time.Time
	Lot         string
}

// Record is a patient's complete vaccination record.
type Record struct {
	PatientID string
	BirthDate time.Time
	Doses     []Dose
}

// ScheduleRule describes the requirements for one vaccine.
type ScheduleRule struct {
	VaccineCode   string
	RequiredDoses int
	MinAgeMonths  int
	MinGapDays    int
}

func containsSeparator(s string) bool {
	return strings.ContainsAny(s, "|;:")
}

// EncodeRecord converts a Record into its compact one-line text form.
func EncodeRecord(r Record) (string, error) {
	if r.PatientID == "" {
		return "", fmt.Errorf("empty patient id")
	}
	if containsSeparator(r.PatientID) {
		return "", fmt.Errorf("invalid patient id %q", r.PatientID)
	}
	if r.BirthDate.IsZero() {
		return "", fmt.Errorf("invalid birth date")
	}
	for _, d := range r.Doses {
		if d.VaccineCode == "" {
			return "", fmt.Errorf("empty vaccine code")
		}
		if containsSeparator(d.VaccineCode) {
			return "", fmt.Errorf("invalid vaccine code %q", d.VaccineCode)
		}
		if d.DoseNumber < 1 {
			return "", fmt.Errorf("invalid dose number %d", d.DoseNumber)
		}
		if d.Date.IsZero() {
			return "", fmt.Errorf("invalid dose date")
		}
		if containsSeparator(d.Lot) {
			return "", fmt.Errorf("invalid lot %q", d.Lot)
		}
	}

	doseParts := make([]string, 0, len(r.Doses))
	for _, d := range r.Doses {
		doseParts = append(doseParts, fmt.Sprintf("%s:%d:%s:%s",
			d.VaccineCode, d.DoseNumber, d.Date.Format(dateLayout), d.Lot))
	}
	return r.PatientID + "|" + r.BirthDate.Format(dateLayout) + "|" + strings.Join(doseParts, ";"), nil
}

// DecodeRecord parses the compact one-line text form back into a Record.
func DecodeRecord(s string) (Record, error) {
	if s == "" {
		return Record{}, fmt.Errorf("empty record")
	}
	fields := strings.Split(s, "|")
	if len(fields) != 3 {
		return Record{}, fmt.Errorf("expected 3 fields, got %d", len(fields))
	}
	if fields[0] == "" {
		return Record{}, fmt.Errorf("empty patient id")
	}
	birth, err := time.Parse(dateLayout, fields[1])
	if err != nil {
		return Record{}, fmt.Errorf("invalid birth date %q", fields[1])
	}
	rec := Record{PatientID: fields[0], BirthDate: birth}

	if fields[2] != "" {
		seen := make(map[string]bool)
		for _, part := range strings.Split(fields[2], ";") {
			parts := strings.Split(part, ":")
			if len(parts) != 4 {
				return Record{}, fmt.Errorf("dose %q: expected 4 fields, got %d", part, len(parts))
			}
			code := parts[0]
			if code == "" {
				return Record{}, fmt.Errorf("empty vaccine code")
			}
			num, err := strconv.Atoi(parts[1])
			if err != nil || num < 1 {
				return Record{}, fmt.Errorf("invalid dose number %q", parts[1])
			}
			date, err := time.Parse(dateLayout, parts[2])
			if err != nil {
				return Record{}, fmt.Errorf("invalid dose date %q", parts[2])
			}
			key := fmt.Sprintf("%s#%d", code, num)
			if seen[key] {
				return Record{}, fmt.Errorf("duplicate dose %s", key)
			}
			seen[key] = true
			rec.Doses = append(rec.Doses, Dose{
				VaccineCode: code,
				DoseNumber:  num,
				Date:        date,
				Lot:         parts[3],
			})
		}
	}
	return rec, nil
}

// CheckSchedule compares a Record against schedule rules as of a given date
// and returns the list of problems found.
func CheckSchedule(r Record, rules []ScheduleRule, asOf time.Time) ([]string, error) {
	seenRules := make(map[string]bool)
	for _, rule := range rules {
		if rule.VaccineCode == "" {
			return nil, fmt.Errorf("invalid rule: empty vaccine code")
		}
		if rule.RequiredDoses < 1 {
			return nil, fmt.Errorf("invalid rule: required doses for %s must be at least 1", rule.VaccineCode)
		}
		if rule.MinAgeMonths < 0 {
			return nil, fmt.Errorf("invalid rule: minimum age for %s must not be negative", rule.VaccineCode)
		}
		if rule.MinGapDays < 0 {
			return nil, fmt.Errorf("invalid rule: minimum gap for %s must not be negative", rule.VaccineCode)
		}
		if seenRules[rule.VaccineCode] {
			return nil, fmt.Errorf("duplicate rule for %s", rule.VaccineCode)
		}
		seenRules[rule.VaccineCode] = true
	}

	var problems []string
	for _, rule := range rules {
		// Collect doses for this rule's vaccine; the last dose with a given
		// number wins. Doses outside 1..RequiredDoses are ignored.
		doseDates := make(map[int]time.Time)
		for _, d := range r.Doses {
			if d.VaccineCode == rule.VaccineCode && d.DoseNumber >= 1 && d.DoseNumber <= rule.RequiredDoses {
				doseDates[d.DoseNumber] = d.Date
			}
		}
		for n := 1; n <= rule.RequiredDoses; n++ {
			date, ok := doseDates[n]
			if !ok || date.After(asOf) {
				problems = append(problems, fmt.Sprintf("%s dose %d missing", rule.VaccineCode, n))
				continue
			}
			if n == 1 {
				if ageInMonths(r.BirthDate, date) < rule.MinAgeMonths {
					problems = append(problems, fmt.Sprintf("%s dose 1 invalid: given before minimum age", rule.VaccineCode))
				}
				continue
			}
			if prev, ok := doseDates[n-1]; ok {
				minValid := prev.AddDate(0, 0, rule.MinGapDays)
				if date.Before(minValid) {
					problems = append(problems, fmt.Sprintf("%s dose %d invalid: given too soon after previous dose", rule.VaccineCode, n))
				}
			}
		}
	}
	return problems, nil
}

// ageInMonths computes the age in full months at the dose date:
// (doseYear − birthYear) × 12 + (doseMonth − birthMonth),
// minus 1 if doseDay < birthDay.
func ageInMonths(birth, dose time.Time) int {
	months := (dose.Year()-birth.Year())*12 + int(dose.Month()) - int(birth.Month())
	if dose.Day() < birth.Day() {
		months--
	}
	return months
}
```

Notes on key design points:

- **Validation order** is followed exactly as specified in both `EncodeRecord` and `DecodeRecord`, with `%q` used where the spec shows quoted values and `%d`/`%s` where raw values are shown.
- **Round-trip**: dates are formatted with layout `2006-01-02` and parsed back with `time.Parse`, which yields UTC midnight — matching the input dates exactly.
- **Empty lot**: the trailing `:` produces an empty 4th field on split, so lots round-trip correctly; an empty dose list produces the trailing `|`.
- **CheckSchedule**: rule validation happens first over all rules in order; then rules are processed in order with dose numbers 1..RequiredDoses, using a `map[int]time.Time` where later doses overwrite earlier ones ("last one wins"). A gap of exactly `MinGapDays` is valid (checked via `date.Before(prev.AddDate(0,0,MinGapDays))`), and no gap check occurs when the previous dose isn't recorded.

