    private final int height;
    private final byte[][] feature;
    private final char[][] oneWayDir; // only meaningful where feature == ONE_WAY

    public WarehousePathsPlanner(int width, int height) {
        if (width <= 0 || height <= 0) {
            throw new LayoutException("Grid dimensions must be positive");
        }
        this.width = width;
        this.height = height;
        this.feature = new byte[height][width];
        this.oneWayDir = new char[height][width];
    }

    public WarehousePathsPlanner withShelf(int x, int y) {
        install(SHELF, x, y, '\0');
        return this;
    }

    public WarehousePathsPlanner withOneWayAisle(int x, int y, char direction) {
        if (direction != 'N' && direction != 'E' && direction != 'S' && direction != 'W') {
            throw new LayoutException("Invalid direction '" + direction + "'");
        }
        install(ONE_WAY, x, y, direction);
        return this;
    }

    public WarehousePathsPlanner withDockingBay(int x, int y) {
        install(DOCK, x, y, '\0');
