                    throw new RoutePlanningException("No route from (" + current.x() + "," + current.y()
                            + ") to (" + stop.x() + "," + stop.y() + ")");
                }
                int x = current.x();
                int y = current.y();
                for (int i = 0; i < leg.path().length(); i++) {
                    int d = dirIndex(leg.path().charAt(i));
                    x += DX[d];
                    y += DY[d];
                    cells.add(new Position(x, y));
                }
                totalCost += leg.cost();
            }
            current = stop;
        }
        return new Route(cells, totalCost);
    }

    private void requireInBounds(Position p) {
        if (p.x() < 0 || p.y() < 0 || p.x() >= width || p.y() >= height) {
            throw new RoutePlanningException("Cell (" + p.x() + "," + p.y() + ") is out of bounds");
        }
    }

    private void requirePassable(Position p, boolean heavy) {
        byte f = feature[p.y()][p.x()];
        if (f == SHELF || (f == NARROW && heavy)) {
            throw new RoutePlanningException("Cell (" + p.x() + "," + p.y() + ") is impassable for this robot");
        }
    }

    /**
     * Dijkstra over states (cell, direction of the move that entered the cell),
     * with the lexicographic key (cost, move sequence). Direction 0 means "no
     * previous move" (leg start), which never triggers a turn penalty. Because
     * every edge strictly increases this key, the first state popped at the
     * target cell yields the minimum-cost, lexicographically smallest leg.
     */
    private Leg shortestLeg(Position from, Position to, boolean heavy) {
        int states = width * height * 5;
        int[] bestCost = new int[states];
        Arrays.fill(bestCost, Integer.MAX_VALUE);
        String[] bestPath = new String[states];
        boolean[] settled = new boolean[states];

        PriorityQueue<Entry> pq = new PriorityQueue<>((a, b) -> {
            if (a.cost() != b.cost()) {
                return Integer.compare(a.cost(), b.cost());
            }
            return a.path().compareTo(b.path());
        });

        int startState = (from.y() * width + from.x()) * 5; // direction 0
        bestCost[startState] = 0;
        bestPath[startState] = "";
        pq.add(new Entry(0, "", startState));

        while (!pq.isEmpty()) {
            Entry e = pq.poll();
            int state = e.state();
            if (settled[state]) {
                continue;
            }
            settled[state] = true;

            int prevDir = state % 5; // 0 = none (leg start)
            int cell = state / 5;
            int x = cell % width;
            int y = cell / width;

            if (x == to.x() && y == to.y()) {
                return new Leg(e.cost(), e.path());
            }

            byte here = feature[y][x];
            for (int i = 0; i < 4; i++) {
                // One-way aisle: may only leave the current cell in its direction.
                if (here == ONE_WAY && DIR_CHARS[i] != oneWayDir[y][x]) {
                    continue;
                }
                int nx = x + DX[i];
                int ny = y + DY[i];
                if (nx < 0 || ny < 0 || nx >= width || ny >= height) {
                    continue;
                }
                byte dest = feature[ny][nx];
                if (dest == SHELF) {
                    continue;
                }
                if (dest == NARROW && heavy) {
                    continue;
                }
                int moveCost = (dest == DOCK ? 3 : 1)
                        + (prevDir != 0 && prevDir != i + 1 ? 1 : 0);
                int nCost = e.cost() + moveCost;
                String nPath = e.path() + DIR_CHARS[i];
                int nState = (ny * width + nx) * 5 + (i + 1);

                if (nCost > bestCost[nState]) {
                    continue;
                }
                if (nCost == bestCost[nState] && nPath.compareTo(bestPath[nState]) >= 0) {
                    continue;
                }
                bestCost[nState] = nCost;
                bestPath[nState] = nPath;
                pq.add(new Entry(nCost, nPath, nState));
            }
        }
        return null;
    }

    private static int dirIndex(char c) {
        switch (c) {
            case 'E': return 0;
            case 'N': return 1;
            case 'S': return 2;
            default:  return 3; // 'W'
        }
    }

    private record Leg(int cost, String path) {
    }

    private record Entry(int cost, String path, int state) {
    }
}
```

A few notes on the implementation:

- **Search algorithm**: each leg is a Dijkstra search over states `(cell, incoming direction)`. The incoming direction is needed because the turn penalty depends on the previous move; direction `0` represents "no previous move" (the leg start), so first moves are never penalized.
- **Tie-breaking**: the priority queue is ordered by `(cost, move sequence)` lexicographically, and since every move strictly increases this key (each move costs at least 1), standard Dijkstra correctness carries over — the first popped state at the target cell gives the cheapest, then lexicographically smallest, move sequence. The directions `E, N, S, W` are indexed in exactly the required character order, so plain `String.compareTo` implements the tie-break.
- **Validation order**: `planRoute` checks robot type → nulls → bounds (start, then stops) → impassability (start, then stops) → per-leg reachability, matching the spec. `withOneWayAisle` validates the direction before the coordinates.
- **Legs**: a stop equal to the current position yields an empty leg (no cells, no cost), and the direction state resets at every stop because each leg runs a fresh search.

