        public RoutePlanningException(String message) { super(message); }
    }

    private static final char[] DIR_CHARS = {'E', 'N', 'S', 'W'};
    private static final int[] DX = {1, 0, 0, -1};
    private static final int[] DY = {0, -1, 1, 0};

    private static final byte NONE = 0, SHELF = 1, ONE_WAY = 2, DOCK = 3, NARROW = 4;

    private final int width, height;
    private final byte[][] feature;
    private final char[][] oneWayDir;

    public WarehousePathsPlanner(int width, int height) {
        if (width <= 0 || height <= 0) throw new LayoutException("Grid dimensions must be positive");
        this.width = width; this.height = height;
        this.feature = new byte[height][width];
        this.oneWayDir = new char[height][width];
    }

    public WarehousePathsPlanner withShelf(int x, int y) { install(SHELF, x, y, '\0'); return this; }
    public WarehousePathsPlanner withOneWayAisle(int x, int y, char direction) {
        if (direction != 'N' && direction != 'E' && direction != 'S' && direction != 'W')
            throw new LayoutException("Invalid direction '" + direction + "'");
        install(ONE_WAY, x, y, direction);
        return this;
    }
    public WarehousePathsPlanner withDockingBay(int x, int y) { install(DOCK, x, y, '\0'); return this; }
    public WarehousePathsPlanner withNarrowAisle(int x, int y) { install(NARROW, x, y, '\0'); return this; }

    private void install(byte f, int x, int y, char dir) {
        if (x < 0 || y < 0 || x >= width || y >= height)
            throw new LayoutException("Cell (" + x + "," + y + ") is out of bounds");
        if (feature[y][x] != NONE)
            throw new LayoutException("Cell (" + x + "," + y + ") already has a feature");
        feature[y][x] = f;
        oneWayDir[y][x] = dir;
    }
