import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

public class RankedBallotsIndex {

    public record Standing(String candidate, int votes) {
    }

    /**
     * One registered ballot: a defensive copy of its ranking plus a
     * forward-only cursor that always sits on the assigned candidate
     * (or past the end once the ballot is exhausted).
     */
    private static final class Ballot {
        final List<String> ranking;
        int cursor;

        Ballot(List<String> ranking) {
            this.ranking = ranking;
            this.cursor = 0;
        }
    }

    /** All ballots, in insertion order. Index is the ballot's id. */
    private final List<Ballot> ballots = new ArrayList<>();

    /** Every name that has ever appeared on any ballot. */
    private final Set<String> knownCandidates = new HashSet<>();

    /** Names that have been eliminated. */
    private final Set<String> eliminated = new HashSet<>();

    /** Vote counts for active candidates only (missing key means 0). */
    private final Map<String, Integer> counts = new HashMap<>();

    /** Ballot ids currently assigned to each active candidate. */
    private final Map<String, List<Integer>> assignedBallots = new HashMap<>();

    private int exhaustedCount = 0;
    private int activeBallots = 0;

    public void addBallot(List<String> ranking) {
        if (ranking == null || ranking.isEmpty()) {
            throw new IllegalArgumentException("Ballot must rank at least one candidate");
        }
        for (String name : ranking) {
            if (name == null) {
                throw new IllegalArgumentException("Ballot must not contain null candidates");
            }
        }
        Set<String> seen = new HashSet<>();
        for (String name : ranking) {
            if (!seen.add(name)) {
                throw new IllegalArgumentException("Duplicate candidate on ballot: " + name);
            }
        }

        // Defensive copy; the caller's list may be mutated afterwards.
        List<String> copy = new ArrayList<>(ranking);
        knownCandidates.addAll(copy);

        Ballot ballot = new Ballot(copy);
        int id = ballots.size();
        ballots.add(ballot);

        // Position the cursor on the first still-standing preference.
        assignFromCursor(ballot, id);
    }

    public void eliminate(String candidate) {
        if (candidate == null) {
            throw new IllegalArgumentException("Candidate must not be null");
        }
        if (!knownCandidates.contains(candidate)) {
            throw new IllegalArgumentException("Unknown candidate: " + candidate);
        }
        if (eliminated.contains(candidate)) {
            throw new IllegalArgumentException("Candidate already eliminated: " + candidate);
        }

        eliminated.add(candidate);
        counts.remove(candidate);
        List<Integer> affected = assignedBallots.remove(candidate);
        if (affected == null) {
            return; // zero current votes; nothing to transfer
        }
        for (Integer id : affected) {
            Ballot ballot = ballots.get(id);
            ballot.cursor++; // step past the just-eliminated candidate
            assignFromCursor(ballot, id);
        }
    }

    public int countFor(String candidate) {
        if (candidate == null) {
            throw new IllegalArgumentException("Candidate must not be null");
        }
        if (!knownCandidates.contains(candidate)) {
            throw new IllegalArgumentException("Unknown candidate: " + candidate);
        }
        return counts.getOrDefault(candidate, 0);
    }

    public Set<String> activeCandidates() {
        Set<String> active = new HashSet<>(knownCandidates);
        active.removeAll(eliminated);
        return Collections.unmodifiableSet(active);
    }

    public List<Standing> leaderboard() {
        List<Standing> board = new ArrayList<>();
        for (String candidate : knownCandidates) {
            if (!eliminated.contains(candidate)) {
                board.add(new Standing(candidate, counts.getOrDefault(candidate, 0)));
            }
        }
        board.sort(Comparator.comparingInt(Standing::votes).reversed()
                .thenComparing(Standing::candidate));
        return Collections.unmodifiableList(board);
    }

    public Optional<String> majorityWinner() {
        int n = activeBallots;
        if (n == 0) {
            return Optional.empty();
        }
        for (Map.Entry<String, Integer> entry : counts.entrySet()) {
            if (2 * entry.getValue() > n) {
                return Optional.of(entry.getKey());
            }
        }
        return Optional.empty();
    }

    public int exhaustedCount() {
        return exhaustedCount;
    }

    public int activeBallots() {
        return activeBallots;
    }

    public int totalBallots() {
        return ballots.size();
    }

    /**
     * Advances the ballot's cursor forward past every eliminated name and
     * re-assigns the ballot to the first active candidate it lands on
     * (updating counts and bookkeeping), or marks it exhausted.
     * The cursor never moves backwards and never re-scans earlier entries.
     */
    private void assignFromCursor(Ballot ballot, int id) {
        while (ballot.cursor < ballot.ranking.size()
                && eliminated.contains(ballot.ranking.get(ballot.cursor))) {
            ballot.cursor++;
        }
        if (ballot.cursor < ballot.ranking.size()) {
            String assigned = ballot.ranking.get(ballot.cursor);
            counts.merge(assigned, 1, Integer::sum);
            assignedBallots.computeIfAbsent(assigned, k -> new ArrayList<>()).add(id);
            activeBallots++;
        } else {
            exhaustedCount++;
        }
    }
}
```

A few notes on the design:

- **Forward-only cursors.** Each `Ballot` keeps a `cursor` into its ranking. `addBallot` positions it once; `eliminate` advances it only for affected ballots, skipping names eliminated earlier. Nothing is ever re-scanned from the beginning.
- **O(affected) elimination.** `assignedBallots` maps each active candidate to the ids of the ballots currently assigned to it, so `eliminate` touches only the ballots that must move.
- **Defensive copy.** `addBallot` copies the incoming list before storing anything, so later caller mutations are harmless; validation happens before any state changes, so rejected ballots leave the index untouched.
- **Snapshot returns.** `activeCandidates()` and `leaderboard()` build fresh copies wrapped with `Collections.unmodifiable*`, so mutation attempts throw `UnsupportedOperationException` and later changes to the index don't leak into earlier snapshots.
- **Invariants.** `activeBallots` is incremented only when a ballot lands on an active candidate and `exhaustedCount` only when it runs off the end, so `totalBallots() == activeBallots() + exhaustedCount()` and the sum of active vote counts equals `activeBallots()` hold after every call.

The bug is in `assignFromCursor`: it increments `activeBallots`/`exhaustedCount` on *every* call, including during re-assignment after an elimination. A ballot that transfers from an eliminated candidate to another active candidate is still just one active ballot, but it was being counted twice (that's why "expected 4 but was 6", "expected 1 but was 5", etc. — counts were inflated by exactly the number of transfers).

The fix is to distinguish initial assignment (a new ballot enters the totals) from re-assignment (an existing ballot moves; totals only change if it transitions from active to exhausted). I track each ballot's current assignment explicitly:

