```java
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class GardenWateringIndex {

    public static final double FIELD_CAPACITY_MM = 50.0;
    public static final double MAX_APPLICATION_MM = 30.0;
    public static final int HISTORY_DAYS = 7;

    public record WeatherDay(double minTempC, double maxTempC, double rainMm) {
    }

    public record Bed(String name, double areaSqm, double cropFactor) {
    }

    public record Watering(String bedName, double depthMm, double litres, boolean partial) {
    }

    private final double roofCatchmentSqm;
    private final double tankCapacityLitres;

    private final Map<String, Bed> beds = new LinkedHashMap<>();
    private final Map<String, Double> moisture = new LinkedHashMap<>();

    private final Deque<WeatherDay> history = new ArrayDeque<>();
    private int totalDaysRecorded = 0;

    private double tankLitres = 0.0;

    public GardenWateringIndex(double roofCatchmentSqm, double tankCapacityLitres) {
        if (roofCatchmentSqm <= 0) {
            throw new IllegalArgumentException("Roof catchment area must be positive");
        }
        if (tankCapacityLitres <= 0) {
            throw new IllegalArgumentException("Tank capacity must be positive");
        }
        this.roofCatchmentSqm = roofCatchmentSqm;
        this.tankCapacityLitres = tankCapacityLitres;
    }

    public void addBed(Bed bed) {
        if (bed == null) {
            throw new NullPointerException("Bed must not be null");
        }
        String name = bed.name();
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("Bed name must not be blank");
        }
        if (beds.containsKey(name)) {
            throw new IllegalArgumentException("Duplicate bed name: " + name);
        }
        if (bed.areaSqm() <= 0) {
            throw new IllegalArgumentException("Bed area must be positive");
        }
        if (bed.cropFactor() <= 0 || bed.cropFactor() > 2) {
            throw new IllegalArgumentException("Crop factor must be in (0.0, 2.0]");
        }
        beds.put(name, bed);
        moisture.put(name, FIELD_CAPACITY_MM);
    }

    public void recordDay(WeatherDay day) {
        if (day == null) {
            throw new NullPointerException("Weather day must not be null");
        }
        if (day.maxTempC() < day.minTempC()) {
            throw new IllegalArgumentException("maxTempC must not be below minTempC");
        }
        if (day.minTempC() < -50.0) {
            throw new IllegalArgumentException("minTempC must be at or above -50.0");
        }
        if (day.maxTempC() > 60.0) {
            throw new IllegalArgumentException("maxTempC must be at or below 60.0");
        }
        if (day.rainMm() < 0) {
            throw new IllegalArgumentException("rainMm must not be negative");
        }

        history.addLast(day);
        while (history.size() > HISTORY_DAYS) {
            history.removeFirst();
        }
        totalDaysRecorded++;

        tankLitres = Math.min(tankCapacityLitres, tankLitres + day.rainMm() * roofCatchmentSqm);

        double et0 = Math.max(0.0, 0.15 * day.maxTempC() + 0.05 * day.minTempC());
        if (hotSpell()) {
            et0 *= 1.25;
        }

        for (Map.Entry<String, Bed> entry : beds.entrySet()) {
            Bed bed = entry.getValue();
            double m = Math.min(FIELD_CAPACITY_MM, moisture.get(entry.getKey()) + 0.9 * day.rainMm());
            moisture.put(entry.getKey(), Math.max(0.0, m - et0 * bed.cropFactor()));
        }
    }

    public List<Watering> wateringPlan() {
        double trigger;
        if (rainRelief()) {
            trigger = 0.35 * FIELD_CAPACITY_MM;
        } else if (hotSpell()) {
            trigger = 0.65 * FIELD_CAPACITY_MM;
        } else {
            trigger = 0.5 * FIELD_CAPACITY_MM;
        }

        List<Watering> plan = new ArrayList<>();
        double budget = tankLitres;

        for (Map.Entry<String, Bed> entry : beds.entrySet()) {
            if (budget <= 0) {
                break;
            }
            String name = entry.getKey();
            Bed bed = entry.getValue();
            double current = moisture.get(name);
            if (current >= trigger) {
                continue;
            }
            double required = FIELD_CAPACITY_MM - current;
            double depth = Math.min(required, MAX_APPLICATION_MM);
            double litres = depth * bed.areaSqm();
            if (litres > budget) {
                depth = budget / bed.areaSqm();
                litres = budget;
            }
            boolean partial = required - depth > 1e-9;
            plan.add(new Watering(name, depth, litres, partial));
            budget -= litres;
        }
        return plan;
    }

    public List<Watering> water() {
        List<Watering> plan = wateringPlan();
        for (Watering w : plan) {
            tankLitres -= w.litres();
            moisture.put(w.bedName(), Math.min(FIELD_CAPACITY_MM, moisture.get(w.bedName()) + w.depthMm()));
        }
        return plan;
    }

    public double moistureOf(String bedName) {
        Double m = moisture.get(bedName);
        if (m == null) {
            throw new IllegalArgumentException("Unknown bed: " + bedName);
        }
        return m;
    }

    public double tankLitres() {
        return tankLitres;
    }

    public int daysRecorded() {
        return totalDaysRecorded;
    }

    public boolean hotSpell() {
        int count = Math.min(3, totalDaysRecorded);
        if (count == 0) {
            return false;
        }
        double sum = 0.0;
        int i = 0;
        Iterator<WeatherDay> it = history.descendingIterator();
        while (it.hasNext() && i < count) {
            sum += it.next().maxTempC();
            i++;
        }
        return sum / count >= 30.0;
    }

    public double recentRainMm() {
        double sum = 0.0;
        for (WeatherDay day : history) {
            sum += day.rainMm();
        }
        return sum;
    }

    public double averageMaxTemp(int days) {
        if (days <= 0) {
            throw new IllegalArgumentException("Day count must be positive");
        }
        if (totalDaysRecorded == 0) {
            throw new IllegalArgumentException("No days recorded yet");
        }
        int count = Math.min(days, HISTORY_DAYS);
        count = Math.min(count, totalDaysRecorded);
        double sum = 0.0;
        int i = 0;
        Iterator<WeatherDay> it = history.descendingIterator();
        while (it.hasNext() && i < count) {
            sum += it.next().maxTempC();
            i++;
        }
        return sum / count;
    }

    public List<String> bedNames() {
        return new ArrayList<>(beds.keySet());
    }

    private boolean rainRelief() {
        int count = Math.min(2, totalDaysRecorded);
        if (count == 0) {
            return false;
        }
        double sum = 0.0;
        int i = 0;
        Iterator<WeatherDay> it = history.descendingIterator();
        while (it.hasNext() && i < count) {
            sum += it.next().rainMm();
            i++;
        }
        return sum >= 10.0;
    }
}
```

## Summary of changes

1. **`averageMaxTemp`**: changed `history.iterator()` to `history.descendingIterator()` so the average covers the *most recent* `min(days, 7, daysRecorded)` days. With your 8-day sequence, `averageMaxTemp(1)` now returns 40.0 and `averageMaxTemp(2)` returns 28.0.
2. **`recordDay`**: changed `moisture.get(entry.getKey()) + day.rainMm()` to `moisture.get(entry.getKey()) + 0.9 * day.rainMm()` so rain reaches the soil at the 90% canopy-uptake rate, while the tank still receives the full `rainMm × roofCatchmentSqm` runoff as specified.

Everything else (validation order, hot spell and rain relief logic, plan/budget logic, `water()` application) matches the spec and was left untouched.

