```java
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.regex.Pattern;

public final class SearchSnippetsCodec {

    public static final class InvalidFormatException extends RuntimeException {
        public InvalidFormatException(String message) {
            super(message);
        }
    }

    /** A half-open character range: [start, end). */
    public record Highlight(int start, int end) {
    }

    /**
     * A search result snippet: an excerpt of a document, the term matches
     * inside it (offsets into {@code text}) and the query terms it was
     * built from.
     */
    public record Snippet(String text, List<Highlight> highlights, List<String> terms) {
        public Snippet {
            Objects.requireNonNull(text, "text");
            Objects.requireNonNull(highlights, "highlights");
            Objects.requireNonNull(terms, "terms");
            highlights = List.copyOf(highlights);
            terms = List.copyOf(terms);
        }
    }

    private static final Pattern RANGE_PATTERN = Pattern.compile("\\d+-\\d+");

    // ------------------------------------------------------------------
    // 1. Snippet extraction
    // ------------------------------------------------------------------

    public Snippet extract(String document, List<String> terms, int maxWidth) {
        Objects.requireNonNull(document, "document");
        Objects.requireNonNull(terms, "terms");
        if (maxWidth < 1) {
            throw new IllegalArgumentException("maxWidth must be positive");
        }
        for (String term : terms) {
            Objects.requireNonNull(term, "term");
            if (term.isEmpty()) {
                throw new IllegalArgumentException("term must not be empty");
            }
        }

        // Left-to-right, non-overlapping matching.
        int n = document.length();
        List<Highlight> matches = new ArrayList<>();
        int i = 0;
        while (i < n) {
            int len = matchLengthAt(document, i, terms);
            if (len > 0) {
                matches.add(new Highlight(i, i + len));
                i += len;
            } else {
                i++;
            }
        }

        int w = Math.min(maxWidth, n);
        int s = bestWindowStart(matches, n, w);

        List<Highlight> windowHighlights = new ArrayList<>();
        for (Highlight m : matches) {
            if (m.start() >= s && m.end() <= s + w) {
                windowHighlights.add(new Highlight(m.start() - s, m.end() - s));
            }
        }
        return new Snippet(document.substring(s, s + w), windowHighlights, terms);
    }

    /** Length of the first term (in list order) matching at {@code index}, or 0. */
    private static int matchLengthAt(String document, int index, List<String> terms) {
        int n = document.length();
        for (String term : terms) {
            int len = term.length();
            if (index + len > n) {
                continue;
            }
            if (!document.regionMatches(false, index, term, 0, len)) {
                continue;
            }
            boolean leftOk = index == 0
                    || !Character.isLetterOrDigit(document.charAt(index - 1));
            boolean rightOk = index + len == n
                    || !Character.isLetterOrDigit(document.charAt(index + len));
            if (leftOk && rightOk) {
                return len;
            }
        }
        return 0;
    }

    /**
     * Window start in {@code [0, n - w]} containing the most matches;
     * ties broken by the smallest start. Uses a difference array so the
     * scan is linear in the document length plus the number of matches.
     */
    private static int bestWindowStart(List<Highlight> matches, int n, int w) {
        int last = n - w;
        int[] diff = new int[last + 2];
        for (Highlight m : matches) {
            // A match [a, b) is fully inside window [s, s + w) iff
            // s <= a and s >= b - w.
            int lo = Math.max(0, m.end() - w);
            int hi = Math.min(m.start(), last);
            if (lo <= hi) {
                diff[lo]++;
                diff[hi + 1]--;
            }
        }
        int bestStart = 0;
        int bestCount = 0;
        int count = 0;
        for (int p = 0; p <= last; p++) {
            count += diff[p];
            if (count >= bestCount) {
                bestCount = count;
                bestStart = p;
            }
        }
        return bestStart;
    }

    // ------------------------------------------------------------------
    // 2. Rendering
    // ------------------------------------------------------------------

    public String render(Snippet snippet) {
        return render(snippet, "[", "]");
    }

    public String render(Snippet snippet, String openMarker, String closeMarker) {
        Objects.requireNonNull(snippet, "snippet");
        Objects.requireNonNull(openMarker, "openMarker");
        Objects.requireNonNull(closeMarker, "closeMarker");
        String text = snippet.text();
        validateHighlights(text, snippet.highlights());

        StringBuilder sb = new StringBuilder(text.length() + 16);
        int pos = 0;
        for (Highlight h : snippet.highlights()) {
            sb.append(text, pos, h.start());
            sb.append(openMarker);
            sb.append(text, h.start(), h.end());
            sb.append(closeMarker);
            pos = h.end();
        }
        sb.append(text, pos, text.length());
        return sb.toString();
    }

    // ------------------------------------------------------------------
    // 3. Highlight validation (render / encode)
    // ------------------------------------------------------------------

    private static void validateHighlights(String text, List<Highlight> highlights) {
        boolean first = true;
        int prevEnd = 0;
        for (Highlight h : highlights) {
            if (h.start() < 0 || h.start() >= h.end()) {
                throw new IllegalArgumentException(
                        "invalid highlight: " + h.start() + "-" + h.end());
            }
            if (h.end() > text.length()) {
                throw new IllegalArgumentException(
                        "highlight out of bounds: " + h.start() + "-" + h.end());
            }
            if (!first && h.start() < prevEnd) {
                throw new IllegalArgumentException(
                        "highlights out of order or overlapping");
            }
            prevEnd = h.end();
            first = false;
        }
    }

    // ------------------------------------------------------------------
    // 4. Wire format
    // ------------------------------------------------------------------

    public String encode(Snippet snippet) {
        Objects.requireNonNull(snippet, "snippet");
        validateHighlights(snippet.text(), snippet.highlights());
        for (String term : snippet.terms()) {
            if (term.isEmpty()) {
                throw new IllegalArgumentException("term must not be empty");
            }
        }

        StringBuilder sb = new StringBuilder("SSNP1|");
        List<String> terms = snippet.terms();
        for (int i = 0; i < terms.size(); i++) {
            if (i > 0) {
                sb.append('+');
            }
            appendEscaped(sb, terms.get(i), true);
        }
        sb.append('|');
        List<Highlight> highlights = snippet.highlights();
        for (int i = 0; i < highlights.size(); i++) {
            if (i > 0) {
                sb.append(',');
            }
            Highlight h = highlights.get(i);
            sb.append(h.start()).append('-').append(h.end());
        }
        sb.append('|');
        appendEscaped(sb, snippet.text(), false);
        return sb.toString();
    }

    private static void appendEscaped(StringBuilder sb, String s, boolean queryField) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '\\' -> sb.append("\\\\");
                case '|' -> sb.append("\\|");
                case '\n' -> sb.append("\\n");
                case '+' -> {
                    if (queryField) {
                        sb.append("\\+");
                    } else {
                        sb.append('+');
                    }
                }
                default -> sb.append(c);
            }
        }
    }

    public Snippet decode(String wire) {
        Objects.requireNonNull(wire, "wire");

        // 1. Split into fields.
        List<String> fields = splitUnescaped(wire, '|');
        if (fields.size() != 4) {
            throw new InvalidFormatException(
                    "expected 4 fields, found " + fields.size());
        }

        // 2. Header.
        if (!fields.get(0).equals("SSNP1")) {
            throw new InvalidFormatException("invalid header");
        }

        // 3. Query terms.
        List<String> terms = new ArrayList<>();
        if (!fields.get(1).isEmpty()) {
            for (String rawTerm : splitUnescaped(fields.get(1), '+')) {
                String term = unescapeQuery(rawTerm);
                if (term.isEmpty()) {
                    throw new InvalidFormatException("empty query term");
                }
                terms.add(term);
            }
        }

        // 4. Highlight ranges.
        List<Highlight> highlights = new ArrayList<>();
        if (!fields.get(2).isEmpty()) {
            for (String part : fields.get(2).split(",", -1)) {
                if (!RANGE_PATTERN.matcher(part).matches()) {
                    throw new InvalidFormatException("invalid highlight: " + part);
                }
                int dash = part.indexOf('-');
                int start;
                int end;
                try {
                    start = Integer.parseInt(part.substring(0, dash));
                    end = Integer.parseInt(part.substring(dash + 1));
                } catch (NumberFormatException e) {
                    throw new InvalidFormatException("invalid highlight: " + part);
                }
                if (start >= end) {
                    throw new InvalidFormatException("invalid highlight: " + part);
                }
                highlights.add(new Highlight(start, end));
            }
        }

        // 5. Text.
        String text = unescapeText(fields.get(3));

        // 6. Range checks against the text.
        for (int i = 0; i < highlights.size(); i++) {
            Highlight h = highlights.get(i);
            if (h.end() > text.length()) {
                throw new InvalidFormatException(
                        "highlight out of bounds: " + h.start() + "-" + h.end());
            }
            if (i > 0 && h.start() < highlights.get(i - 1).end()) {
                throw new InvalidFormatException(
                        "highlights out of order or overlapping");
            }
        }

        return new Snippet(text, highlights, terms);
    }

    /**
     * Splits {@code s} on unescaped occurrences of {@code sep}. While
     * scanning, a backslash always consumes the character that follows it
     * (if any), so an escaped separator is kept in the current part. The
     * returned parts retain their escape sequences.
     */
    private static List<String> splitUnescaped(String s, char sep) {
        List<String> parts = new ArrayList<>();
        StringBuilder cur = new StringBuilder();
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            if (c == '\\' && i + 1 < s.length()) {
                cur.append(c).append(s.charAt(i + 1));
                i += 2;
            } else if (c == sep) {
                parts.add(cur.toString());
                cur.setLength(0);
                i++;
            } else {
                cur.append(c);
                i++;
            }
        }
        parts.add(cur.toString());
        return parts;
    }

    private static String unescapeQuery(String raw) {
        StringBuilder sb = new StringBuilder(raw.length());
        int i = 0;
        while (i < raw.length()) {
