```java
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

public final class WarehousePathsReconciler {

    public enum IssueType { START_MISMATCH, ROUTE_DEVIATION, END_MISMATCH }

    public record PathIssue(String robotId, IssueType type, String detail) {
    }

    public record ReconciliationReport(List<String> missingRobots,
                                       List<String> unexpectedRobots,
                                       List<PathIssue> issues) {
        public boolean isClean() {
            return missingRobots.isEmpty() && unexpectedRobots.isEmpty() && issues.isEmpty();
        }
    }

    private static final class PathData {
        final String start;
        final List<String> cells; // includes the start cell at index 0

        PathData(String start, List<String> cells) {
            this.start = start;
            this.cells = cells;
        }
    }

    private final int width;
    private final int height;
    private final Set<String> racks = new HashSet<>();
    private final Map<String, PathData> plans = new LinkedHashMap<>();
    private final Map<String, PathData> executions = new LinkedHashMap<>();

    public WarehousePathsReconciler(int width, int height, Set<String> rackCells) {
        if (width < 1 || width > 26) {
            throw new IllegalArgumentException("Width must be between 1 and 26");
        }
        if (height < 1) {
            throw new IllegalArgumentException("Height must be positive");
        }
        this.width = width;
        this.height = height;
        if (rackCells != null) {
            for (String cell : rackCells) {
                int[] pos = parseCell(cell);
                if (pos == null || pos[0] >= width || pos[1] < 1 || pos[1] > height) {
                    throw new IllegalArgumentException("Invalid cell: " + cell);
                }
                racks.add(cellName(pos[0], pos[1]));
            }
        }
    }

    public void planPath(String robotId, String startCell, String moves) {
        store(plans, robotId, startCell, moves, true);
    }

    public void recordExecution(String robotId, String startCell, String moves) {
        store(executions, robotId, startCell, moves, false);
    }

    public ReconciliationReport reconcile() {
        List<String> missingRobots = new ArrayList<>();
        List<String> unexpectedRobots = new ArrayList<>();
        List<PathIssue> issues = new ArrayList<>();

        for (String id : plans.keySet()) {
            if (!executions.containsKey(id)) {
                missingRobots.add(id);
            }
        }
        Collections.sort(missingRobots);

        for (String id : executions.keySet()) {
            if (!plans.containsKey(id)) {
                unexpectedRobots.add(id);
            }
        }
        Collections.sort(unexpectedRobots);

        List<String> commonIds = new ArrayList<>();
        for (String id : plans.keySet()) {
            if (executions.containsKey(id)) {
                commonIds.add(id);
            }
        }
        Collections.sort(commonIds);

        for (String id : commonIds) {
            PathData planned = plans.get(id);
            PathData executed = executions.get(id);

            if (!planned.start.equals(executed.start)) {
                issues.add(new PathIssue(id, IssueType.START_MISMATCH,
                        "start: planned " + planned.start + ", executed " + executed.start));
            }

            List<String> pc = planned.cells;
            List<String> ec = executed.cells;
            int limit = Math.min(pc.size(), ec.size());
            int firstDiff = -1;
            for (int i = 0; i < limit; i++) {
                if (!pc.get(i).equals(ec.get(i))) {
                    firstDiff = i;
                    break;
                }
            }
            if (firstDiff >= 0) {
                issues.add(new PathIssue(id, IssueType.ROUTE_DEVIATION,
                        "first cell difference at index " + firstDiff
                                + ": planned " + pc.get(firstDiff)
                                + ", executed " + ec.get(firstDiff)));
            } else if (pc.size() != ec.size()) {
                issues.add(new PathIssue(id, IssueType.ROUTE_DEVIATION,
                        "route length differs: planned " + pc.size()
                                + " cells, executed " + ec.size() + " cells"));
            }

            String plannedEnd = pc.get(pc.size() - 1);
            String executedEnd = ec.get(ec.size() - 1);
            if (!plannedEnd.equals(executedEnd)) {
                issues.add(new PathIssue(id, IssueType.END_MISMATCH,
                        "end: planned " + plannedEnd + ", executed " + executedEnd));
            }
        }

        return new ReconciliationReport(
                Collections.unmodifiableList(missingRobots),
                Collections.unmodifiableList(unexpectedRobots),
                Collections.unmodifiableList(issues));
    }

    private void store(Map<String, PathData> target, String robotId, String startCell,
                       String moves, boolean isPlan) {
        if (robotId == null) {
            throw new IllegalArgumentException("Robot id must not be null");
        }
        if (startCell == null) {
            throw new IllegalArgumentException("Start cell must not be null");
        }
        if (moves == null) {
            throw new IllegalArgumentException("Moves must not be null");
        }

        int[] start = parseCell(startCell);
        if (start == null || start[0] >= width || start[1] < 1 || start[1] > height) {
            throw new IllegalArgumentException("Invalid cell: " + startCell);
        }
        String startName = cellName(start[0], start[1]);
        if (racks.contains(startName)) {
            throw new IllegalArgumentException("Start cell " + startName + " is a rack");
        }

        List<String> cells = new ArrayList<>();
        cells.add(startName);
        int col = start[0];
        int row = start[1];

        for (int i = 0; i < moves.length(); i++) {
            char move = moves.charAt(i);
            if (move != 'N' && move != 'E' && move != 'S' && move != 'W') {
                throw new IllegalArgumentException("Invalid move character: '" + move + "'");
            }
            int nextCol = col;
            int nextRow = row;
            switch (move) {
                case 'N': nextRow = row + 1; break;
                case 'S': nextRow = row - 1; break;
                case 'E': nextCol = col + 1; break;
                case 'W': nextCol = col - 1; break;
                default: throw new AssertionError();
            }
            if (nextCol < 0 || nextCol >= width || nextRow < 1 || nextRow > height) {
                throw new IllegalArgumentException("Move from " + cellName(col, row)
                        + " going " + move + " leaves the warehouse");
            }
            String nextName = cellName(nextCol, nextRow);
            if (racks.contains(nextName)) {
                throw new IllegalArgumentException("Move from " + cellName(col, row)
                        + " to " + nextName + " enters a rack");
            }
            cells.add(nextName);
            col = nextCol;
            row = nextRow;
        }

        if (target.containsKey(robotId)) {
            if (isPlan) {
                throw new IllegalStateException("Path already planned for robot " + robotId);
            } else {
                throw new IllegalStateException("Execution already recorded for robot " + robotId);
            }
        }
        target.put(robotId, new PathData(startName, cells));
    }

    /**
     * Parses a cell name into {column (0-based), row (1-based)},
     * or returns null if the name is malformed.
     */
    private static int[] parseCell(String cell) {
        if (cell == null || cell.length() < 2) {
            return null;
        }
        char c = cell.charAt(0);
        if (c < 'A' || c > 'Z') {
            return null;
        }
        int col = c - 'A';
        String digits = cell.substring(1);
        if (digits.charAt(0) == '0' && digits.length() > 1) {
            return null; // leading zeros are not allowed
        }
        long row = 0;
        for (int i = 0; i < digits.length(); i++) {
            char d = digits.charAt(i);
            if (d < '0' || d > '9') {
                return null;
            }
            row = row * 10 + (d - '0');
            if (row > Integer.MAX_VALUE) {
                break; // will fail the bounds check anyway
            }
        }
        if (row > Integer.MAX_VALUE) {
            row = Integer.MAX_VALUE + 1L; // force out-of-bounds
        }
        return new int[]{col, (int) row};
    }

    private static String cellName(int col, int row) {
        return String.valueOf((char) ('A' + col)) + row;
    }
}
```

Notes on the implementation:

- **Cell parsing** (`parseCell`) enforces the exact format: one uppercase letter followed by digits with no leading zeros; a long row number is safely handled so it fails the bounds check rather than overflowing.
- **Eager validation** happens in the prescribed order: null checks → start-cell format/bounds → start-cell rack → per-move (character, then grid bounds, then rack) → duplicate check last.
- **Rack cells** are normalized to canonical names in the constructor; each one is validated with the exact message `"Invalid cell: " + cell`.
- **Reconcile** is purely read-only: it computes missing/unexpected ids and the three independent issue types (start, route, end), sorted by robot id and then by the declaration order of `IssueType` (achieved by checking them in that order per robot while iterating ids in ascending order). It can be called repeatedly with identical results.

