        col = nc; row = nr;
    }
    if (map.containsKey(robotId)) {
        throw new IllegalStateException(isPlan ? "Path already planned for robot " + robotId : "Execution already recorded for robot " + robotId);
    }
    map.put(robotId, new PathData(start, cells));
}
