src/main/java/StockPortfolioMigrator.java
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;
import java.util.regex.Pattern;

public final class StockPortfolioMigrator {

    public static final class MigrationException extends RuntimeException {
        public MigrationException(String message) {
            super(message);
        }
    }

    public record Position(String symbol, long quantity, long averageCostCents, long realizedGainCents) {
    }

    private static final Pattern SYMBOL_PATTERN = Pattern.compile("[A-Z][A-Z0-9.]{0,7}");

    private static final class State {
        long quantity;
        long averageCost;
        long realizedGain;
        boolean hasPosition;
        boolean hasTrade;
    }

    private StockPortfolioMigrator() {
    }

    public static List<Position> analyze(String v1) {
        Map<String, State> states = new TreeMap<>();
        parse(v1, states);
        List<Position> result = new ArrayList<>();
        for (Map.Entry<String, State> e : states.entrySet()) {
            State s = e.getValue();
            result.add(new Position(e.getKey(), s.quantity,
                    s.quantity == 0 ? 0L : s.averageCost, s.realizedGain));
        }
        return List.copyOf(result);
    }

    public static String migrate(String v1) {
        Map<String, State> states = new TreeMap<>();
        String accountId = parse(v1, states);
        StringBuilder sb = new StringBuilder();
        sb.append("PORTFOLIO-V2 ").append(accountId);
        long total = 0;
        for (Map.Entry<String, State> e : states.entrySet()) {
            State s = e.getValue();
            long avg = s.quantity == 0 ? 0L : s.averageCost;
            sb.append("\nPOSITION ").append(e.getKey()).append(' ')
                    .append(s.quantity).append(' ')
                    .append(avg).append(' ')
                    .append(s.realizedGain);
            total += s.realizedGain;
        }
        sb.append("\nTOTAL ").append(total);
        return sb.toString();
    }

    // ------------------------------------------------------------------
    // Parsing / validation / replay
    // ------------------------------------------------------------------

    private static String parse(String v1, Map<String, State> states) {
        Objects.requireNonNull(v1);

        // A single trailing newline does not create an extra line.
        String content = v1.endsWith("\n") ? v1.substring(0, v1.length() - 1) : v1;
        if (content.isEmpty()) {
            throw new MigrationException("Migration failed: empty input");
        }

        String[] lines = content.split("\n", -1);

        // Header (line 1)
        String[] header = tokenize(lines[0]);
        if (header.length == 0) {
            throw new MigrationException("Line 1: blank line");
        }
        if (header.length == 1 && header[0].equals("PORTFOLIO-V1")) {
            throw new MigrationException("Line 1: missing account id");
        }
        if (header.length != 2 || !header[0].equals("PORTFOLIO-V1")) {
            throw new MigrationException("Line 1: invalid header");
        }
        String accountId = header[1];

        // Records (lines 2+)
        for (int i = 1; i < lines.length; i++) {
            processRecord(lines[i], i + 1, states);
        }
        return accountId;
    }

    private static void processRecord(String line, int lineNumber, Map<String, State> states) {
        String[] f = tokenize(line);
        if (f.length == 0) {
            throw new MigrationException("Line " + lineNumber + ": blank line");
        }
        String kind = f[0];
        if (kind.equals("POSITION")) {
            applyPosition(f, lineNumber, states);
        } else if (kind.equals("TRADE")) {
            applyTrade(f, lineNumber, states);
        } else {
            throw new MigrationException("Line " + lineNumber + ": unknown record '" + kind + "'");
        }
    }

    private static void applyPosition(String[] f, int k, Map<String, State> states) {
        if (f.length != 4) {
            throw new MigrationException("Line " + k + ": POSITION requires 4 fields, got " + f.length);
        }
        String symbol = f[1];
        if (!isValidSymbol(symbol)) {
            throw new MigrationException("Line " + k + ": invalid symbol '" + symbol + "'");
        }
        long quantity = parseQuantity(f[2], k);
        long avgCost = parseNonNegative(f[3], k, "average cost");

        State existing = states.get(symbol);
        if (existing != null && existing.hasPosition) {
            throw new MigrationException("Line " + k + ": duplicate position for '" + symbol + "'");
        }
        if (existing != null && existing.hasTrade) {
            throw new MigrationException("Line " + k + ": position for '" + symbol + "' must precede its trades");
        }

        State s = new State();
        s.quantity = quantity;
        s.averageCost = avgCost;
        s.realizedGain = 0;
        s.hasPosition = true;
        states.put(symbol, s);
    }

    private static void applyTrade(String[] f, int k, Map<String, State> states) {
        if (f.length != 5) {
            throw new MigrationException("Line " + k + ": TRADE requires 5 fields, got " + f.length);
        }
        String symbol = f[1];
        if (!isValidSymbol(symbol)) {
            throw new MigrationException("Line " + k + ": invalid symbol '" + symbol + "'");
        }
        String side = f[2];
        if (!side.equals("BUY") && !side.equals("SELL")) {
            throw new MigrationException("Line " + k + ": invalid side '" + side + "'");
        }
        long quantity = parseQuantity(f[3], k);
        long price = parseNonNegative(f[4], k, "price");

        State s = states.computeIfAbsent(symbol, x -> new State());
        s.hasTrade = true;

        if (side.equals("BUY")) {
            if (s.quantity == 0) {
                s.averageCost = price;
            } else {
                s.averageCost = (s.quantity * s.averageCost + quantity * price) / (s.quantity + quantity);
            }
            s.quantity += quantity;
        } else {
            if (quantity > s.quantity) {
                throw new MigrationException("Line " + k + ": oversell of '" + symbol + "'");
            }
            s.realizedGain += (price - s.averageCost) * quantity;
            s.quantity -= quantity;
            if (s.quantity == 0) {
                s.averageCost = 0;
            }
        }
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private static boolean isValidSymbol(String s) {
        return SYMBOL_PATTERN.matcher(s).matches();
    }

    private static long parseQuantity(String token, int k) {
        long v;
        try {
            v = Long.parseLong(token);
        } catch (NumberFormatException e) {
            throw new MigrationException("Line " + k + ": invalid quantity '" + token + "'");
        }
        if (v < 1) {
            throw new MigrationException("Line " + k + ": invalid quantity '" + token + "'");
        }
        return v;
    }

    private static long parseNonNegative(String token, int k, String label) {
        long v;
        try {
            v = Long.parseLong(token);
        } catch (NumberFormatException e) {
            throw new MigrationException("Line " + k + ": invalid " + label + " '" + token + "'");
        }
        if (v < 0) {
            throw new MigrationException("Line " + k + ": invalid " + label + " '" + token + "'");
        }
        return v;
    }

    /**
