import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

public class AlertRulesCalculator {

    public enum Comparison { ABOVE, BELOW }

    public enum AlertState { FIRING, RESOLVED }

    public record Sample(long timestamp, double value) {
    }

    public record AlertRule(String metric, Comparison comparison, double threshold, int durationInSamples) {
    }

    public record Silence(String metric, long start, long end) {
    }

    public record AlertEvent(long timestamp, AlertState state) {
    }

    public static List<AlertEvent> evaluate(AlertRule rule, List<Sample> samples, List<Silence> silences) {
        Objects.requireNonNull(rule, "rule must not be null");
        Objects.requireNonNull(rule.metric(), "rule.metric must not be null");
        Objects.requireNonNull(rule.comparison(), "rule.comparison must not be null");
        if (rule.durationInSamples() < 1) {
            throw new IllegalArgumentException("duration must be at least 1");
        }
        validateSilencesSilently(silences);

        Objects.requireNonNull(samples, "samples must not be null");
        long previousTimestamp = Long.MIN_VALUE;
        boolean first = true;
        for (Sample sample : samples) {
            Objects.requireNonNull(sample, "sample must not be null");
            if (!first && sample.timestamp() <= previousTimestamp) {
                throw new IllegalArgumentException(
                        "samples must be sorted by strictly increasing timestamps");
            }
            previousTimestamp = sample.timestamp();
            first = false;
        }

        List<AlertEvent> events = new ArrayList<>();
        boolean firing = false;
        int streak = 0;

        for (Sample sample : samples) {
            long timestamp = sample.timestamp();
            double value = sample.value();
            boolean violates = (rule.comparison() == Comparison.ABOVE)
                    ? value > rule.threshold()
                    : value < rule.threshold();

            if (violates) {
                streak++;
                if (!firing && streak >= rule.durationInSamples() && !isSilenced(silences, rule.metric(), timestamp)) {
                    events.add(new AlertEvent(timestamp, AlertState.FIRING));
                    firing = true;
                }
            } else {
                streak = 0;
                if (firing) {
                    events.add(new AlertEvent(timestamp, AlertState.RESOLVED));
                    firing = false;
                }
            }
        }

        return events;
    }

    public static List<Silence> mergeSilences(List<Silence> silences) {
        validateSilencesSilently(silences);

        Map<String, List<Silence>> byMetric = new LinkedHashMap<>();
        for (Silence silence : silences) {
            byMetric.computeIfAbsent(silence.metric(), m -> new ArrayList<>()).add(silence);
        }

        List<Silence> result = new ArrayList<>();
        for (Map.Entry<String, List<Silence>> entry : byMetric.entrySet()) {
            List<Silence> group = entry.getValue();
            group.sort(Comparator.comparingLong(Silence::start).thenComparingLong(Silence::end));

            long currentStart = group.get(0).start();
            long currentEnd = group.get(0).end();

            for (int i = 1; i < group.size(); i++) {
                Silence next = group.get(i);
                if (next.start() < currentEnd) {
                    // Overlapping: extend the current window.
                    currentEnd = Math.max(currentEnd, next.end());
                } else {
                    result.add(new Silence(entry.getKey(), currentStart, currentEnd));
                    currentStart = next.start();
                    currentEnd = next.end();
                }
            }
            result.add(new Silence(entry.getKey(), currentStart, currentEnd));
        }

        result.sort(Comparator.comparing(Silence::metric).thenComparingLong(Silence::start));
        return result;
    }

    private static boolean isSilenced(List<Silence> silences, String metric, long timestamp) {
        for (Silence silence : silences) {
            if (silence.metric().equals(metric) || silence.metric().equals("*")) {
                if (silence.start() <= timestamp && timestamp < silence.end()) {
                    return true;
                }
            }
        }
        return false;
    }

    private static void validateSilencesSilently(List<Silence> silences) {
        Objects.requireNonNull(silences, "silences must not be null");
        for (Silence silence : silences) {
            Objects.requireNonNull(silence, "silence must not be null");
            Objects.requireNonNull(silence.metric(), "silence metric must not be null");
            if (silence.start() >= silence.end()) {
                throw new IllegalArgumentException("silence start must be before end");
            }
        }
    }
}
