import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public final class QueueTicketsReport {

    private static final Set<String> VALID_PRIORITIES =
            new LinkedHashSet<>(List.of("HIGH", "NORMAL", "LOW"));

    /** Immutable registration data for a ticket. */
    private static final class TicketSpec {
        final String id;
        final String priority;
        final int arrivalTick;
        final int durationTicks;

        TicketSpec(String id, String priority, int arrivalTick, int durationTicks) {
            this.id = id;
            this.priority = priority;
            this.arrivalTick = arrivalTick;
            this.durationTicks = durationTicks;
        }
    }

    /** Mutable simulation state for a ticket. */
    private static final class SimTicket {
        final String id;
        final String priority;
        final int arrivalTick;
        final int durationTicks;
        int startTick = -1;
        String counterId = null;

        SimTicket(TicketSpec spec) {
            this.id = spec.id;
            this.priority = spec.priority;
            this.arrivalTick = spec.arrivalTick;
            this.durationTicks = spec.durationTicks;
        }
    }

    /** Mutable simulation state for a counter. */
    private static final class SimCounter {
        final String id;
        final Set<String> servablePriorities; // empty means "any priority"
        SimTicket currentTicket = null;
        int busyUntil = 0;
        int servedCount = 0;
        int busyTicks = 0;

        SimCounter(String id, Set<String> servablePriorities) {
            this.id = id;
            this.servablePriorities = servablePriorities;
        }

        boolean canServe(String priority) {
            return servablePriorities.isEmpty() || servablePriorities.contains(priority);
        }
    }

    private final Map<String, Set<String>> countersById = new LinkedHashMap<>();
    private final Map<String, TicketSpec> ticketsById = new LinkedHashMap<>();

    public QueueTicketsReport() {
    }

    public QueueTicketsReport addCounter(String counterId, String... servablePriorities) {
        if (isBlank(counterId)) {
            throw new IllegalArgumentException("Counter id must not be blank");
        }
        String[] priorities = servablePriorities == null ? new String[0] : servablePriorities;
        for (String priority : priorities) {
            if (priority == null || !VALID_PRIORITIES.contains(priority)) {
                throw new IllegalArgumentException("Invalid priority: " + priority);
            }
        }
        if (countersById.containsKey(counterId)) {
            throw new IllegalArgumentException("Duplicate counter id: " + counterId);
        }
        Set<String> servable = new LinkedHashSet<>();
        for (String priority : priorities) {
            servable.add(priority);
        }
        countersById.put(counterId, servable);
        return this;
    }

    public QueueTicketsReport addTicket(String ticketId, String priority, int arrivalTick, int durationTicks) {
        if (isBlank(ticketId)) {
            throw new IllegalArgumentException("Ticket id must not be blank");
        }
        if (priority == null || !VALID_PRIORITIES.contains(priority)) {
            throw new IllegalArgumentException("Invalid priority: " + priority);
        }
        if (arrivalTick < 0) {
            throw new IllegalArgumentException("Arrival tick must not be negative: " + arrivalTick);
        }
        if (durationTicks <= 0) {
            throw new IllegalArgumentException("Duration must be positive: " + durationTicks);
        }
        if (ticketsById.containsKey(ticketId)) {
            throw new IllegalArgumentException("Duplicate ticket id: " + ticketId);
        }
        ticketsById.put(ticketId, new TicketSpec(ticketId, priority, arrivalTick, durationTicks));
        return this;
    }

    public String generateReport() {
        if (countersById.isEmpty()) {
            throw new IllegalArgumentException("No counters configured");
        }

        // Simulation copies; the registered configuration is never mutated.
        List<SimCounter> counters = new ArrayList<>();
        for (Map.Entry<String, Set<String>> entry : countersById.entrySet()) {
            counters.add(new SimCounter(entry.getKey(), entry.getValue()));
        }
        counters.sort((a, b) -> a.id.compareTo(b.id));

        List<SimTicket> allTickets = new ArrayList<>();
        for (TicketSpec spec : ticketsById.values()) {
            allTickets.add(new SimTicket(spec));
        }

        List<SimTicket> waiting = new ArrayList<>();
        StringBuilder events = new StringBuilder();
        int maxQueue = 0;
        int tick = 0;

        while (true) {
            // Phase 1: arrivals, in registration order.
            for (SimTicket ticket : allTickets) {
                if (ticket.arrivalTick == tick) {
                    waiting.add(ticket);
                    if (waiting.size() > maxQueue) {
                        maxQueue = waiting.size();
                    }
                    events.append("tick ").append(tick).append(": arrival ")
                            .append(ticket.id).append('(').append(ticket.priority).append(")\n");
                }
            }

            // Phase 2: completions, counters in lexicographic order of id.
            for (SimCounter counter : counters) {
                if (counter.currentTicket != null && counter.busyUntil == tick) {
                    events.append("tick ").append(tick).append(": complete ")
                            .append(counter.currentTicket.id).append(" at ").append(counter.id).append('\n');
                    counter.currentTicket = null;
                }
            }

            // Phase 3: assignment, counters in lexicographic order of id.
            for (SimCounter counter : counters) {
                if (counter.currentTicket != null) {
                    continue;
                }
                SimTicket best = null;
                for (SimTicket candidate : waiting) {
                    if (!counter.canServe(candidate.priority)) {
                        continue;
                    }
                    if (best == null || isBetter(candidate, best)) {
                        best = candidate;
                    }
                }
                if (best != null) {
                    waiting.remove(best);
                    best.startTick = tick;
                    best.counterId = counter.id;
                    counter.currentTicket = best;
                    counter.busyUntil = tick + best.durationTicks;
                    counter.servedCount++;
                    counter.busyTicks += best.durationTicks;
                    events.append("tick ").append(tick).append(": start ")
                            .append(best.id).append(" at ").append(counter.id).append('\n');
                }
            }

            // End-of-tick checks.
            boolean allIdle = true;
            for (SimCounter counter : counters) {
                if (counter.currentTicket != null) {
                    allIdle = false;
                    break;
                }
            }
            boolean futureArrival = false;
            for (SimTicket ticket : allTickets) {
                if (ticket.arrivalTick > tick) {
                    futureArrival = true;
                    break;
                }
            }
            if (allIdle && !futureArrival) {
                if (waiting.isEmpty()) {
                    break;
                }
                List<String> ids = new ArrayList<>();
                for (SimTicket ticket : waiting) {
                    ids.add(ticket.id);
                }
                ids.sort(String::compareTo);
                throw new IllegalStateException("Unservable tickets remain: " + String.join(", ", ids));
            }
            tick++;
        }

        // Build the report.
        StringBuilder report = new StringBuilder();
        report.append("=== Ticket Queue Report ===\n");
        report.append(events);
        report.append("--- Summary ---\n");

        int served = 0;
        for (SimTicket ticket : allTickets) {
            if (ticket.startTick >= 0) {
                served++;
            }
        }
        report.append("served: ").append(served).append('/').append(allTickets.size()).append('\n');
        report.append("max queue: ").append(maxQueue).append('\n');

        List<SimTicket> sortedTickets = new ArrayList<>(allTickets);
        sortedTickets.sort((a, b) -> a.id.compareTo(b.id));
        for (SimTicket ticket : sortedTickets) {
            report.append(ticket.id)
                    .append(": start=").append(ticket.startTick)
                    .append(" end=").append(ticket.startTick + ticket.durationTicks)
                    .append(" counter=").append(ticket.counterId)
                    .append(" wait=").append(ticket.startTick - ticket.arrivalTick)
                    .append('\n');
        }
        for (SimCounter counter : counters) {
            report.append(counter.id)
                    .append(": served=").append(counter.servedCount)
                    .append(" busyTicks=").append(counter.busyTicks)
                    .append('\n');
        }
        report.deleteCharAt(report.length() - 1); // strip trailing newline
        return report.toString();
    }

    private static boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }

    private static boolean isBetter(SimTicket candidate, SimTicket best) {
        int rankDiff = priorityRank(candidate.priority) - priorityRank(best.priority);
        if (rankDiff != 0) {
            return rankDiff < 0;
        }
        if (candidate.arrivalTick != best.arrivalTick) {
            return candidate.arrivalTick < best.arrivalTick;
        }
        return candidate.id.compareTo(best.id) < 0;
    }

    private static int priorityRank(String priority) {
        switch (priority) {
            case "HIGH":
                return 0;
            case "NORMAL":
                return 1;
            default:
                return 2;
        }
    }
}
