import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;

public final class FlightItinerariesCalculator {

    private FlightItinerariesCalculator() {
    }

    public static List<Itinerary> findItineraries(List<Flight> flights,
                                                  Map<String, AirportRules> airports,
                                                  ItineraryQuery query) {
        validate(flights, airports, query);

        List<Itinerary> results = new ArrayList<>();
        if (query.origin().equals(query.destination())) {
            return results;
        }

        Map<String, List<Flight>> byFrom = new HashMap<>();
        for (Flight f : flights) {
            byFrom.computeIfAbsent(f.from(), k -> new ArrayList<>()).add(f);
        }

        List<Flight> path = new ArrayList<>();
        Set<String> visited = new HashSet<>();
        visited.add(query.origin());

        search(query.origin(), null, path, visited, query, airports, byFrom, results);

        results.sort(Comparator
                .comparingInt(Itinerary::totalDuration)
                .thenComparingInt(i -> i.legs().size())
                .thenComparing(FlightItinerariesCalculator::codePath));
        return results;
    }

    private static void search(String airport,
                               Flight lastFlight,
                               List<Flight> path,
                               Set<String> visited,
                               ItineraryQuery query,
                               Map<String, AirportRules> airports,
                               Map<String, List<Flight>> byFrom,
                               List<Itinerary> results) {
        if (path.size() >= query.maxLegs()) {
            return;
        }
        for (Flight f : byFrom.getOrDefault(airport, List.of())) {
            if (lastFlight == null) {
                if (f.departure() < query.earliestDeparture()) {
                    continue;
                }
            } else if (!connectionValid(lastFlight, f, airports.get(airport))) {
                continue;
            }
            if (f.to().equals(query.destination())) {
                if (f.arrival() <= query.latestArrival()) {
                    path.add(f);
                    results.add(buildItinerary(path));
                    path.remove(path.size() - 1);
                }
                // Nothing continues past the destination.
                continue;
            }
            if (visited.contains(f.to())) {
                continue;
            }
            path.add(f);
            visited.add(f.to());
