```javascript
// ---------- Shared helpers ----------

function normalizeText(text) {
  return text.trim().replace(/\s+/g, ' ');
}

function findWords(norm) {
  const words = [];
  const re = /[A-Za-z0-9]+/g;
  let m;
  while ((m = re.exec(norm)) !== null) {
    words.push({ start: m.index, end: m.index + m[0].length, word: m[0] });
  }
  return words;
}

function normalizeTerms(terms) {
  const out = [];
  const seen = new Set();
  for (const t of terms) {
    const n = t.trim().toLowerCase();
    if (n === '') continue;
    if (seen.has(n)) continue;
    seen.add(n);
    out.push(n);
  }
  return out;
}

function isAlnumChar(c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9');
}

function noMatchSnippet(norm, maxWidth) {
  if (norm.length <= maxWidth) return norm;
  let cut = -1;
  for (let i = Math.min(maxWidth, norm.length - 1); i >= 0; i--) {
    if (norm[i] === ' ') {
      cut = i;
      break;
    }
  }
  const base = cut === -1 ? norm.slice(0, maxWidth) : norm.slice(0, cut);
  return base + ' ...';
}

// ---------- Public API ----------

export function extractSnippet(text, terms, maxWidth) {
  if (typeof text !== 'string') {
    throw new Error('text must be a string');
  }
  if (!Array.isArray(terms) || terms.some((t) => typeof t !== 'string')) {
    throw new Error('terms must be an array of strings');
  }
  if (!Number.isInteger(maxWidth) || maxWidth < 10) {
    throw new Error('maxWidth must be an integer of at least 10');
  }

  const norm = normalizeText(text);
  const usableTerms = normalizeTerms(terms);
  const termSet = new Set(usableTerms);
  const words = findWords(norm);

  // Window selection
  let best = null; // { i, j, distinct, matches }
  if (usableTerms.length > 0 && words.length > 0) {
    for (let i = 0; i < words.length; i++) {
      if (words[i].end - words[i].start > maxWidth) continue; // single word too long
      let j = i;
      while (
        j + 1 < words.length &&
        words[j + 1].end - words[i].start <= maxWidth
      ) {
        j++;
      }
      const distinct = new Set();
      let matches = 0;
      for (let k = i; k <= j; k++) {
        const lw = words[k].word.toLowerCase();
        if (termSet.has(lw)) {
          distinct.add(lw);
          matches++;
        }
      }
      if (
        best === null ||
        distinct.size > best.distinct ||
        (distinct.size === best.distinct && matches > best.matches)
      ) {
        best = { i, j, distinct: distinct.size, matches };
      }
    }
  }

  if (best === null || best.matches === 0) {
    return noMatchSnippet(norm, maxWidth);
  }

  // Render the chosen window
  const winStart = words[best.i].start;
  const winEnd = words[best.j].end;

  let extStart = winStart;
  let extEnd = winEnd;
  while (
    extStart > 0 &&
    !isAlnumChar(norm[extStart - 1]) &&
    norm[extStart - 1] !== ' '
  ) {
    extStart--;
  }
  while (
    extEnd < norm.length &&
    !isAlnumChar(norm[extEnd]) &&
    norm[extEnd] !== ' '
  ) {
    extEnd++;
  }

  // Extension only ever covers punctuation, so every word inside
  // [extStart, extEnd) lies fully within the window.
  const inner = norm
    .slice(extStart, extEnd)
    .replace(
      /[A-Za-z0-9]+/g,
      (w) => (termSet.has(w.toLowerCase()) ? `[[${w}]]` : w)
    );

  let result = inner;
  if (extStart > 0) result = '... ' + result;
  if (extEnd < norm.length) result = result + ' ...';
  return result;
}

export function scoreDocument(text, terms) {
  if (typeof text !== 'string') {
    throw new Error('text must be a string');
  }
  if (!Array.isArray(terms) || terms.some((t) => typeof t !== 'string')) {
    throw new Error('terms must be an array of strings');
  }

  const norm = normalizeText(text);
  const usable = normalizeTerms(terms);
  if (usable.length === 0) return 0;

  const termSet = new Set(usable);
  const words = findWords(norm).map((w) => w.word.toLowerCase());

  let matchedWords = 0;
  const matchedTerms = new Set();
  for (const w of words) {
    if (termSet.has(w)) {
      matchedWords++;
      matchedTerms.add(w);
    }
  }

  let score = matchedTerms.size * 5 + matchedWords;

  if (matchedTerms.size >= 2) {
    outer: for (let s = 0; s + usable.length <= words.length; s++) {
      for (let k = 0; k < usable.length; k++) {
        if (words[s + k] !== usable[k]) continue outer;
      }
      score += 10;
      break;
    }
  }

  return score;
}

export function generateReport(query, documents, options) {
  if (typeof query !== 'string') {
    throw new Error('Query must be a string');
  }
  if (query.trim() === '') {
    throw new Error('Empty query');
  }

  let maxWidth = 60;
  let topN = 10;
  if (options !== undefined) {
    if (
      typeof options !== 'object' ||
      options === null ||
      Array.isArray(options)
    ) {
      throw new Error('options must be an object');
    }
    if (options.maxWidth !== undefined) maxWidth = options.maxWidth;
    if (options.topN !== undefined) topN = options.topN;
  }
  if (!Number.isInteger(maxWidth) || maxWidth < 10) {
    throw new Error('maxWidth must be an integer of at least 10');
  }
  if (!Number.isInteger(topN) || topN < 1) {
    throw new Error('topN must be a positive integer');
  }

  if (!Array.isArray(documents)) {
    throw new Error('documents must be an array');
  }
  const seenIds = new Set();
  for (const doc of documents) {
    if (typeof doc !== 'object' || doc === null || Array.isArray(doc)) {
      throw new Error('Invalid document');
    }
    if (
      typeof doc.id !== 'string' ||
      doc.id === '' ||
      typeof doc.text !== 'string'
    ) {
      throw new Error('Invalid document');
    }
    if (seenIds.has(doc.id)) {
      throw new Error(`Duplicate document id: ${doc.id}`);
    }
    seenIds.add(doc.id);
  }

  const terms = normalizeTerms(query.trim().split(/\s+/));

  const results = [];
  for (const doc of documents) {
    const score = scoreDocument(doc.text, terms);
    if (score === 0) continue;
    const snippet = extractSnippet(doc.text, terms, maxWidth);
    results.push({ id: doc.id, score, snippet });
  }

  results.sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    if (a.id < b.id) return -1;
    if (a.id > b.id) return 1;
    return 0;
  });

  const lines = [`Query: ${query}`, `Results: ${results.length}`];
  if (results.length === 0) {
    lines.push('No results.');
  } else {
    const shown = results.slice(0, topN);
    for (let i = 0; i < shown.length; i++) {
      lines.push(`${i + 1}. ${shown[i].id} (score: ${shown[i].score})`);
      lines.push(`  ${shown[i].snippet}`);
    }
  }

  return lines.join('\n');
}
```

A few notes on the implementation:

- **Window selection** iterates each starting word `i`, greedily extends to the furthest word `j` with `endOf(j) − startOf(i) ≤ maxWidth`, and scores the pair `(distinct terms, matched words)`. Since starts are scanned left to right and replacement only happens on a strictly better pair, ties automatically resolve to the earliest starting word.
- **Punctuation extension** runs on the normalized text after wrapping; because the extension only ever crosses non-alphanumeric, non-space characters, every word in the extended slice lies fully inside the window, so a single regex replace can wrap the matched words.
- **Phrase bonus** scans the lowercased word sequence for the full normalized term list appearing consecutively; it's only attempted when at least two distinct terms matched (which, given deduplication, is equivalent to the term list having length ≥ 2 and being found).
- **Validation order** in `generateReport` matches the spec: query → options/maxWidth/topN → documents (shape, then duplicates), with all documents validated before any scoring or snippet generation.
- The examples from the spec produce exactly the shown outputs, e.g. `scoreDocument('A quick fox runs', ['quick', 'fox'])` → `22` and the report renders with the trailing `.` attached to `[[fox]]`.

