```javascript
const VALID_TYPES = new Set(['int', 'dec', 'str', 'bool', 'enum']);
const FORBIDDEN_CHARS = /[;=\n\r]/;

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function hasOwn(obj, key) {
  return Object.prototype.hasOwnProperty.call(obj, key);
}

function isPresent(record, name) {
  return hasOwn(record, name) && record[name] !== undefined;
}

function outOfRange(field, value) {
  if (field.min !== undefined && value < field.min) return true;
  if (field.max !== undefined && value > field.max) return true;
  return false;
}

export function validateSchema(schema) {
  if (!Array.isArray(schema) || schema.length === 0) {
    throw new Error('Invalid schema: expected a non-empty array of field definitions');
  }
  const seenCodes = new Set();
  const seenNames = new Set();
  for (let i = 0; i < schema.length; i++) {
    const def = schema[i];
    const badDefinition =
      !isPlainObject(def) ||
      typeof def.code !== 'string' || !/^[A-Z]$/.test(def.code) ||
      typeof def.name !== 'string' || def.name === '' ||
      (def.min !== undefined && !Number.isFinite(def.min)) ||
      (def.max !== undefined && !Number.isFinite(def.max)) ||
      (def.maxLength !== undefined &&
        (!Number.isInteger(def.maxLength) || def.maxLength < 1));
    if (badDefinition) {
      throw new Error(`Invalid schema: bad field definition at position ${i}`);
    }
    if (!VALID_TYPES.has(def.type)) {
      throw new Error(`Invalid schema: unknown type "${String(def.type)}" at position ${i}`);
    }
    if (def.type === 'enum' && (!Array.isArray(def.values) || def.values.length === 0)) {
      throw new Error(`Invalid schema: enum field "${def.name}" must define a non-empty values array`);
    }
    if (seenCodes.has(def.code)) {
      throw new Error(`Invalid schema: duplicate field code "${def.code}"`);
    }
    if (seenNames.has(def.name)) {
      throw new Error(`Invalid schema: duplicate field name "${def.name}"`);
    }
    seenCodes.add(def.code);
    seenNames.add(def.name);
  }
  return undefined;
}

export function validateRecord(schema, record) {
  validateSchema(schema);
  if (!isPlainObject(record)) {
    throw new Error('Invalid record: expected an object');
  }
  const errors = [];
  const knownNames = new Set(schema.map((f) => f.name));
  let anyPresent = false;
  for (const field of schema) {
    if (!isPresent(record, field.name)) {
      if (field.required) {
        errors.push(`Missing required field "${field.name}"`);
      }
      continue;
    }
    anyPresent = true;
    const value = record[field.name];
    const quoted = `"${String(value)}"`;
    switch (field.type) {
      case 'int':
        if (!Number.isInteger(value)) {
          errors.push(`Invalid int for field "${field.name}": ${quoted}`);
        } else if (outOfRange(field, value)) {
          errors.push(`Value out of range for field "${field.name}": ${quoted}`);
        }
        break;
      case 'dec':
        if (typeof value !== 'number' || !Number.isFinite(value)) {
          errors.push(`Invalid dec for field "${field.name}": ${quoted}`);
        } else if (outOfRange(field, value)) {
          errors.push(`Value out of range for field "${field.name}": ${quoted}`);
        }
        break;
      case 'bool':
        if (value !== true && value !== false) {
          errors.push(`Invalid bool for field "${field.name}": ${quoted}`);
        }
        break;
      case 'str':
        if (typeof value !== 'string') {
          errors.push(`Invalid str for field "${field.name}": ${quoted}`);
        } else if (FORBIDDEN_CHARS.test(value)) {
          errors.push(`Invalid str for field "${field.name}": ${quoted} contains a forbidden character`);
        } else if (field.maxLength !== undefined && value.length > field.maxLength) {
          errors.push(`String too long for field "${field.name}": max ${field.maxLength}, got ${value.length}`);
        }
        break;
      case 'enum':
        if (!field.values.includes(value)) {
          errors.push(`Invalid enum for field "${field.name}": ${quoted}`);
        }
        break;
    }
  }
  if (!anyPresent) {
    errors.push('Invalid record: no fields present');
  }
  for (const key of Object.keys(record)) {
    if (!knownNames.has(key)) {
      errors.push(`Unknown field "${key}"`);
    }
  }
  return errors;
}

function toWire(field, value) {
  switch (field.type) {
    case 'int':
      return String(value);
    case 'dec':
      return value.toFixed(2);
    case 'str':
      return value;
    case 'bool':
      return value ? 'Y' : 'N';
    case 'enum':
      return value;
  }
}

export function encodeRecords(schema, records) {
  validateSchema(schema);
  if (!Array.isArray(records)) {
    throw new Error('Invalid records: expected an array');
  }
  const lines = [];
  for (const record of records) {
    const errors = validateRecord(schema, record);
    if (errors.length > 0) {
      throw new Error(errors[0]);
    }
    const tokens = [];
    for (const field of schema) {
      if (isPresent(record, field.name)) {
        tokens.push(`${field.code}=${toWire(field, record[field.name])}`);
      }
    }
    lines.push(tokens.join(';'));
  }
  return lines.join('\n');
}

function convertFromWire(field, text, token) {
  switch (field.type) {
    case 'int': {
      if (!/^-?\d+$/.test(text)) {
        throw new Error(`Invalid int for field "${field.name}": "${token}"`);
      }
      const value = Number(text);
      if (outOfRange(field, value)) {
        throw new Error(`Value out of range for field "${field.name}": "${token}"`);
      }
      return value;
    }
    case 'dec': {
      if (!/^-?\d+\.\d{2}$/.test(text)) {
        throw new Error(`Invalid dec for field "${field.name}": "${token}"`);
      }
      const value = Number(text);
      if (outOfRange(field, value)) {
        throw new Error(`Value out of range for field "${field.name}": "${token}"`);
      }
      return value;
    }
    case 'bool': {
      if (text === 'Y') return true;
      if (text === 'N') return false;
      throw new Error(`Invalid bool for field "${field.name}": "${token}"`);
    }
    case 'str': {
      if (FORBIDDEN_CHARS.test(text)) {
        throw new Error(`Invalid str for field "${field.name}": "${token}" contains a forbidden character`);
      }
      if (field.maxLength !== undefined && text.length > field.maxLength) {
        throw new Error(`String too long for field "${field.name}": max ${field.maxLength}, got ${text.length}`);
      }
      return text;
    }
    case 'enum': {
      if (!field.values.includes(text)) {
        throw new Error(`Invalid enum for field "${field.name}": "${token}"`);
      }
      return text;
    }
  }
}

export function decodeRecords(schema, text) {
  validateSchema(schema);
  if (typeof text !== 'string') {
    throw new Error('Invalid input: expected a string');
  }
  if (text === '') {
    return [];
  }
  const fieldByCode = new Map(schema.map((f) => [f.code, f]));
  const lines = text.split('\n');
  const records = [];
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1;
    const line = lines[i];
    if (line === '') {
      throw new Error(`Empty record at line ${lineNo}`);
    }
    const tokens = line.split(';');
    const valuesByCode = new Map();
    for (const token of tokens) {
      if (token === '' || !token.includes('=')) {
        throw new Error(`Malformed token at line ${lineNo}: "${token}"`);
      }
      const eq = token.indexOf('=');
      const code = token.slice(0, eq);
      const valueText = token.slice(eq + 1);
      const field = fieldByCode.get(code);
      if (field === undefined) {
        throw new Error(`Unknown field code at line ${lineNo}: "${code}"`);
      }
      if (valuesByCode.has(code)) {
        throw new Error(`Duplicate field code at line ${lineNo}: "${code}"`);
      }
      valuesByCode.set(code, convertFromWire(field, valueText, token));
    }
    const record = {};
    for (const field of schema) {
      if (valuesByCode.has(field.code)) {
        record[field.name] = valuesByCode.get(field.code);
      } else if (field.required) {
        throw new Error(`Missing required field "${field.name}"`);
      }
    }
    records.push(record);
  }
  return records;
}
