          `Line ${lineNo}: invalid service duration "${serviceToken}" for stop ${index}: expected a non-negative integer`
        );
      }

      seenIndices.add(index);
      stops.push({
        index,
        name: tokens[2],
        x: Number(tokens[3]),
        y: Number(tokens[4]),
        open,
        close,
        service: Number(serviceToken)
      });
    }
  }

  if (header === null) {
    throw new Error('Route plan is empty');
  }
  return header;
}

export function orderStops(plan) {
  const remaining = plan.stops.map((s) => ({ ...s }));
  let curX = plan.depot.x;
  let curY = plan.depot.y;
  let curTime = plan.startTime;
  const schedule = [];

  while (remaining.length > 0) {
    let best = -1;
    for (let i = 0; i < remaining.length; i++) {
      const s = remaining[i];
      const travel = Math.abs(curX - s.x) + Math.abs(curY - s.y);
      const serviceStart = Math.max(curTime + travel, s.open);
      if (serviceStart > s.close) continue; // not feasible
      if (best === -1) {
        best = i;
        continue;
      }
      const b = remaining[best];
      if (
        s.close < b.close ||
        (s.close === b.close && s.open < b.open) ||
        (s.close === b.close && s.open === b.open && s.index < b.index)
      ) {
        best = i;
      }
    }

    if (best === -1) {
      throw new Error(`No feasible stop remaining for route ${plan.routeId}`);
    }

    const s = remaining.splice(best, 1)[0];
    const travel = Math.abs(curX - s.x) + Math.abs(curY - s.y);
    const arrival = Math.max(curTime + travel, s.open);
    const departure = arrival + s.service;
    schedule.push({ index: s.index, name: s.name, arrival, departure });
    curX = s.x;
    curY = s.y;
    curTime = departure;
  }

  return schedule;
}
```

