const DAYS = ['MON', 'TUE', 'WED', 'THU', 'FRI'];
const DAY_INDEX = { MON: 0, TUE: 1, WED: 2, THU: 3, FRI: 4 };

const TIME_RE = /^([01]\d|2[0-3]):([0-5]\d)$/;
const CODE_RE = /^[A-Z]{2,4}\d{3}$/;
const ROOM_RE = /^[A-Z0-9-]{1,10}$/;

function toMinutes(hh, mm) {
  return hh * 60 + mm;
}

export function parseTimetable(text) {
  const entries = [];
  const lines = String(text).split('\n');

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1;
    const trimmed = lines[i].trim();

    if (trimmed === '') continue;
    if (trimmed.startsWith('#')) continue;

    const fields = trimmed.split(/[ \t]+/);

    if (fields.length !== 5) {
      throw new Error(`Line ${lineNo}: expected 5 fields, got ${fields.length}`);
    }

    const [day, startStr, endStr, code, room] = fields;

    if (!DAYS.includes(day)) {
      throw new Error(`Line ${lineNo}: unknown day "${day}"`);
    }

    const startMatch = TIME_RE.exec(startStr);
    if (!startMatch) {
      throw new Error(`Line ${lineNo}: invalid time "${startStr}"`);
    }

    const endMatch = TIME_RE.exec(endStr);
    if (!endMatch) {
      throw new Error(`Line ${lineNo}: invalid time "${endStr}"`);
    }

    const start = toMinutes(Number(startMatch[1]), Number(startMatch[2]));
    const end = toMinutes(Number(endMatch[1]), Number(endMatch[2]));

    if (!(start < end)) {
      throw new Error(`Line ${lineNo}: start must be before end`);
    }

    if (!CODE_RE.test(code)) {
      throw new Error(`Line ${lineNo}: invalid course code "${code}"`);
    }

    if (!ROOM_RE.test(room)) {
      throw new Error(`Line ${lineNo}: invalid room "${room}"`);
    }

    entries.push({ day, start, end, code, room });
  }

  return entries;
}

export function findConflicts(entries) {
  const conflicts = [];

  for (let i = 0; i < entries.length; i++) {
    for (let j = i + 1; j < entries.length; j++) {
      const a = entries[i];
      const b = entries[j];

      if (a.day !== b.day || a.room !== b.room) continue;
      if (!(a.start <= b.end && b.start <= a.end)) continue;

      const codes = [a.code, b.code].sort();
      conflicts.push({
        day: a.day,
        room: a.room,
        start: Math.max(a.start, b.start),
        end: Math.min(a.end, b.end),
        codes,
      });
    }
  }

  conflicts.sort((x, y) => {
    const dayDiff = DAY_INDEX[x.day] - DAY_INDEX[y.day];
    if (dayDiff !== 0) return dayDiff;
    if (x.start !== y.start) return x.start - y.start;
    if (x.end !== y.end) return x.end - y.end;
    if (x.room !== y.room) return x.room < y.room ? -1 : 1;
    if (x.codes[0] !== y.codes[0]) return x.codes[0] < y.codes[0] ? -1 : 1;
    if (x.codes[1] !== y.codes[1]) return x.codes[1] < y.codes[1] ? -1 : 1;
    return 0;
  });

  return conflicts;
}
