export function simulateBerths(berths, ships) {
  // ---- Validation: berths ----
  if (!Array.isArray(berths) || berths.length === 0) {
    throw new Error('berths must be a non-empty array');
  }
  const seenBerthIds = new Set();
  for (const berth of berths) {
    if (typeof berth !== 'object' || berth === null || Array.isArray(berth)) {
      throw new Error('each berth must be an object');
    }
    if (typeof berth.id !== 'string' || berth.id.length === 0) {
      throw new Error('berth id must be a non-empty string');
    }
    if (
      typeof berth.length !== 'number' ||
      !Number.isFinite(berth.length) ||
      berth.length <= 0
    ) {
      throw new Error('berth length must be a positive number');
    }
    if (seenBerthIds.has(berth.id)) {
      throw new Error(`duplicate berth id: ${berth.id}`);
    }
    seenBerthIds.add(berth.id);
  }

  // ---- Validation: ships ----
  if (!Array.isArray(ships) || ships.length === 0) {
    throw new Error('ships must be a non-empty array');
  }
  const seenShipNames = new Set();
  let maxBerthLength = -Infinity;
  for (const berth of berths) {
    if (berth.length > maxBerthLength) maxBerthLength = berth.length;
  }
  for (const ship of ships) {
    if (typeof ship !== 'object' || ship === null || Array.isArray(ship)) {
      throw new Error('each ship must be an object');
    }
    if (typeof ship.name !== 'string' || ship.name.length === 0) {
      throw new Error('ship name must be a non-empty string');
    }
    if (
      typeof ship.arrivalTime !== 'number' ||
      !Number.isFinite(ship.arrivalTime) ||
      ship.arrivalTime < 0
    ) {
      throw new Error('ship arrival time must be a non-negative number');
    }
    if (
      typeof ship.length !== 'number' ||
      !Number.isFinite(ship.length) ||
      ship.length <= 0
    ) {
      throw new Error('ship length must be a positive number');
    }
    if (
      typeof ship.serviceTime !== 'number' ||
      !Number.isFinite(ship.serviceTime) ||
      ship.serviceTime <= 0
    ) {
      throw new Error('ship service time must be a positive number');
    }
    if (seenShipNames.has(ship.name)) {
      throw new Error(`duplicate ship name: ${ship.name}`);
    }
    seenShipNames.add(ship.name);
    if (ship.length > maxBerthLength) {
      throw new Error(`Ship ${ship.name} cannot fit any berth`);
    }
  }

  // ---- Simulation setup (no input mutation) ----
  const berthCount = berths.length;
  const freeFrom = new Array(berthCount).fill(0);
  const berthBusy = new Array(berthCount).fill(0);
  let lastStart = 0;

  // Ships in processing order: by arrivalTime, ties keep input order.
  const order = ships.map((ship, index) => ({ ship, index }));
  order.sort((a, b) => {
    if (a.ship.arrivalTime !== b.ship.arrivalTime) {
      return a.ship.arrivalTime - b.ship.arrivalTime;
    }
    return a.index - b.index;
  });

  const results = new Array(ships.length);
  const queue = [];

  function assignmentPass(limit) {
    while (queue.length > 0) {
      const front = queue[0];
      const S = front.ship;

      let bestIndex = -1;
      let bestStart = Infinity;
      for (let i = 0; i < berthCount; i++) {
        if (berths[i].length < S.length) continue;
        const start = Math.max(freeFrom[i], lastStart, S.arrivalTime);
        if (
          bestIndex === -1 ||
          start < bestStart ||
          (start === bestStart && berths[i].length < berths[bestIndex].length)
        ) {
          bestIndex = i;
          bestStart = start;
        }
      }

      // If the best possible start exceeds the limit, everyone keeps waiting.
      if (bestStart > limit) return;

      // Assign the ship.
      queue.shift();
      const end = bestStart + S.serviceTime;
      freeFrom[bestIndex] = end;
      lastStart = bestStart;
      berthBusy[bestIndex] += S.serviceTime;
      results[front.index] = {
        ship: S.name,
        berth: berths[bestIndex].id,
        start: bestStart,
        end,
        wait: bestStart - S.arrivalTime,
      };
    }
  }

  // Process ships in arrival order: enqueue, then run a pass limited to that
  // ship's arrival time.
  for (const entry of order) {
    queue.push(entry);
    assignmentPass(entry.ship.arrivalTime);
  }

  // Final pass with no time limit.
  assignmentPass(Infinity);

  // ---- Build result ----
  let totalWait = 0;
  let maxWait = 0;
  for (const r of results) {
    totalWait += r.wait;
    if (r.wait > maxWait) maxWait = r.wait;
  }

  return {
    schedule: results,
    berthStats: berths.map((berth, i) => ({
      berth: berth.id,
      busyTime: berthBusy[i],
    })),
    totalWait,
    maxWait,
  };
}
