/**
 * Build the planned consumption manifest for the given recipe book and orders.
 *
 * @param {Array} recipes the recipe book.
 * @param {Array} orders the crafting orders.
 * @returns {{consumption: Object, production: Object, waste: Object, craftCount: Object}} manifest
 */
export function planConsumption(recipes, orders) {
  const { byId, producerOf } = validateRecipes(recipes);
  const normalizedOrders = validateOrders(orders, byId);

  const consumption = {};
  const production = {};
  const waste = {};
  const craftCount = {};

  for (const order of normalizedOrders) {
    const recipe = order.recipe;

    // 1. The order's own crafts.
    craftCount[recipe.id] = (craftCount[recipe.id] || 0) + order.batches;
    production[recipe.output.item] =
      (production[recipe.output.item] || 0) + recipe.output.qty * order.batches;

    const fromStockSet = new Set(order.fromStock);
    const subByFor = new Map();
    for (const sub of order.substitutions) {
      subByFor.set(sub.for, sub);
    }

    // Recursive expansion of a single line item.
    const expand = (item, qty, pathSet) => {
      if (fromStockSet.has(item) || !producerOf.has(item)) {
        // fromStock check comes first; otherwise consumed from inventory
        // because nothing in the book produces it.
        consumption[item] = (consumption[item] || 0) + qty;
        return;
      }
      const S = producerOf.get(item);
      if (pathSet.has(S.id)) {
        throw new Error(`Crafting cycle detected involving recipe ${S.id}`);
      }
      const crafts = Math.ceil(qty / S.output.qty);
      craftCount[S.id] = (craftCount[S.id] || 0) + crafts;
      production[item] = (production[item] || 0) + crafts * S.output.qty;
      const surplus = crafts * S.output.qty - qty;
      if (surplus > 0) {
        waste[item] = (waste[item] || 0) + surplus;
      }
      const nextPath = new Set(pathSet);
      nextPath.add(S.id);
      for (const input of S.inputs) {
        // Each line item is expanded independently; quantities never pooled.
        expand(input.item, input.qty * crafts, nextPath);
      }
    };

    // 2. Top-level line items, with substitutions applied.
    const initialPath = new Set([recipe.id]);
    for (const input of recipe.inputs) {
      const sub = subByFor.get(input.item);
      if (sub) {
        expand(sub.use, sub.ratio * input.qty * order.batches, initialPath);
      } else {
        expand(input.item, input.qty * order.batches, initialPath);
      }
    }
  }

  return {
    consumption: filterPositive(consumption),
    production: filterPositive(production),
    waste: filterPositive(waste),
    craftCount: filterPositive(craftCount),
  };
}

/**
 * Compare a manifest produced by planConsumption against the actual
 * inventory withdrawal ledger and report every difference.
 *
 * @param {{consumption: Object}} manifest the planned manifest.
 * @param {Array} ledger the actual withdrawals.
 * @returns {{balanced: boolean, checkedItems: number, matchedItems: number, differences: Array}} report
 */
export function reconcile(manifest, ledger) {
  if (!Array.isArray(ledger)) {
    throw new Error('Ledger must be an array');
  }
  const actual = {};
  for (const entry of ledger) {
    if (entry === null || typeof entry !== 'object') {
      throw new Error('Ledger entry must be an object');
    }
    const item = entry.item;
    if (!isNonEmptyString(item)) {
      throw new Error('Ledger entry item must be a non-empty string');
    }
    const qty = entry.qty;
    if (!isPositiveInteger(qty)) {
      throw new Error(`Ledger entry for item ${item}: quantity must be a positive integer`);
    }
    actual[item] = (actual[item] || 0) + qty;
  }

  const planned =
    manifest && typeof manifest === 'object' && manifest.consumption
      ? manifest.consumption
      : {};

  const items = new Set([...Object.keys(planned), ...Object.keys(actual)]);
  const differences = [];
  let matchedItems = 0;
  for (const item of items) {
    const p = planned[item] || 0;
    const a = actual[item] || 0;
    if (p === a) {
      matchedItems += 1;
    } else {
      differences.push({
        item,
        planned: p,
        actual: a,
        status: a < p ? 'shortfall' : 'overage',
        delta: a - p,
      });
    }
  }
  differences.sort((x, y) => (x.item < y.item ? -1 : x.item > y.item ? 1 : 0));

  return {
    balanced: differences.length === 0,
    checkedItems: items.size,
    matchedItems,
    differences,
  };
}

/**
 * Plan the orders and reconcile the plan against the ledger in one step.
 *
 * @param {Array} recipes the recipe book.
 * @param {Array} orders the crafting orders.
 * @param {Array} ledger the actual withdrawals.
 * @returns {{balanced: boolean, checkedItems: number, matchedItems: number, differences: Array}} report
 */
export function reconcileCrafting(recipes, orders, ledger) {
  return reconcile(planConsumption(recipes, orders), ledger);
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function isNonEmptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

function isPositiveInteger(value) {
  return Number.isInteger(value) && value > 0;
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object';
}

function filterPositive(map) {
  const out = {};
  for (const key of Object.keys(map)) {
    if (map[key] > 0) {
      out[key] = map[key];
    }
  }
  return out;
}

function validateRecipes(recipes) {
  if (!Array.isArray(recipes)) {
    throw new Error('Recipes must be an array');
  }
  const byId = new Map();
  const producerOf = new Map(); // output item -> recipe
  for (const recipe of recipes) {
    if (!isPlainObject(recipe)) {
      throw new Error('Recipe must be an object');
    }
    const id = recipe.id;
    if (!isNonEmptyString(id)) {
      throw new Error('Recipe id must be a non-empty string');
    }
    if (byId.has(id)) {
      throw new Error(`Duplicate recipe id: ${id}`);
    }
    const output = recipe.output;
    const outItem = isPlainObject(output) ? output.item : undefined;
    if (!isNonEmptyString(outItem)) {
      throw new Error(`Recipe ${id}: output item must be a non-empty string`);
    }
    if (!isPositiveInteger(output.qty)) {
      throw new Error(`Recipe ${id}: output quantity must be a positive integer`);
    }
    if (producerOf.has(outItem)) {
      throw new Error(`Multiple recipes produce item: ${outItem}`);
    }
    const inputs = recipe.inputs;
    if (!Array.isArray(inputs) || inputs.length === 0) {
      throw new Error(`Recipe ${id}: inputs must be a non-empty array`);
    }
    const seenInputs = new Set();
    for (const input of inputs) {
      const item = isPlainObject(input) ? input.item : undefined;
      if (!isNonEmptyString(item)) {
        throw new Error(`Recipe ${id}: input item must be a non-empty string`);
      }
      if (!isPositiveInteger(input.qty)) {
        throw new Error(`Recipe ${id}: invalid quantity ${input.qty} for item ${item}`);
      }
      if (seenInputs.has(item)) {
        throw new Error(`Recipe ${id}: lists item ${item} more than once`);
      }
      seenInputs.add(item);
    }
    byId.set(id, recipe);
    producerOf.set(outItem, recipe);
  }
  return { byId, producerOf };
}

function validateOrders(orders, byId) {
  if (!Array.isArray(orders)) {
    throw new Error('Orders must be an array');
  }
  const orderIds = new Set();
  const normalized = [];
  for (const order of orders) {
    if (!isPlainObject(order)) {
      throw new Error('Order must be an object');
    }
    const id = order.id;
    if (!isNonEmptyString(id)) {
      throw new Error('Order id must be a non-empty string');
    }
    if (orderIds.has(id)) {
      throw new Error(`Duplicate order id: ${id}`);
    }
    const recipeId = order.recipe;
    if (!byId.has(recipeId)) {
      throw new Error(`Order ${id}: unknown recipe ${recipeId}`);
    }
    if (!isPositiveInteger(order.batches)) {
      throw new Error(`Order ${id}: batches must be a positive integer`);
    }
    const recipe = byId.get(recipeId);
    const inputItems = new Set(recipe.inputs.map((i) => i.item));

    let substitutions = [];
    if (order.substitutions !== undefined) {
      if (!Array.isArray(order.substitutions)) {
        throw new Error(`Order ${id}: substitutions must be an array`);
      }
      const seenFor = new Set();
      for (const sub of order.substitutions) {
        const forItem = isPlainObject(sub) ? sub.for : undefined;
        if (!isNonEmptyString(forItem)) {
          throw new Error(`Order ${id}: substitution target must be a non-empty string`);
        }
        if (!isNonEmptyString(sub.use)) {
          throw new Error(`Order ${id}: substitution replacement must be a non-empty string`);
        }
        if (!isPositiveInteger(sub.ratio)) {
          throw new Error(`Order ${id}: substitution ratio must be a positive integer`);
        }
        if (seenFor.has(forItem)) {
          throw new Error(`Order ${id}: duplicate substitution for ${forItem}`);
        }
        if (!inputItems.has(forItem)) {
          throw new Error(
            `Order ${id}: cannot substitute for ${forItem}: not an input of recipe ${recipeId}`
          );
        }
        seenFor.add(forItem);
        substitutions.push({ for: forItem, use: sub.use, ratio: sub.ratio });
      }
    }

    let fromStock = [];
    if (order.fromStock !== undefined) {
      if (!Array.isArray(order.fromStock) || !order.fromStock.every(isNonEmptyString)) {
        throw new Error(`Order ${id}: fromStock must be an array of item names`);
      }
      fromStock = order.fromStock.slice();
    }

    orderIds.add(id);
    normalized.push({ id, recipe, batches: order.batches, substitutions, fromStock });
  }
  return normalized;
}
