  }

  if (typeof bill.meterId !== 'string' || !METER_ID_RE.test(bill.meterId)) fail('invalid meter id');
  if (typeof bill.tariffName !== 'string' || !TARIFF_NAME_RE.test(bill.tariffName)) fail('invalid tariff name');

  if (bill.windows.length > 6) fail('too many windows');

  const codes = new Set();
  for (const w of bill.windows) {
    if (typeof w.code !== 'string' || !WINDOW_CODE_RE.test(w.code)) fail('invalid window code');
    if (codes.has(w.code)) fail('duplicate window code');
    codes.add(w.code);
    if (typeof w.from !== 'string' || !CLOCK_RE.test(w.from) ||
        typeof w.to !== 'string' || !CLOCK_RE.test(w.to) || w.from === w.to) {
      fail('invalid window time');
    }
    if (!Number.isInteger(w.centsPerKWh) || w.centsPerKWh < 1 || w.centsPerKWh > 999) fail('invalid rate');
  }

  const lines = [
    'MTR ' + bill.meterId,
    'TAR ' + bill.tariffName + ' ' +
      bill.windows.map((w) => w.code + '/' + w.from + '-' + w.to + '/' + w.centsPerKWh).join(','),
  ];

  let prevTime = null;
  for (const e of bill.entries) {
    const m = typeof e.time === 'string' ? BILL_TIME_RE.exec(e.time) : null;
    if (!m || !validDateTime(+m[1], +m[2], +m[3], +m[4], +m[5])) fail('invalid entry time');
    if (!codes.has(e.window)) fail('unknown window code');
    if (typeof e.kwh !== 'number' || !Number.isFinite(e.kwh) || e.kwh < 0) fail('invalid energy');
    const centi = Math.round(e.kwh * 100);
    if (centi / 100 !== e.kwh || centi > 999999) fail('invalid energy');
    if (prevTime !== null && e.time < prevTime) fail('entries out of order');
    prevTime = e.time;
    lines.push('E ' + m[1] + m[2] + m[3] + 'T' + m[4] + m[5] + ' ' + e.window + ' ' + centi);
