export function decodeBill(record) {
  if (typeof record !== 'string' || record === '') fail('empty input');

  const lines = record.split('\n');
  if (lines[lines.length - 1] === '') lines.pop();
  if (lines.length < 3) fail('malformed record');

  const chkLine = lines[lines.length - 1];
  if (!CHK_LINE_RE.test(chkLine)) fail('malformed record');

  const body = lines.slice(0, -1).join('\n') + '\n';
  if (String(checksumOf(body)).padStart(5, '0') !== chkLine.slice(4)) fail('checksum mismatch');

  if (!lines[0].startsWith('MTR ')) fail('malformed record');
  const meterId = lines[0].slice(4);
  if (!METER_ID_RE.test(meterId)) fail('invalid meter id');

  if (!lines[1].startsWith('TAR ')) fail('malformed record');
  const tarRest = lines[1].slice(4);
  const sp = tarRest.indexOf(' ');
  if (sp === -1) fail('malformed record');
  const tariffName = tarRest.slice(0, sp);
  if (!TARIFF_NAME_RE.test(tariffName)) fail('invalid tariff name');

  const winTokens = tarRest.slice(sp + 1).split(',');
  if (winTokens.length > 6) fail('too many windows');

  const windows = [];
  const codes = new Set();
  for (const token of winTokens) {
    // CODE/from-to/centsPerKWh => exactly 4 parts separated by '/' and '-'.
    const parts = token.split(/[\/-]/);
    if (parts.length !== 4) fail('malformed record');
    const code = parts[0];
    const from = parts[1];
    const to = parts[2];
    const rateStr = parts[3];
    if (!WINDOW_CODE_RE.test(code)) fail('invalid window code');
    if (!CLOCK_RE.test(from) || !CLOCK_RE.test(to) || from === to) fail('invalid window time');
    if (!RATE_RE.test(rateStr)) fail('invalid rate');
    const cents = Number(rateStr);
    if (cents < 1 || cents > 999) fail('invalid rate');
    if (codes.has(code)) fail('duplicate window code');
    codes.add(code);
    windows.push({ code, from, to, centsPerKWh: cents });
  }

  const entries = [];
  let prevTime = null;
  for (let i = 2; i < lines.length - 1; i++) {
    const line = lines[i];
    if (!line.startsWith('E ')) fail('malformed record');
    const toks = line.slice(2).split(' ');
    if (toks.length !== 3 || toks[0] === '' || toks[1] === '' || toks[2] === '') fail('malformed record');
    const stamp = toks[0];
    const code = toks[1];
    const energyTok = toks[2];

    const m = STAMP_RE.exec(stamp);
    if (!m || !validDateTime(+m[1], +m[2], +m[3], +m[4], +m[5])) fail('invalid entry time');
    if (!codes.has(code)) fail('unknown window code');
    if (!ENERGY_RE.test(energyTok)) fail('invalid energy');

    const time = m[1] + '-' + m[2] + '-' + m[3] + 'T' + m[4] + ':' + m[5];
    // Equal timestamps are allowed; only strictly earlier ones are out of order.
    if (prevTime !== null && time < prevTime) fail('entries out of order');
    prevTime = time;

    entries.push({ time, window: code, kwh: Number(energyTok) / 100 });
  }

  return { meterId, tariffName, windows, entries };
}
