const INVALID_ADDRESS = 'Invalid email address';

export function normalizeAddress(address) {
  if (typeof address !== 'string') {
    throw new Error(INVALID_ADDRESS);
  }

  const trimmed = address.trim().toLowerCase();

  const atCount = trimmed.split('@').length - 1;
  if (atCount !== 1) {
    throw new Error(INVALID_ADDRESS);
  }

  const atIndex = trimmed.indexOf('@');
  let local = trimmed.slice(0, atIndex);
  const domain = trimmed.slice(atIndex + 1);

  // Strip the plus-tag: everything from the first '+' up to the '@'.
  const plusIndex = local.indexOf('+');
  if (plusIndex !== -1) {
    local = local.slice(0, plusIndex);
  }
  if (local.length === 0) {
    throw new Error(INVALID_ADDRESS);
  }

  if (
    domain.length === 0 ||
    !domain.includes('.') ||
    domain.startsWith('.') ||
    domain.endsWith('.') ||
    domain.includes('..')
  ) {
    throw new Error(INVALID_ADDRESS);
  }

  return `${local}@${domain}`;
}

function withDefaults(config) {
  const c = config || {};
  return {
    vipAddresses: Array.isArray(c.vipAddresses) ? c.vipAddresses : [],
    internalDomains: Array.isArray(c.internalDomains) ? c.internalDomains : [],
    keywordPoints: Array.isArray(c.keywordPoints) ? c.keywordPoints : [],
  };
}

function senderDomain(normalized) {
  return normalized.slice(normalized.indexOf('@') + 1);
}

function containsCaseInsensitive(haystack, needle) {
  return haystack.toLowerCase().includes(needle.toLowerCase());
}

export function computeScore(email, config) {
  const { vipAddresses, internalDomains, keywordPoints } = withDefaults(config);

  const normalizedFrom = normalizeAddress(email.from);
  const domain = senderDomain(normalizedFrom);

  let score = 0;

  for (const vip of vipAddresses) {
    let normalizedVip;
    try {
      normalizedVip = normalizeAddress(vip);
    } catch (err) {
      continue; // invalid VIP entries simply never match
    }
    if (normalizedVip === normalizedFrom) {
      score += 30;
      break;
    }
  }

  const internalSet = new Set(
    internalDomains.map((d) => String(d).trim().toLowerCase())
  );
  if (internalSet.has(domain)) {
    score += 20;
  }

  for (const { word, points } of keywordPoints) {
    const w = String(word);
    if (containsCaseInsensitive(email.subject, w)) {
      score += points;
    }
    if (containsCaseInsensitive(email.body, w)) {
      score += points;
    }
  }

  return Math.max(0, Math.min(100, score));
}

export function routeEmail(email, rules, config) {
  const normalizedFrom = normalizeAddress(email.from);
  const domain = senderDomain(normalizedFrom);

  for (const rule of Array.isArray(rules) ? rules : []) {
    const when = rule.when || {};

    if (
      Object.prototype.hasOwnProperty.call(when, 'fromDomain') &&
      when.fromDomain !== undefined
    ) {
      if (domain !== String(when.fromDomain).trim().toLowerCase()) {
        continue;
      }
    }

    if (
      Object.prototype.hasOwnProperty.call(when, 'subjectContains') &&
      when.subjectContains !== undefined
    ) {
      if (!containsCaseInsensitive(email.subject, String(when.subjectContains))) {
        continue;
      }
    }

    if (
      Object.prototype.hasOwnProperty.call(when, 'minScore') &&
      when.minScore !== undefined
    ) {
      if (computeScore(email, config) <= when.minScore) {
        continue;
      }
    }

    return { queue: rule.queue, rule: rule.name };
  }

  return { queue: 'unassigned', rule: null };
}

export function planRouting(emails, rules, config) {
  const emailList = Array.isArray(emails) ? emails : [];

  const routes = [];
  const queueCounts = {};

  const scored = emailList.map((email) => ({
    email,
    score: computeScore(email, config),
  }));

  for (const { email } of scored) {
    const { queue, rule } = routeEmail(email, rules, config);
    routes.push({ id: email.id, queue, rule });
    queueCounts[queue] = (queueCounts[queue] || 0) + 1;
  }

  const urgentFirst = scored
    .filter(({ score }) => score >= 80)
    .map(({ email, score }) => ({ id: email.id, score, receivedAt: email.receivedAt }))
    .sort((a, b) => {
      if (b.score !== a.score) return b.score - a.score;
      if (a.receivedAt !== b.receivedAt) return a.receivedAt - b.receivedAt;
      return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
    })
    .map(({ id }) => id);

  return { routes, queueCounts, urgentFirst };
}
