// Subnet Fleet Simulator - IP/CIDR utilities and a deterministic block allocator.

const MAX_UINT32 = 4294967295;

function isDigits(s) {
  if (s.length === 0) return false;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c < 48 || c > 57) return false;
  }
  return true;
}

export function parseIp(ip) {
  const bad = () => {
    throw new Error(`Invalid IP address: ${ip}`);
  };
  if (typeof ip !== 'string') bad();
  const parts = ip.split('.');
  if (parts.length !== 4) bad();
  let value = 0;
  for (const part of parts) {
    if (!isDigits(part)) bad();
    if (part.length > 1 && part[0] === '0') bad();
    const n = Number(part);
    if (n > 255) bad();
    value = value * 256 + n;
  }
  return value;
}

export function formatIp(value) {
  if (!Number.isInteger(value) || value < 0 || value > MAX_UINT32) {
    throw new Error(`Invalid IP integer: ${value}`);
  }
  return [value >>> 24, (value >>> 16) & 255, (value >>> 8) & 255, value & 255].join('.');
}

export function parseCidr(cidr) {
  const bad = () => {
    throw new Error(`Invalid CIDR: ${cidr}`);
  };
  if (typeof cidr !== 'string') bad();
  const pieces = cidr.split('/');
  if (pieces.length !== 2) bad();
  let ipValue;
  try {
    ipValue = parseIp(pieces[0]);
  } catch (e) {
    bad();
  }
  const p = pieces[1];
  if (!isDigits(p)) bad();
  if (p.length > 1 && p[0] === '0') bad();
  const prefix = Number(p);
  if (prefix > 32) bad();
  const mask = prefix === 0 ? 0 : (0xFFFFFFFF << (32 - prefix)) >>> 0;
  const network = (ipValue & mask) >>> 0;
  const broadcast = (network | (~mask >>> 0)) >>> 0;
  return {
    network: formatIp(network),
    broadcast: formatIp(broadcast),
    prefix,
    mask: formatIp(mask),
    totalAddresses: 2 ** (32 - prefix),
  };
}

export function cidrContains(cidr, ip) {
  const info = parseCidr(cidr);
  const value = parseIp(ip);
  const network = parseIp(info.network);
  const broadcast = parseIp(info.broadcast);
