}

export function cidrSplit(cidr, newPrefix) {
  const info = parseCidr(cidr);
  if (!Number.isInteger(newPrefix) || newPrefix < 0 || newPrefix > 32) {
    throw new Error(`Invalid prefix: ${newPrefix}`);
  }
  if (newPrefix < info.prefix) {
    throw new Error(`Cannot split /${info.prefix} into /${newPrefix}`);
  }
  const count = 2 ** (newPrefix - info.prefix);
  if (count > 65536) {
    throw new Error(`Too many subnets: ${count}`);
  }
  const network = parseIp(info.network);
  const size = 2 ** (32 - newPrefix);
  const result = [];
  for (let i = 0; i < count; i++) {
    result.push(`${formatIp(network + i * size)}/${newPrefix}`);
  }
  return result;
}

function rangeToCidrs(start, end) {
  const result = [];
  let cur = start;
  while (cur <= end) {
    let size = 1;
    while (size * 2 <= end - cur + 1 && cur % (size * 2) === 0) {
      size *= 2;
    }
    const prefix = 32 - Math.log2(size);
    result.push(`${formatIp(cur)}/${prefix}`);
    cur += size;
  }
  return result;
}

export function cidrMerge(cidrs) {
  const ranges = cidrs.map((entry) => {
    const info = parseCidr(entry); // throws `Invalid CIDR: <entry>`
