export function runSimulation(baseCidr, blockPrefix, commands) {
  const base = parseCidr(baseCidr);
  if (!Number.isInteger(blockPrefix) || blockPrefix <= base.prefix || blockPrefix > 32) {
    throw new Error(`Invalid block prefix: ${blockPrefix}`);
  }
  if (!Array.isArray(commands)) {
    throw new Error('Invalid command list');
  }
  const totalBlocks = 2 ** (blockPrefix - base.prefix);
  if (totalBlocks > 65536) {
    throw new Error(`Too many blocks: ${totalBlocks}`);
  }

  const baseNetwork = parseIp(base.network);
  const baseBroadcast = parseIp(base.broadcast);
  const blockSize = 2 ** (32 - blockPrefix);

  const blocks = new Array(totalBlocks).fill(null); // block index -> owner name or null
  const ownerIndex = new Map(); // name -> block index
  const order = []; // names in (re)allocation order
  const log = [];

  const blockCidr = (index) =>
    `${formatIp(baseNetwork + index * blockSize)}/${blockPrefix}`;

  let step = 0;
  for (const cmd of commands) {
    step++;
    const isObject = cmd !== null && typeof cmd === 'object';
    const op = isObject ? cmd.op : undefined;
    if (op !== 'allocate' && op !== 'release' && op !== 'check') {
      throw new Error(`Unknown operation: ${op}`);
    }

    if (op === 'allocate') {
      const name = cmd.name;
      if (typeof name !== 'string' || name.length === 0) {
        throw new Error('allocate requires a name');
      }
      if (ownerIndex.has(name)) {
        log.push({
          step,
          op: 'allocate',
          status: 'error',
          message: `name already allocated: ${name}`,
        });
        continue;
      }
      let index;
      if (cmd.index !== undefined) {
        if (!Number.isInteger(cmd.index) || cmd.index < 0 || cmd.index >= totalBlocks) {
          log.push({
            step,
            op: 'allocate',
            status: 'error',
            message: `invalid block index: ${cmd.index}`,
          });
          continue;
        }
        if (blocks[cmd.index] !== null) {
          log.push({
            step,
            op: 'allocate',
            status: 'error',
            message: `block already in use: ${cmd.index}`,
          });
          continue;
        }
        index = cmd.index;
      } else {
        index = blocks.indexOf(null);
        if (index === -1) {
          log.push({
            step,
            op: 'allocate',
            status: 'error',
            message: 'no free block available',
          });
          continue;
        }
      }
      blocks[index] = name;
      ownerIndex.set(name, index);
      order.push(name);
      log.push({ step, op: 'allocate', status: 'ok', name, cidr: blockCidr(index) });
    } else if (op === 'release') {
      const name = cmd.name;
      if (typeof name !== 'string' || name.length === 0) {
        throw new Error('release requires a name');
      }
      if (!ownerIndex.has(name)) {
        log.push({
          step,
          op: 'release',
          status: 'error',
          message: `not allocated: ${name}`,
        });
        continue;
      }
      const index = ownerIndex.get(name);
      blocks[index] = null;
      ownerIndex.delete(name);
      order.splice(order.indexOf(name), 1);
      log.push({ step, op: 'release', status: 'ok', name, cidr: blockCidr(index) });
    } else {
      // check
      let value;
      try {
        value = parseIp(cmd.ip);
      } catch (e) {
        log.push({
          step,
          op: 'check',
          status: 'error',
          message: `invalid IP address: ${cmd.ip}`,
        });
        continue;
      }
      if (value < baseNetwork || value > baseBroadcast) {
        log.push({ step, op: 'check', status: 'ok', ip: cmd.ip, state: 'outside' });
        continue;
      }
      const index = Math.floor((value - baseNetwork) / blockSize);
      if (blocks[index] === null) {
        log.push({ step, op: 'check', status: 'ok', ip: cmd.ip, state: 'free' });
      } else {
        log.push({
          step,
          op: 'check',
          status: 'ok',
          ip: cmd.ip,
          state: 'allocated',
          name: blocks[index],
          cidr: blockCidr(index),
        });
      }
    }
  }

  const allocations = {};
  for (const name of order) {
    allocations[name] = blockCidr(ownerIndex.get(name));
  }
  let freeBlocks = 0;
  for (const b of blocks) {
    if (b === null) freeBlocks++;
  }

  return {
    base: `${base.network}/${base.prefix}`,
    blockPrefix,
    totalBlocks,
    freeBlocks,
    allocations,
    log,
  };
}
```

Notes on the implementation:

- **Strict parsing**: `isDigits` checks each character's code point directly, so whitespace, newlines, and other stray characters are rejected (a plain `/^\d+$/` regex would let a trailing `\n` slip through `$`).
- **Bitwise care**: the `/0` mask is special-cased (since `<< 32` is a no-op in JS), and `>>> 0` keeps every intermediate value an unsigned 32-bit integer.
- **`cidrMerge`**: converts each CIDR to a `{start, end}` range, sorts, merges touching/overlapping ranges, then re-encodes each merged range as the minimal set of aligned power-of-two blocks (the standard range→CIDR decomposition).
- **`runSimulation`**: structural problems (bad base, bad block prefix, non-array commands, unknown `op`, missing name) throw immediately; operational failures only push error log entries and consume a step. The `allocations` object is rebuilt from the `order` array so key insertion order reflects the most recent allocation order after releases/reallocations.

