export function runSimulation(baseCidr, blockPrefix, commands) {
  const base = parseCidr(baseCidr);
  if (!Number.isInteger(blockPrefix) || blockPrefix <= base.prefix || blockPrefix > 32) {
    throw new Error(`Invalid block prefix: ${blockPrefix}`);
  }
  if (!Array.isArray(commands)) throw new Error('Invalid command list');
  const totalBlocks = 2 ** (blockPrefix - base.prefix);
  if (totalBlocks > 65536) throw new Error(`Too many blocks: ${totalBlocks}`);

  const baseNetwork = parseIp(base.network);
  const baseBroadcast = parseIp(base.broadcast);
  const blockSize = 2 ** (32 - blockPrefix);

  const blocks = new Array(totalBlocks).fill(null); // name or null
  const ownerIndex = new Map(); // name -> block index
  const order = []; // names in (re)allocation order
  const log = [];

  const blockCidr = (i) => `${formatIp(baseNetwork + i * blockSize)}/${blockPrefix}`;

  let step = 0;
  for (const cmd of commands) {
    step++;
    const isObj = cmd !== null && typeof cmd === 'object';
    const op = isObj ? cmd.op : undefined;
    if (op !== 'allocate' && op !== 'release' && op !== 'check') {
      throw new Error(`Unknown operation: ${op}`);
    }
    if (op === 'allocate') {
      const name = cmd.name;
      if (typeof name !== 'string' || name.length === 0) throw new Error('allocate requires a name');
      if (ownerIndex.has(name)) {
        log.push({ step, op: 'allocate', status: 'error', message: `name already allocated: ${name}` });
        continue;
      }
      let index;
      if (cmd.index !== undefined) {
        if (!Number.isInteger(cmd.index) || cmd.index < 0 || cmd.index >= totalBlocks) {
          log.push({ step, op: 'allocate', status: 'error', message: `invalid block index: ${cmd.index}` });
          continue;
        }
        if (blocks[cmd.index] !== null) {
          log.push({ step, op: 'allocate', status: 'error', message: `block already in use: ${cmd.index}` });
          continue;
        }
        index = cmd.index;
      } else {
        index = blocks.indexOf(null);
        if (index === -1) {
          log.push({ step, op: 'allocate', status: 'error', message: 'no free block available' });
          continue;
        }
      }
      blocks[index] = name;
      ownerIndex.set(name, index);
      order.push(name);
      log.push({ step, op: 'allocate', status: 'ok', name, cidr: blockCidr(index) });
    } else if (op === 'release') {
      const name = cmd.name;
      if (typeof name !== 'string' || name.length === 0) throw new Error('release requires a name');
      if (!ownerIndex.has(name)) {
        log.push({ step, op: 'release', status: 'error', message: `not allocated: ${name}` });
        continue;
      }
      const index = ownerIndex.get(name);
      blocks[index] = null;
      ownerIndex.delete(name);
      const oi = order.indexOf(name);
      order.splice(oi, 1);
      log.push({ step, op: 'release', status: 'ok', name, cidr: blockCidr(index) });
    } else { // check
      let value;
      try {
        value = parseIp(cmd.ip);
      } catch {
        log.push({ step, op: 'check', status: 'error', message: `invalid IP address: ${cmd.ip}` });
        continue;
      }
      if (value < baseNetwork || value > baseBroadcast) {
        log.push({ step, op: 'check', status: 'ok', ip: cmd.ip, state: 'outside' });
        continue;
      }
      const index = Math.floor((value - baseNetwork) / blockSize);
      if (blocks[index] === null) {
        log.push({ step, op: 'check', status: 'ok', ip: cmd.ip, state: 'free' });
      } else {
        log.push({ step, op: 'check', status: 'ok', ip: cmd.ip, state: 'allocated', name: blocks[index], cidr: blockCidr(index) });
      }
    }
  }

  const allocations = {};
  for (const name of order) allocations[name] = blockCidr(ownerIndex.get(name));
  const freeBlocks = blocks.reduce((n, b) => (b === null ? n + 1 : n), 0);

  return {
    base: `${base.network}/${base.prefix}`,
    blockPrefix,
    totalBlocks,
    freeBlocks,
    allocations,
    log,
  };
}
