"""Reconciler for environment files with variable interpolation."""

import re
from dataclasses import dataclass

_KEY_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")

_ESCAPES = {
    "n": "\n",
    "t": "\t",
    "\\": "\\",
    '"': '"',
    "$": "$",
}


@dataclass(frozen=True)
class Difference:
    """A single difference between two environment files.

    kind is one of "only_in_left", "only_in_right", "value_mismatch"
    or "raw_mismatch". left and right hold the relevant values (resolved
    values for the first three kinds, raw definitions for "raw_mismatch"),
    with None marking the side that does not define the key.
    """

    kind: str
    key: str
    left: str | None
    right: str | None
    detail: str


class _EnvFile:
    """Parsed state of one environment file."""

    def __init__(self, text: str) -> None:
        self.order: list[str] = []                 # first-definition order
        self.defs: dict[str, tuple[int, str]] = {}  # key -> (line no, raw value)
        self._cache: dict[str, str] = {}            # resolved values (memoised)
        self._resolving: set[str] = set()
        self._parse(text)

    # ------------------------------------------------------------------
    # line-level parsing
    # ------------------------------------------------------------------

    def _parse(self, text: str) -> None:
        for n, raw_line in enumerate(text.split("\n"), 1):
            line = raw_line.strip()
            if not line or line.startswith("#"):
                continue
            body = line
            if body.startswith("export") and len(body) > 6 and body[6] in " \t":
                body = body[6:].lstrip(" \t")
            eq = body.find("=")
            if eq < 0:
                raise ValueError(f"Line {n} is not a valid assignment: '{line}'")
            key = body[:eq]
            if not _KEY_RE.fullmatch(key):
                raise ValueError(f"Line {n} is not a valid assignment: '{line}'")
            value = body[eq + 1:].strip()
            if key not in self.defs:
                self.order.append(key)
            self.defs[key] = (n, value)

    # ------------------------------------------------------------------
    # public views
    # ------------------------------------------------------------------

    def raw(self) -> dict[str, str]:
        return {key: self.defs[key][1] for key in self.order}

    def resolved(self) -> dict[str, str]:
        return {key: self._resolve(key, self.defs[key][0]) for key in self.order}

    # ------------------------------------------------------------------
    # resolution / rendering
    # ------------------------------------------------------------------

    def _resolve(self, key: str, err_line: int) -> str:
        if key in self._cache:
            return self._cache[key]
        if key in self._resolving:
            raise ValueError(f"Circular reference involving '{key}'")
        self._resolving.add(key)
        try:
            raw = self.defs[key][1]
            value = self._render_value(err_line, raw)
        finally:
            self._resolving.discard(key)
        self._cache[key] = value
        return value

    def _render_value(self, n: int, raw: str) -> str:
        if raw.startswith("'"):
            return self._render_single_quoted(n, raw)
        if raw.startswith('"'):
            return self._render_double_quoted(n, raw)
        return self._render_unquoted(n, raw)

    def _render_single_quoted(self, n: int, raw: str) -> str:
        end = raw.find("'", 1)
        if end < 0:
            raise ValueError(f"Line {n} has an unterminated single-quoted value")
        if raw[end + 1:]:
            raise ValueError(
                f"Line {n} has trailing characters after the closing quote")
        return raw[1:end]

    def _render_double_quoted(self, n: int, raw: str) -> str:
        out: list[str] = []
        i = 1
        while i < len(raw):
            ch = raw[i]
            if ch == "\\":
                if i + 1 >= len(raw):
                    break  # a lone trailing backslash: no closing quote
                esc = raw[i + 1]
                if esc not in _ESCAPES:
                    raise ValueError(
                        f"Line {n} contains invalid escape sequence '\\{esc}'")
                out.append(_ESCAPES[esc])
                i += 2
            elif ch == '"':
                if raw[i + 1:]:
                    raise ValueError(
                        f"Line {n} has trailing characters after the closing quote")
                return "".join(out)
            elif ch == "$" and raw.startswith("${", i):
                text, i = self._render_reference(n, raw, i)
                out.append(text)
            else:
                out.append(ch)
                i += 1
        raise ValueError(f"Line {n} has an unterminated double-quoted value")

    def _render_unquoted(self, n: int, raw: str) -> str:
        out: list[str] = []
        i = 0
        while i < len(raw):
            ch = raw[i]
            if ch == "$":
                if raw.startswith("$$", i):
                    out.append("$")
                    i += 2
                    continue
                if raw.startswith("${", i):
                    text, i = self._render_reference(n, raw, i)
                    out.append(text)
                    continue
            out.append(ch)
            i += 1
        return "".join(out)

    def _render_reference(self, n: int, raw: str, start: int) -> tuple[str, int]:
        """Render the reference beginning at raw[start] (which is '${').

        Returns (rendered text, index just past the closing brace).
        """
        i = start + 2
        depth = 1
        end = -1
        while i < len(raw):
            if raw.startswith("${", i):
                depth += 1
                i += 2
            elif raw[i] == "}":
                depth -= 1
                if depth == 0:
                    end = i
                    break
                i += 1
            else:
                i += 1
        if end < 0:
            raise ValueError(f"Line {n} has an unterminated variable reference")

        inner = raw[start + 2:end]
        sep = self._find_separator(inner)
        if sep < 0:
            name, default = inner, None
        else:
            name, default = inner[:sep], inner[sep + 2:]

        if not _KEY_RE.fullmatch(name):
            raise ValueError(f"Line {n} has invalid variable name '{name}'")

        if name in self.defs:
            value = self._resolve(name, n)
            if value == "" and default is not None:
                return self._render_unquoted(n, default), end + 1
            return value, end + 1

        if default is None:
            raise ValueError(f"Line {n} references undefined variable '{name}'")
        return self._render_unquoted(n, default), end + 1

    @staticmethod
    def _find_separator(inner: str) -> int:
        """Index of the first non-nested ':-' inside inner, or -1."""
        depth = 0
        i = 0
        while i < len(inner):
            if inner.startswith("${", i):
                depth += 1
                i += 2
            elif inner[i] == "}":
                depth -= 1
                i += 1
            elif depth == 0 and inner.startswith(":-", i):
                return i
            else:
                i += 1
        return -1


def parse_env_file(text: str) -> dict[str, str]:
    """Parse an environment file and return fully resolved key/value pairs."""
    return _EnvFile(text).resolved()


def raw_definitions(text: str) -> dict[str, str]:
    """Parse an environment file and return values exactly as written."""
    return _EnvFile(text).raw()


def reconcile(left_text: str, right_text: str) -> list[Difference]:
    """Compare two environment files and report every difference."""
    left_file = _EnvFile(left_text)
    left = left_file.resolved()
    left_raw = left_file.raw()

    right_file = _EnvFile(right_text)
    right = right_file.resolved()
    right_raw = right_file.raw()

    differences: list[Difference] = []
    keys = list(left) + [key for key in right if key not in left]
    for key in keys:
        if key not in right:
            differences.append(Difference(
                "only_in_left", key, left[key], None,
                f"key '{key}' is defined only in the left file"))
        elif key not in left:
            differences.append(Difference(
                "only_in_right", key, None, right[key],
                f"key '{key}' is defined only in the right file"))
        elif left[key] != right[key]:
            differences.append(Difference(
                "value_mismatch", key, left[key], right[key],
                f"key '{key}' resolves to '{left[key]}' in the left file "
                f"but '{right[key]}' in the right file"))
        elif left_raw[key] != right_raw[key]:
            differences.append(Difference(
                "raw_mismatch", key, left_raw[key], right_raw[key],
                f"key '{key}' resolves to the same value but raw "
                f"definitions differ: '{left_raw[key]}' vs '{right_raw[key]}'"))
    return differences
```

The bug: my `_resolve` propagated the *caller's* line number into the recursive rendering. Per the line-number rule, every error raised while a definition's value is being rendered must report **that definition's** line — so when `A` (line 1) references `B` (line 2), errors from rendering `B`'s value report line 2. The fix is to have `_resolve` always use the line number stored with the key's own definition.

```python
"""Reconciler for environment files with variable interpolation."""

import re
from dataclasses import dataclass

_KEY_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")

_ESCAPES = {
    "n": "\n",
    "t": "\t",
    "\\": "\\",
    '"': '"',
    "$": "$",
}


@dataclass(frozen=True)
class Difference:
    """A single difference between two environment files.

    kind is one of "only_in_left", "only_in_right", "value_mismatch"
    or "raw_mismatch". left and right hold the relevant values (resolved
    values for the first three kinds, raw definitions for "raw_mismatch"),
    with None marking the side that does not define the key.
    """

    kind: str
    key: str
    left: str | None
    right: str | None
    detail: str


class _EnvFile:
    """Parsed state of one environment file."""

    def __init__(self, text: str) -> None:
        self.order: list[str] = []                 # first-definition order
        self.defs: dict[str, tuple[int, str]] = {}  # key -> (line no, raw value)
        self._cache: dict[str, str] = {}            # resolved values (memoised)
        self._resolving: set[str] = set()
        self._parse(text)

    # ------------------------------------------------------------------
    # line-level parsing
    # ------------------------------------------------------------------

    def _parse(self, text: str) -> None:
        for n, raw_line in enumerate(text.split("\n"), 1):
            line = raw_line.strip()
            if not line or line.startswith("#"):
                continue
            body = line
            if body.startswith("export") and len(body) > 6 and body[6] in " \t":
                body = body[6:].lstrip(" \t")
            eq = body.find("=")
            if eq < 0:
                raise ValueError(f"Line {n} is not a valid assignment: '{line}'")
            key = body[:eq]
            if not _KEY_RE.fullmatch(key):
                raise ValueError(f"Line {n} is not a valid assignment: '{line}'")
            value = body[eq + 1:].strip()
            if key not in self.defs:
                self.order.append(key)
            self.defs[key] = (n, value)

    # ------------------------------------------------------------------
    # public views
    # ------------------------------------------------------------------

    def raw(self) -> dict[str, str]:
        return {key: self.defs[key][1] for key in self.order}

    def resolved(self) -> dict[str, str]:
        return {key: self._resolve(key) for key in self.order}

    # ------------------------------------------------------------------
    # resolution / rendering
    # ------------------------------------------------------------------

    def _resolve(self, key: str) -> str:
        """Resolve a key, reporting errors against its own definition line."""
        if key in self._cache:
            return self._cache[key]
        if key in self._resolving:
            raise ValueError(f"Circular reference involving '{key}'")
        self._resolving.add(key)
        try:
            n, raw = self.defs[key]
            value = self._render_value(n, raw)
        finally:
            self._resolving.discard(key)
        self._cache[key] = value
        return value

    def _render_value(self, n: int, raw: str) -> str:
        if raw.startswith("'"):
            return self._render_single_quoted(n, raw)
        if raw.startswith('"'):
            return self._render_double_quoted(n, raw)
        return self._render_unquoted(n, raw)

    def _render_single_quoted(self, n: int, raw: str) -> str:
        end = raw.find("'", 1)
        if end < 0:
            raise ValueError(f"Line {n} has an unterminated single-quoted value")
        if raw[end + 1:]:
            raise ValueError(
                f"Line {n} has trailing characters after the closing quote")
        return raw[1:end]

    def _render_double_quoted(self, n: int, raw: str) -> str:
        out: list[str] = []
        i = 1
        while i < len(raw):
            ch = raw[i]
            if ch == "\\":
                if i + 1 >= len(raw):
                    break  # a lone trailing backslash: no closing quote
                esc = raw[i + 1]
                if esc not in _ESCAPES:
                    raise ValueError(
                        f"Line {n} contains invalid escape sequence '\\{esc}'")
                out.append(_ESCAPES[esc])
                i += 2
            elif ch == '"':
                if raw[i + 1:]:
                    raise ValueError(
                        f"Line {n} has trailing characters after the closing quote")
                return "".join(out)
            elif ch == "$" and raw.startswith("${", i):
                text, i = self._render_reference(n, raw, i)
                out.append(text)
            else:
                out.append(ch)
                i += 1
        raise ValueError(f"Line {n} has an unterminated double-quoted value")

    def _render_unquoted(self, n: int, raw: str) -> str:
        out: list[str] = []
        i = 0
        while i < len(raw):
            ch = raw[i]
            if ch == "$":
                if raw.startswith("$$", i):
                    out.append("$")
                    i += 2
                    continue
                if raw.startswith("${", i):
                    text, i = self._render_reference(n, raw, i)
                    out.append(text)
                    continue
            out.append(ch)
            i += 1
        return "".join(out)

    def _render_reference(self, n: int, raw: str, start: int) -> tuple[str, int]:
        """Render the reference beginning at raw[start] (which is '${').

        Returns (rendered text, index just past the closing brace).
        """
        i = start + 2
        depth = 1
        end = -1
        while i < len(raw):
            if raw.startswith("${", i):
                depth += 1
                i += 2
            elif raw[i] == "}":
                depth -= 1
                if depth == 0:
                    end = i
                    break
                i += 1
            else:
                i += 1
        if end < 0:
            raise ValueError(f"Line {n} has an unterminated variable reference")

        inner = raw[start + 2:end]
        sep = self._find_separator(inner)
        if sep < 0:
            name, default = inner, None
        else:
            name, default = inner[:sep], inner[sep + 2:]

        if not _KEY_RE.fullmatch(name):
            raise ValueError(f"Line {n} has invalid variable name '{name}'")

        if name in self.defs:
            value = self._resolve(name)
            if value == "" and default is not None:
                return self._render_unquoted(n, default), end + 1
            return value, end + 1

        if default is None:
            raise ValueError(f"Line {n} references undefined variable '{name}'")
        return self._render_unquoted(n, default), end + 1

    @staticmethod
    def _find_separator(inner: str) -> int:
        """Index of the first non-nested ':-' inside inner, or -1."""
        depth = 0
        i = 0
        while i < len(inner):
            if inner.startswith("${", i):
                depth += 1
                i += 2
            elif inner[i] == "}":
                depth -= 1
                i += 1
            elif depth == 0 and inner.startswith(":-", i):
                return i
            else:
                i += 1
        return -1


def parse_env_file(text: str) -> dict[str, str]:
    """Parse an environment file and return fully resolved key/value pairs."""
    return _EnvFile(text).resolved()


def raw_definitions(text: str) -> dict[str, str]:
    """Parse an environment file and return values exactly as written."""
    return _EnvFile(text).raw()


def reconcile(left_text: str, right_text: str) -> list[Difference]:
    """Compare two environment files and report every difference."""
    left_file = _EnvFile(left_text)
    left = left_file.resolved()
    left_raw = left_file.raw()

    right_file = _EnvFile(right_text)
    right = right_file.resolved()
    right_raw = right_file.raw()

    differences: list[Difference] = []
    keys = list(left) + [key for key in right if key not in left]
    for key in keys:
        if key not in right:
            differences.append(Difference(
                "only_in_left", key, left[key], None,
                f"key '{key}' is defined only in the left file"))
        elif key not in left:
            differences.append(Difference(
                "only_in_right", key, None, right[key],
                f"key '{key}' is defined only in the right file"))
        elif left[key] != right[key]:
            differences.append(Difference(
                "value_mismatch", key, left[key], right[key],
                f"key '{key}' resolves to '{left[key]}' in the left file "
                f"but '{right[key]}' in the right file"))
        elif left_raw[key] != right_raw[key]:
            differences.append(Difference(
                "raw_mismatch", key, left_raw[key], right_raw[key],
                f"key '{key}' resolves to the same value but raw "
                f"definitions differ: '{left_raw[key]}' vs '{right_raw[key]}'"))
    return differences
```

## Cause

Two bugs, both in the rule-checking section (the input validation and the other rules are fine):

1. **Rule 5 (skills)** — The heavy-room threshold is checked with `room.credits > DEEP_CLEAN_CREDITS` (`> 30`), but the spec says a room is heavy if its credits are **30 or more** (`>= 30`). That's why your 30-credit room didn't require `deep-clean`. (Note the docstring's other places use the constant correctly; it's just this comparison.)

2. **Rule 6 (floor spread)** — The floor-spread computation filters rooms with `if room_by_number[number].status in CLEANING_STATUSES`, i.e., it only counts rooms that need cleaning. The spec explicitly says the floors considered are those of **all** assigned rooms, *regardless of status*. This filter should be removed, which explains why `vacant-clean`/`vacant-inspected` rooms on floors 3 and 5 were ignored. (Rule 7 *does* correctly filter to cleaning-status rooms, so leave that as is.)

## Fix

hotel_housekeeping_validator.py
```python
"""Validator for hotel housekeeping room assignments."""

from __future__ import annotations

import re
from dataclasses import dataclass

STATUSES = (
    "occupied",
    "vacant-dirty",
    "vacant-clean",
    "vacant-inspected",
    "out-of-order",
)

CLEANING_STATUSES = ("occupied", "vacant-dirty")
NO_CLEANING_STATUSES = ("vacant-clean", "vacant-inspected")
KNOWN_SKILLS = ("vip", "deep-clean")
DEEP_CLEAN_CREDITS = 30

_ROOM_NUMBER = re.compile(r"^[1-9][0-9]{2}$")


@dataclass(frozen=True)
class Room:
    """A hotel room with its current status."""

    number: str
    floor: int
    status: str
    credits: int
    vip: bool = False


@dataclass(frozen=True)
class Attendant:
    """A housekeeping attendant on shift."""

    name: str
    max_credits: int
    skills: frozenset[str] = frozenset()


def _validate_inputs(
    rooms: list[Room],
    attendants: list[Attendant],
    assignments: dict[str, list[str]],
) -> None:
    """Raise ValueError on the first malformed record found."""
    # Phase 1: rooms, in list order.
    seen_rooms: set[str] = set()
    for room in rooms:
        if room.number in seen_rooms:
            raise ValueError(f"duplicate room number: {room.number}")
        seen_rooms.add(room.number)
        if room.status not in STATUSES:
            raise ValueError(f"invalid status for room {room.number}: {room.status}")
        if room.credits <= 0:
            raise ValueError(f"room {number] if False else room.number} has non-positive credits") if False else None
        if room.credits <= 0:
            raise ValueError(f"room {room.number} has non-positive credits")
        if _ROOM_NUMBER.match(room.number) is None:
            raise ValueError(f"room {room.number} has a malformed number")
        implied = int(room.number[0])
        if implied != room.floor:
            raise ValueError(
                f"room {room.number} has inconsistent floor: "
                f"number implies {implied} but floor is {room.floor}"
            )

    # Phase 2: attendants, in list order.
    seen_attendants: set[str] = set()
    for attendant in attendants:
        if attendant.name in seen_attendants:
            raise ValueError(f"duplicate attendant: {attendant.name}")
        seen_attendants.add(attendant.name)
        if attendant.max_credits <= 0:
            raise ValueError(f"attendant {attendant.name} has non-positive max credits")
        for skill in sorted(attendant.skills):
            if skill not in KNOWN_SKILLS:
                raise ValueError(
                    f"attendant {attendant.name} has unknown skill: {skill}"
                )

    # Phase 3: assignments, keys in insertion order.
    for name, room_numbers in assignments.items():
        if name not in seen_attendants:
            raise ValueError(f"unknown attendant: {name}")
        for number in room_numbers:
            if number not in seen_rooms:
                raise ValueError(f"unknown room: {number}")


def validate_assignments(
    rooms: list[Room],
    attendants: list[Attendant],
    assignments: dict[str, list[str]],
) -> list[str]:
    """Validate a housekeeping plan.

    Return every detected problem as a string, ordered by rule and then by
    the position of the offending room or attendant, or raise a ValueError
    when the room, attendant or assignment records are malformed.
    """
    _validate_inputs(rooms, attendants, assignments)

    room_by_number = {room.number: room for room in rooms}
    attendant_by_name = {attendant.name: attendant for attendant in attendants}

    # Rooms assigned to each attendant (in list order, duplicates kept),
    # and attendants holding each room (in attendants list order).
    assigned_to: dict[str, list[str]] = {att.name: [] for att in attendants}
    holders: dict[str, list[Attendant]] = {room.number: [] for room in rooms}
    for attendant in attendants:
        for number in assignments.get(attendant.name, []):
            assigned_to[attendant.name].append(number)
            holders[number].append(attendant)

    # Distinct holders per room, preserving attendants-list order.
    distinct_holders: dict[str, list[Attendant]] = {
        number: list(dict.fromkeys(holder_list))
        for number, holder_list in holders.items()
    }

    problems: list[str] = []

    # Rule 1: out-of-order rooms must never be assigned.
    for room in rooms:
        if room.status == "out-of-order" and holders[room.number]:
            problems.append(
                f"out-of-order room {room.number} is assigned to "
                f"{holders[room.number][0].name}"
            )

    # Rule 2: rooms that do not need cleaning must not be assigned.
    for room in rooms:
        if room.status in NO_CLEANING_STATUSES and holders[room.number]:
            problems.append(
                f"room {room.number} ({room.status}) does not need cleaning "
                f"but is assigned to {holders[room.number][0].name}"
            )

    # Rule 3: every room that needs cleaning must be assigned.
    for room in rooms:
        if room.status in CLEANING_STATUSES and not holders[room.number]:
            problems.append(f"room {room.number} needs cleaning but is unassigned")

    # Rule 4: at most one attendant, at most once.
    for room in rooms:
        holder_list = distinct_holders[room.number]
        if len(holder_list) >= 2:
            names = ", ".join(att.name for att in holder_list)
            problems.append(
                f"room {room.number} is assigned to more than one attendant: {names}"
            )
        elif holder_list:
            attendant = holder_list[0]
            if holders[room.number].count(attendant) > 1:
                problems.append(
                    f"room {room.number} is assigned more than once to {attendant.name}"
                )

    # Rule 5: skill requirements for rooms that need cleaning.
    for room in rooms:
        if room.status not in CLEANING_STATUSES:
            continue
        required: list[str] = []
        if room.vip:
            required.append("vip")
        if room.credits >= DEEP_CLEAN_CREDITS:
            required.append("deep-clean")
        if not required:
            continue
        for attendant in distinct_holders[room.number]:
            missing = [skill for skill in required if skill not in attendant.skills]
            if missing:
                missing_str = ", ".join(f"'{skill}'" for skill in missing)
                problems.append(
                    f"room {room.number} assigned to {attendant.name} "
                    f"lacks required skills: {missing_str}"
                )

    # Rule 6: floor spread per attendant.
    # All assigned rooms count, regardless of status, each distinct room once.
    for attendant in attendants:
        floors = sorted(
            {
                room_by_number[number].floor
                for number in set(assigned_to[attendant.name])
            }
        )
        if len(floors) > 2 or (len(floors) == 2 and floors[1] - floors[0] != 1):
            floors_str = ", ".join(str(floor) for floor in floors)
            problems.append(
                f"attendant {attendant.name} has a disallowed floor spread: {floors_str}"
            )

    # Rule 7: credit limit per attendant.
    for attendant in attendants:
        load = sum(
            room_by_number[number].credits
            for number in set(assigned_to[attendant.name])
            if room_by_number[number].status in CLEANING_STATUSES
        )
        if load > attendant.max_credits:
            problems.append(
                f"attendant {attendant.name} exceeds credit limit: "
                f"{load}/{attendant.max_credits}"
            )

    return problems
