                    f"room {room.number} is assigned more than once to {attendant.name}"
                )

    # Rule 5: skill requirements for rooms that need cleaning.
    for room in rooms:
        if room.status not in CLEANING_STATUSES:
            continue
        required: list[str] = []
        if room.vip:
            required.append("vip")
        if room.credits >= DEEP_CLEAN_CREDITS:
            required.append("deep-clean")
        if not required:
            continue
        for attendant in distinct_holders[room.number]:
            missing = [skill for skill in required if skill not in attendant.skills]
            if missing:
                missing_str = ", ".join(f"'{skill}'" for skill in missing)
                problems.append(
                    f"room {room.number} assigned to {attendant.name} "
                    f"lacks required skills: {missing_str}"
                )

    # Rule 6: floor spread per attendant.
    # All assigned rooms count, regardless of status, each distinct room once.
    for attendant in attendants:
        floors = sorted(
            {
                room_by_number[number].floor
                for number in set(assigned_to[attendant.name])
            }
        )
        if len(floors) > 2 or (len(floors) == 2 and floors[1] - floors[0] != 1):
            floors_str = ", ".join(str(floor) for floor in floors)
            problems.append(
                f"attendant {attendant.name} has a disallowed floor spread: {floors_str}"
            )

    # Rule 7: credit limit per attendant.
    for attendant in attendants:
        load = sum(
            room_by_number[number].credits
            for number in set(assigned_to[attendant.name])
            if room_by_number[number].status in CLEANING_STATUSES
        )
        if load > attendant.max_credits:
            problems.append(
                f"attendant {attendant.name} exceeds credit limit: "
                f"{load}/{attendant.max_credits}"
            )

    return problems
