```python
"""A tiny rule interpreter that routes restaurant order items to kitchen stations."""

import re

_TOKEN_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


def _is_token(value: str) -> bool:
    """Return True if value matches [A-Za-z0-9][A-Za-z0-9_-]* exactly."""
    return _TOKEN_RE.fullmatch(value) is not None


class _Item:
    __slots__ = ("name", "station")

    def __init__(self, name: str, station: str) -> None:
        self.name = name
        self.station = station


class _Override:
    __slots__ = ("pattern", "station")

    def __init__(self, pattern: str, station: str) -> None:
        self.pattern = pattern
        self.station = station

    def matches(self, item_name: str, tags: list[str]) -> bool:
        if self.pattern == "default":
            return True
        if self.pattern.startswith("item:"):
            return item_name == self.pattern[len("item:"):]
        # tag:...
        return self.pattern[len("tag:"):] in tags


class KitchenRouter:
    """Parses a routing program and routes orders to kitchen stations."""

    def __init__(self, program: str) -> None:
        """Parse and validate the routing program.

        Raises ValueError for malformed lines, invalid patterns,
        duplicate declarations, or references to unknown stations/items.
        """
        # Ordered declarations.
        self._stations: list[str] = []
        self._station_set: set[str] = set()
        self._items: dict[str, _Item] = {}
        self._item_order: list[str] = []
        self._items_list: list[_Item] = []
        self._overrides: list[_Override] = []

        for lineno, raw_line in enumerate(program.split("\n"), start=1):
            line = raw_line.strip()
            if not line:
                continue
            if line.startswith("#"):
                continue

            tokens = line.split()

            if len(tokens) == 2 and tokens[0] == "station" and _is_token(tokens[1]):
                name = tokens[1]
                if name in self._station_set:
                    raise ValueError(f"duplicate station: {name}")
                self._station_set.add(name)
                self._stations.append(name)
                continue

            if len(tokens) == 4 and tokens[0] == "item" and tokens[2] == "->" \
                    and _is_token(tokens[1]) and _is_token(tokens[3]):
                name, station = tokens[1], tokens[3]
                if name in self._items:
                    raise ValueError(f"duplicate item: {name}")
                item = _Item(name, station)
                self._items[name] = item
                self._item_order.append(name)
                self._items_list.append(item)
                continue

            if len(tokens) == 4 and tokens[0] == "override" and tokens[2] == "->" \
                    and _is_token(tokens[3]):
                pattern, station = tokens[1], tokens[3]
                if not self._is_valid_pattern(pattern):
                    raise ValueError(f"bad pattern: {pattern}")
                self._overrides.append(_Override(pattern, station))
                continue

            raise ValueError(f"bad line {lineno}: {line}")

        # Resolve references: items first, then overrides.
        for item in self._items_list:
            if item.station not in self._station_set:
                raise ValueError(f"unknown station: {item.station}")

        for override in self._overrides:
            if override.pattern.startswith("item:"):
                target = override.pattern[len("item:"):]
                if target not in self._items:
                    raise ValueError(f"unknown item: {target}")
            if override.station not in self._station_set:
                raise ValueError(f"unknown station: {override.station}")

    @staticmethod
    def _is_valid_pattern(pattern: str) -> bool:
        if pattern == "default":
            return True
        if pattern.startswith("item:"):
            return _is_token(pattern[len("item:"):])
        if pattern.startswith("tag:"):
            return _is_token(pattern[len("tag:"):])
        return False

    def stations(self) -> list[str]:
        """Return the declared station names in declaration order."""
        return list(self._stations)

    def route(self, order: dict[str, list[str]]) -> dict[str, list[str]]:
        """Route an order (item name -> list of tags) to stations.

        Returns a dict mapping every declared station to the list of item
        names routed there, in order of appearance in the order.
        """
        result: dict[str, list[str]] = {station: [] for station in self._stations}

        for item_name, tags in order.items():
            item = self._items.get(item_name)
            if item is None:
                raise ValueError(f"unknown item: {item_name}")

            destination = item.station
            for override in self._overrides:
                if override.matches(item_name, tags):
                    destination = override.station
                    break

            result[destination].append(item_name)

        return result


def route_order(program: str, order: dict[str, list[str]]) -> dict[str, list[str]]:
    """Convenience helper: build a router from the program and route the order."""
    return KitchenRouter(program).route(order)
```

### Summary of the fixes

1. **`_Override.matches` (the failing tests' root cause):** the tag check compared `self.pattern in tags`, i.e. `"tag:vegan" in ["vegan", "hot"]`, which is always `False`. It now strips the `tag:` prefix: `self.pattern[len("tag:"):] in tags`.

2. **`route` (latent bug):** the override loop kept scanning after a match, so a later rule would replace an earlier one — violating "the **first** matching rule wins." Added a `break` once a rule matches. (E.g. `override tag:hot -> grill` followed by `override default -> cold` must send hot items to the grill.)

3. **Minor cleanup:** removed the unused `tags` slot from `_Item`, which was declared but never assigned.

row_filters_index.py
```python
"""Inverted index for evaluating SQL-like WHERE filters over rows."""

_OPS = ("==", "!=", "<", "<=", ">", ">=", "in")
_CONTAINER_TYPES = (list, tuple, set, frozenset)


class FilterEngine:
    """Stores rows and named filters, keeping match sets in sync."""

    def __init__(self):
        self._rows = {}       # row_id -> row dict
        self._filters = {}    # filter name -> expression
        self._by_filter = {}  # filter name -> set of row ids matching it
        self._by_row = {}     # row id -> set of filter names it satisfies

    # ------------------------------------------------------------------
    # Expression validation / evaluation
    # ------------------------------------------------------------------

    @classmethod
    def _validate(cls, expr):
        """Raise ValueError('invalid filter expression') unless expr is valid."""
        if not isinstance(expr, tuple) or not expr:
            raise ValueError("invalid filter expression")
        kind = expr[0]
        if kind == "col":
            if len(expr) != 4:
                raise ValueError("invalid filter expression")
            _, column, op, literal = expr
            if not isinstance(column, str):
                raise ValueError("invalid filter expression")
            if op not in _OPS:
                raise ValueError("invalid filter expression")
            if op == "in" and not isinstance(literal, _CONTAINER_TYPES):
                raise ValueError("invalid filter expression")
        elif kind in ("and", "or"):
            if len(expr) != 3:
                raise ValueError("invalid filter expression")
            cls._validate(expr[1])
            cls._validate(expr[2])
        elif kind == "not":
            if len(expr) != 2:
                raise ValueError("invalid filter expression")
            cls._validate(expr[1])
        else:
            raise ValueError("invalid filter expression")

    @staticmethod
    def _eval(expr, row):
        """Evaluate a validated expression against a row. Never raises."""
        kind = expr[0]
        if kind == "col":
            _, column, op, literal = expr
            if column not in row:
                return False
            value = row[column]
            if op == "==":
                return value == literal
            if op == "!=":
                return value != literal
            try:
                if op == "<":
                    return value < literal
                if op == "<=":
                    return value <= literal
                if op == ">":
                    return value > literal
                if op == ">=":
                    return value >= literal
                # op == "in"
                return value in literal
            except TypeError:
                return False
        if kind == "and":
            return _eval_static(expr[1], row) and _eval_static(expr[2], row)
        if kind == "or":
            return _eval_static(expr[1], row) or _eval_static(expr[2], row)
        # kind == "not"
        return not _eval_static(expr[1], row)

    # ------------------------------------------------------------------
    # Filters
    # ------------------------------------------------------------------

    def add_filter(self, name, expr):
        if not isinstance(name, str) or not name:
            raise ValueError("invalid filter name")
        if name in self._filters:
            raise ValueError("duplicate filter: {}".format(name))
        self._validate(expr)

        matched = {rid for rid, row in self._rows.items() if self._eval(expr, row)}
        self._filters[name] = expr
        self._by_filter[name] = matched
        for rid in matched:
            self._by_row[rid].add(name)

    def remove_filter(self, name):
        if name not in self._filters:
            raise ValueError("unknown filter: {}".format(name))
        del self._filters[name]
        for rid in self._by_filter.pop(name):
            self._by_row[rid].discard(name)

    # ------------------------------------------------------------------
    # Rows
    # ------------------------------------------------------------------

    def _check_row(self, row):
        if not isinstance(row, dict):
            raise ValueError("row must be a dict")
        if any(not isinstance(key, str) for key in row):
            raise ValueError("row columns must be strings")

    def add_row(self, row_id, row):
        if row_id in self._rows:
            raise ValueError("duplicate row id: {}".format(row_id))
        self._check_row(row)

        self._rows[row_id] = row
        hits = {name for name, expr in self._filters.items() if self._eval(expr, row)}
        self._by_row[row_id] = hits
        for name in hits:
            self._by_filter[name].add(row_id)

    def update_row(self, row_id, row):
        if row_id not in self._rows:
            raise ValueError("unknown row id: {}".format(row_id))
        self._check_row(row)

        # Drop the row's old index entries.
        for name in self._by_row.pop(row_id):
            self._by_filter[name].discard(row_id)

        self._rows[row_id] = row
        hits = {name for name, expr in self._filters.items() if self._eval(expr, row)}
        self._by_row[row_id] = hits
        for name in hits:
            self._by_filter[name].add(row_id)

    def remove_row(self, row_id):
        if row_id not in self._rows:
            raise ValueError("unknown row id: {}".format(row_id))
        del self._rows[row_id]
        for name in self._by_row.pop(row_id):
            self._by_filter[name].discard(row_id)

    # ------------------------------------------------------------------
    # Queries
    # ------------------------------------------------------------------

    def rows_matching(self, name):
        if name not in self._filters:
            raise ValueError("unknown filter: {}".format(name))
        return tuple(sorted(self._by_filter[name]))

    def matching_filters(self, row_id):
        if row_id not in self._rows:
            raise ValueError("unknown row id: {}".format(row_id))
        return tuple(sorted(self._by_row[row_id]))

    def select(self, expr):
        self._validate(expr)
        return tuple(
            sorted(
                rid for rid, row in self._rows.items() if self._eval(expr, row)
            )
        )

    # ------------------------------------------------------------------
    # Counts
    # ------------------------------------------------------------------

    def row_count(self):
        return len(self._rows)

    def filter_count(self):
        return len(self._filters)


# Module-level helper so _eval can recurse without binding a classmethod
# attribute lookup on every recursive call.
def _eval_static(expr, row):
    return FilterEngine._eval(expr, row)
```

Notes on the implementation:

- **Index structure**: `_by_filter` (name → set of row ids) and `_by_row` (row id → set of names) are updated together on every mutation, so both views stay consistent after every successful operation.
- **Validation** is fully recursive (`and`/`or`/`not` sub-expressions are validated too), and happens *after* the name/duplicate checks in `add_filter`, matching the specified error precedence.
- **Evaluation** treats missing columns as `False` and catches `TypeError` only for ordering comparisons and `in` membership, exactly as specified; `==`/`!=` use plain Python equality.
- **`select`** validates the expression with the same rules, then evaluates it ad-hoc over all rows without registering anything.
- Errors use `str.format` rather than f-strings so the messages format `row_id`/`name` values (e.g. ints) correctly in every Python version.

