"""Migrate feature flag configurations from schema version 1 to version 2."""

import copy


def _validate_top_level(config, version):
    """Validate the config envelope (dict / schema_version / flags).

    Returns the flags list. Raises ValueError on any problem.
    """
    if not isinstance(config, dict):
        raise ValueError("config must be a dict")
    if config.get("schema_version") is not version:
        raise ValueError("schema_version must be %d" % version)
    if "flags" not in config or not isinstance(config["flags"], list):
        raise ValueError("flags must be a list")
    return config["flags"]


def _validate_flag_header(flag, index, seen_names):
    """Validate that a flag is a dict with a unique non-empty name.

    Returns the flag's name.
    """
    if not isinstance(flag, dict):
        raise ValueError("flags[%d] must be a dict" % index)
    name = flag.get("name")
    if not isinstance(name, str) or not name:
        raise ValueError("flags[%d] name must be a non-empty string" % index)
    if name in seen_names:
        raise ValueError("duplicate flag name: %s" % name)
    seen_names.add(name)
    return name


def validate_v1(config):
    """Validate a version 1 configuration.

    Raises ValueError with a descriptive message if the configuration is
    invalid. Returns None if the configuration is valid.
    """
    flags = _validate_top_level(config, 1)
    seen_names = set()
    for i, flag in enumerate(flags):
        _validate_flag_header(flag, i, seen_names)

        if not isinstance(flag["enabled"], bool):
            raise ValueError("flags[%d] enabled must be a boolean" % i)

        rollout = flag["rollout"]
        if isinstance(rollout, bool) or not isinstance(rollout, int) \
                or not 0 <= rollout <= 100:
            raise ValueError(
                "flags[%d] rollout must be an integer between 0 and 100" % i
            )

        if "segments" in flag:
            segments = flag["segments"]
            if not isinstance(segments, dict):
                raise ValueError("flags[%d] segments must be a dict" % i)
            for key, value in segments.items():
                if not isinstance(key, str) or not key:
                    raise ValueError(
                        "flags[%d] segments keys must be non-empty strings" % i
                    )
                if not isinstance(value, bool):
                    raise ValueError(
                        "flags[%d] segments values must be booleans" % i
                    )


def validate_v2(config):
    """Validate a version 2 configuration.

    Raises ValueError with a descriptive message if the configuration is
    invalid. Returns None if the configuration is valid.
    """
    flags = _validate_top_level(config, 2)
    seen_names = set()
    for i, flag in enumerate(flags):
        _validate_flag_header(flag, i, seen_names)

        state = flag.get("state")
        if state not in ("on", "off", "percentage"):
            raise ValueError(
                "flags[%d] state must be one of 'on', 'off', 'percentage'" % i
            )

        if state == "percentage":
            percentage = flag.get("percentage")
            if isinstance(percentage, bool) or not isinstance(percentage, int) \
                    or not 0 <= percentage <= 100:
                raise ValueError(
                    "flags[%d] percentage must be an integer "
                    "between 0 and 100" % i
                )
        elif "percentage" in flag:
            raise ValueError(
                "flags[%d] percentage must only be present "
                "when state is 'percentage'" % i
            )

        rules = flag["segment_rules"]
        if not isinstance(rules, list):
            raise ValueError("flags[%d] segment_rules must be a list" % i)
        seen_segments = set()
        for j, rule in enumerate(rules):
            if not isinstance(rule, dict):
                raise ValueError(
                    "flags[%d] segment_rules[%d] must be a dict" % (i, j)
                )
            segment = rule.get("segment")
            if not isinstance(segment, str) or not segment:
                raise ValueError(
                    "flags[%d] segment_rules[%d] segment "
                    "must be a non-empty string" % (i, j)
                )
            if rule.get("serve") not in ("on", "off"):
                raise ValueError(
                    "flags[%d] segment_rules[%d] serve must be "
                    "'on' or 'off'" % (i, j)
                )
            if segment in seen_segments:
                raise ValueError(
                    "flags[%d] duplicate segment rule: %s" % (i, segment)
                )
            seen_segments.add(segment)


def migrate_to_v2(config):
    """Validate a version 1 configuration and return it as version 2."""
    validate_v1(config)

    new_flags = []
    for flag in config["flags"]:
        new_flag = {"name": flag["name"]}

        if not flag["enabled"]:
            new_flag["state"] = "off"
        elif flag["rollout"] == 100:
            new_flag["state"] = "on"
        else:
            new_flag["state"] = "percentage"
            new_flag["percentage"] = flag["rollout"]

        segment_rules = [
            {
                "segment": segment,
                "serve": "on" if serve else "off",
            }
            for segment, serve in sorted(flag.get("segments", {}).items())
        ]
        new_flag["segment_rules"] = segment_rules

        new_flags.append(new_flag)

    return {"schema_version": 2, "flags": new_flags}


def migrate(config):
    """Migrate a configuration to version 2, whatever its current version."""
    if not isinstance(config, dict):
        raise ValueError("config must be a dict")
    version = config.get("schema_version")
    if version is 1:
        return migrate_to_v2(config)
    if version is 2:
        validate_v2(config)
        return copy.deepcopy(config)
    raise ValueError("unsupported schema_version: %r" % version)
```

A few notes on the implementation:

- **Bool vs int**: `rollout` and `percentage` use `isinstance(x, bool)` checks first, since `bool` is a subclass of `int` in Python (`True` would otherwise pass an `isinstance(x, int)` check).
- **`is` comparisons for `schema_version`**: `version is 1` correctly rejects `True` (since `True == 1` but `True is not 1`), matching the "exactly 1" requirement.
- **No mutation**: `migrate_to_v2` builds entirely new dicts/lists, and `migrate` returns `copy.deepcopy` for already-v2 configs, so mutating results never affects inputs.
- **Sorted segments**: `sorted(...items())` sorts by segment name ascending, as required.
- **Key iteration order for `segments` validation**: keys and values are checked per item in insertion order, so the earliest offending key (in dict order) triggers the error first — consistent with "processed left to right" semantics.

