                    "'on' or 'off'" % (i, j)
                )
            if segment in seen_segments:
                raise ValueError(
                    "flags[%d] duplicate segment rule: %s" % (i, segment)
                )
            seen_segments.add(segment)


def migrate_to_v2(config):
    """Validate a version 1 configuration and return it as version 2."""
    validate_v1(config)

    new_flags = []
    for flag in config["flags"]:
        new_flag = {"name": flag["name"]}

        if not flag["enabled"]:
            new_flag["state"] = "off"
        elif flag["rollout"] == 100:
            new_flag["state"] = "on"
        else:
            new_flag["state"] = "percentage"
            new_flag["percentage"] = flag["rollout"]

        segment_rules = [
            {
                "segment": segment,
                "serve": "on" if serve else "off",
            }
            for segment, serve in sorted(flag.get("segments", {}).items())
        ]
        new_flag["segment_rules"] = segment_rules

        new_flags.append(new_flag)

    return {"schema_version": 2, "flags": new_flags}


def migrate(config):
    """Migrate a configuration to version 2, whatever its current version."""
    if not isinstance(config, dict):
        raise ValueError("config must be a dict")
    version = config.get("schema_version")
    if _is_exact_int(version, 1):
        return migrate_to_v2(config)
    if _is_exact_int(version, 2):
        validate_v2(config)
        return copy.deepcopy(config)
    raise ValueError("unsupported schema_version: %r" % version)
```

Summary of the fixes:

1. **`KeyError: 'rollout'`** — a missing key must produce the proper `ValueError` message, not a `KeyError`. Changed `flag["rollout"]`, `flag["enabled"]`, and `flag["segment_rules"]` to `.get(...)` accesses so that a missing value fails the subsequent `isinstance` check and raises the correct `ValueError` (e.g. `flags[0] rollout must be an integer between 0 and 100`).

2. **`SyntaxWarning: "is" with a literal`** — replaced the `version is 1` / `version is 2` identity checks with a small helper `_is_exact_int(value, expected)`, which requires the value to be a real `int` (rejecting `bool`, since `True == 1`) equal to the expected version. This keeps the exact-version semantics (e.g. `True` is not accepted as version 1) while eliminating the warnings and being robust across Python versions, where `is` on small ints is an implementation detail rather than a guarantee.

Both bugs are small, one-line fixes:

**Bug 1 (half-up rounding):** In `_add_line`, `.quantize(_TWO_PLACES)` is called without a rounding argument, so it uses the decimal context's default `ROUND_HALF_EVEN`. That makes `0.005` round to `0.00` (banker's rounding) instead of `0.01`. `ROUND_HALF_UP` is imported but never used. The fix is to pass `rounding=ROUND_HALF_UP` to `quantize`.

**Bug 2 (sign of net VAT due):** `net_vat_due()` computes `input_vat() - output_vat()`, but the spec says it should be `output_vat() - input_vat()`. That's why your signs are flipped in both `net_vat_due()` and `box_summary()`.

