```python
import re
from decimal import Decimal, ROUND_HALF_UP

_TWO_PLACES = Decimal("0.01")


class VatReturn:
    """Accumulates VAT-rated sales and purchase lines for one period."""

    ALLOWED_RATES = ("0", "5", "20")

    # A fully valid net amount: digits, optionally a point and 1-2 digits.
    _VALID_NET = re.compile(r"^\d+(\.\d{1,2})?$")
    # A "plain number" (used to detect a negative amount): digits,
    # optionally a point and any number of digits.
    _PLAIN_NUMBER = re.compile(r"^\d+(\.\d+)?$")
    # A plain number with three or more fractional digits.
    _TOO_MANY_DECIMALS = re.compile(r"^\d+\.\d{3,}$")

    def __init__(self, period_label):
        if not isinstance(period_label, str):
            raise TypeError("period label must be a string")
        if not period_label.strip():
            raise ValueError("period label must not be empty")

        self._period_label = period_label
        self._finalized = False
        self._sales = []       # list of (net Decimal, rate str, vat Decimal)
        self._purchases = []

    # ------------------------------------------------------------------
    # Internal helpers
    # ------------------------------------------------------------------

    def _validate_net(self, net):
        if not isinstance(net, str):
            raise TypeError("net amount must be given as a string")

        if net.startswith("-"):
            rest = net[1:]
            if self._PLAIN_NUMBER.match(rest):
                raise ValueError("net amount must not be negative")

        if self._TOO_MANY_DECIMALS.match(net):
            raise ValueError("net amount must have at most two decimal places")

        if not self._VALID_NET.match(net):
            raise ValueError("net amount must be a decimal number")

        return Decimal(net)

    def _validate_rate(self, vat_rate):
        if not isinstance(vat_rate, str):
            raise TypeError("vat rate must be given as a string")
        if vat_rate not in self.ALLOWED_RATES:
            raise ValueError("vat rate must be one of: 0, 5, 20")
        return vat_rate

    def _add_line(self, lines, net, vat_rate):
        if self._finalized:
            raise RuntimeError("return is already finalized")

        net_value = self._validate_net(net)
        rate = self._validate_rate(vat_rate)

        vat = (net_value * (Decimal(rate) / Decimal(100))).quantize(
            _TWO_PLACES, rounding=ROUND_HALF_UP
        )
        lines.append((net_value, rate, vat))

    # ------------------------------------------------------------------
    # Recording lines
    # ------------------------------------------------------------------

    def add_sale(self, net, vat_rate):
        self._add_line(self._sales, net, vat_rate)

    def add_purchase(self, net, vat_rate):
        self._add_line(self._purchases, net, vat_rate)

    # ------------------------------------------------------------------
    # Read methods
    # ------------------------------------------------------------------

    def output_vat(self):
        total = sum((line[2] for line in self._sales), Decimal("0.00"))
        return total.quantize(_TWO_PLACES)

    def input_vat(self):
        total = sum((line[2] for line in self._purchases), Decimal("0.00"))
        return total.quantize(_TWO_PLACES)

    def net_vat_due(self):
        return (self.output_vat() - self.input_vat()).quantize(_TWO_PLACES)

    def total_net_sales(self):
        total = sum((line[0] for line in self._sales), Decimal("0.00"))
        return total.quantize(_TWO_PLACES)

    def total_net_purchases(self):
        total = sum((line[0] for line in self._purchases), Decimal("0.00"))
        return total.quantize(_TWO_PLACES)

    def _by_rate(self, lines):
        result = {rate: Decimal("0.00") for rate in self.ALLOWED_RATES}
        for net_value, rate, _vat in lines:
            result[rate] += net_value
        return {rate: total.quantize(_TWO_PLACES) for rate, total in result.items()}

    def sales_by_rate(self):
        return self._by_rate(self._sales)

    def purchases_by_rate(self):
        return self._by_rate(self._purchases)

    def box_summary(self):
        return {
            "period": self._period_label,
            "net_sales": self.total_net_sales(),
            "net_purchases": self.total_net_purchases(),
            "output_vat": self.output_vat(),
            "input_vat": self.input_vat(),
            "net_vat_due": self.net_vat_due(),
        }

    def finalize(self):
        self._finalized = True
        return self.box_summary()
```

Verification against your failing cases:

- `add_sale("0.10", "5")` → per-line VAT `0.005` now rounds **half-up** to `Decimal("0.01")`; `"0.02"` at `"5"` still gives `0.00`. Same for purchases.
- Sale `"100.00"` at `"20"` (output 20.00) minus purchase `"40.00"` at `"20"` (input 8.00) → `net_vat_due()` = `Decimal("12.00")`.
- Repayment case: output 20.00 − input 25.00 → `Decimal("-5.00")`.

One note on why bug 1 is subtle: per-line VAT values like `0.005` are exact `Decimal`s, so the rounding mode really is the only thing deciding `0.00` vs `0.01` — there's no float fuzz to "rescue" the result. The default context rounding is `ROUND_HALF_EVEN`, which rounds exact halves toward the even last digit (0), while the spec requires `ROUND_HALF_UP`. All the other `quantize` calls (on totals) are safe either way since the values being quantized already have ≤ 2 decimal places, but I left them as-is since they're correct.

The bug is in `render_report`, in the top-level tracking:

```python
if top_level is None or level >= top_level:
```

Using `>=` means a later save with an *equal* level replaces the current leader, but the spec says on a tie the **earliest** save in the list wins. It must be a strict `>`:

```python
if top_level is None or level > top_level:
```

With `>=`, Bob (level 5, save #2) overwrites Alice (level 5, save #1), producing `TOP LEVEL: Bob (5)` instead of `TOP LEVEL: Alice (5)`.

