    """Validate save and migrate it to CURRENT_VERSION.

    Returns a brand-new dict; the input is never mutated.
    """
    validate(save)
    current = save
    if current["version"] == 1:
        current = _migrate_v1_to_v2(current)
    if current["version"] == 2:
        current = _migrate_v2_to_v3(current)
    # Build a fresh version 3 dict (deep copy for already-v3 inputs too).
    return {
        "version": CURRENT_VERSION,
        "player": current["player"],
        "health": current["health"],
        "wealth": dict(current["wealth"]),
        "level": current["level"],
        "position": dict(current["position"]),
    }


def _canonical(value):
    if value is None:
        return "n:none"
    if value is True:
        return "b:true"
    if value is False:
        return "b:false"
    if isinstance(value, int):
        return "i:{}".format(value)
    if isinstance(value, str):
        return "s:{}".format(value)
    if isinstance(value, (list, tuple)):
        return "[" + ",".join(_canonical(item) for item in value) + "]"
    if isinstance(value, dict):
        parts = ["{}={}".format(_canonical(k), _canonical(v))
                 for k in sorted(value) for v in [value[k]]]
        return "{" + ",".join(parts) + "}"
    raise ValueError("cannot canonicalize value of type {}".format(_type_name(value)))


def fingerprint(save):
    """Return the four lowercase hex digit fingerprint of a version 3 save."""
    validate(save)
    if save["version"] != CURRENT_VERSION:
        raise ValueError(
            "fingerprint requires version 3, got version {}".format(save["version"]))
    text = _canonical(save)
    total = sum(ord(ch) for ch in text) % 65536
    return format(total, "04x")


def render_report(saves):
    """Render the exact text report for a list of save files."""
    if not isinstance(saves, list):
        raise ValueError("saves must be a list, got {}".format(_type_name(saves)))

    lines = ["=== DUNGEON DEPTHS SAVE REPORT ===", "Saves: {}".format(len(saves))]

    players = []
    total_coins = 0
    total_gems = 0
    top_level = None
    top_name = None

    for index, save in enumerate(saves, 1):
        validate(save)
        source_version = save["version"]
        migrated = migrate(save)

        if source_version == 1:
            migrations = "v1->v2, v2->v3"
        elif source_version == 2:
            migrations = "v2->v3"
        else:
            migrations = "none"

        player = migrated["player"]
        health = migrated["health"]
        level = migrated["level"]
        purse = migrated["wealth"]["purse"]
        gems = migrated["wealth"]["gems"]
        room = migrated["position"]["room"]
        checksum = (health + 2 * level + 3 * purse + 5 * gems) % 97

        lines.append("-" * 34)
        lines.append("SAVE #{}".format(index))
        lines.append("Player: {}".format(player))
        lines.append("Source version: {}".format(source_version))
        lines.append("Target version: {}".format(CURRENT_VERSION))
        lines.append("Migrations: {}".format(migrations))
        lines.append("Health: {}".format(health))
        lines.append("Level: {}".format(level))
        lines.append("Coins: {}".format(purse))
        lines.append("Gems: {}".format(gems))
        lines.append("Room: {}".format(room))
        lines.append("Checksum: {:02d}".format(checksum))

        if player not in players:
            players.append(player)
        total_coins += purse
        total_gems += gems
        if top_level is None or level > top_level:
            top_level = level
            top_name = player

    lines.append("=" * 34)
    lines.append("PLAYERS: {}".format(", ".join(players) if players else "none"))
    lines.append("TOTAL COINS: {}".format(total_coins))
    lines.append("TOTAL GEMS: {}".format(total_gems))
    if top_level is None:
        lines.append("TOP LEVEL: none")
    else:
        lines.append("TOP LEVEL: {} ({})".format(top_name, top_level))

    return "\n".join(lines)
```

