storage_quotas_simulator.py
```python
class QuotaExceededError(Exception):
    """Raised when an operation would push usage past a quota."""


class QuotaManager:
    """Simulates per-user and per-group storage quota accounting."""

    def __init__(self) -> None:
        # group name -> quota (int)
        self._groups = {}
        # user name -> {"group": str, "quota": int}
        self._users = {}
        # user name -> {filename: size}
        self._files = {}
        # cached usage sums for O(1) queries
        self._user_usage = {}
        self._group_usage = {}
        self._total_usage = 0

    def add_group(self, name: str, quota_bytes: int) -> None:
        if name in self._groups:
            raise ValueError(f"group already exists: {name}")
        if quota_bytes < 0:
            raise ValueError("quota must be non-negative")
        self._groups[name] = quota_bytes
        self._group_usage[name] = 0

    def add_user(self, name: str, group: str, quota_bytes: int) -> None:
        if group not in self._groups:
            raise ValueError(f"unknown group: {group}")
        if name in self._users:
            raise ValueError(f"user already exists: {name}")
        if quota_bytes < 0:
            raise ValueError("quota must be non-negative")
        self._users[name] = {"group": group, "quota": quota_bytes}
        self._files[name] = {}
        self._user_usage[name] = 0

    def store(self, user: str, filename: str, size: int) -> None:
        if user not in self._users:
            raise ValueError(f"unknown user: {user}")
        if filename in self._files[user]:
            raise ValueError(f"file already exists: {user}/{filename}")
        if size <= 0:
            raise ValueError("size must be positive")
        group = self._users[user]["group"]
        if self._user_usage[user] + size > self._users[user]["quota"]:
            raise QuotaExceededError(f"user quota exceeded for {user}")
        if self._group_usage[group] + size > self._groups[group]:
            raise QuotaExceededError(f"group quota exceeded for {group}")
        # All checks passed; commit.
        self._files[user][filename] = size
        self._user_usage[user] += size
        self._group_usage[group] += size
        self._total_usage += size

    def delete(self, user: str, filename: str) -> None:
        if user not in self._users:
            raise ValueError(f"unknown user: {user}")
        if filename not in self._files[user]:
            raise ValueError(f"no such file: {user}/{filename}")
        size = self._files[user].pop(filename)
        group = self._users[user]["group"]
        self._user_usage[user] -= size
        self._group_usage[group] -= size
        self._total_usage -= size

    def user_usage(self, user: str) -> int:
        if user not in self._users:
            raise ValueError(f"unknown user: {user}")
        return self._user_usage[user]

    def group_usage(self, group: str) -> int:
        if group not in self._groups:
            raise ValueError(f"unknown group: {group}")
        return self._group_usage[group]

    def total_usage(self) -> int:
        return self._total_usage

    def move_user(self, user: str, new_group: str) -> None:
        if user not in self._users:
            raise ValueError(f"unknown user: {user}")
        if new_group not in self._groups:
            raise ValueError(f"unknown group: {new_group}")
        old_group = self._users[user]["group"]
        if old_group == new_group:
            return
        usage = self._user_usage[user]
        if self._group_usage[new_group] + usage > self._groups[new_group]:
            raise QuotaExceededError(f"group quota exceeded for {new_group}")
        self._group_usage[old_group] -= usage
        self._group_usage[new_group] += usage
        self._users[user]["group"] = new_group

    def resize_user_quota(self, user: str, new_quota: int) -> None:
        if user not in self._users:
            raise ValueError(f"unknown user: {user}")
        if new_quota < 0:
            raise ValueError("quota must be non-negative")
        self._users[user]["quota"] = new_quota
```

A few notes on the design:

- **Usage is cached, not recomputed** — `_user_usage`, `_group_usage`, and `_total_usage` are updated incrementally on `store`/`delete`/`move_user`, so all the query methods are O(1). If you preferred, `user_usage` could sum `self._files[user].values()` instead, but the cached version keeps `store`'s quota checks cheap too.
- **Check order matters** — each method performs its validations in exactly the order specified, and mutations only happen after all checks pass, so a failed call never leaves partial state behind.
- **`move_user`** only touches group usage counters and the user's group assignment; total usage and the user's own quota are unaffected, per the spec.
- **`resize_user_quota`** allows shrinking below current usage — the spec says that's fine, and any later `store` will fail naturally at the user-quota check until usage drops via deletions.

