"""Migrate restaurant orders between the three kitchen order formats."""

import re

STATIONS = ("grill", "fry", "pizza", "cold", "pastry")
COURSES = ("starter", "main", "dessert")

_EXACT_ROUTES = {
    "garlic bread": "pizza",
    "steak pie": "pastry",
    "wings": "fry",
}

# Substring keywords, checked in this exact order; first match wins.
_KEYWORD_ROUTES = (
    ("pizza", "pizza"),
    ("fries", "fry"),
    ("fried", "fry"),
    ("salad", "cold"),
    ("tartare", "cold"),
    ("carpaccio", "cold"),
    ("steak", "grill"),
    ("grilled", "grill"),
    ("burger", "grill"),
    ("cake", "pastry"),
    ("pie", "pastry"),
    ("tart", "pastry"),
    ("sundae", "pastry"),
)

_EXACT_COURSES = {
    "garlic bread": "starter",
    "wings": "starter",
}
_STARTER_KEYWORDS = ("salad", "bread", "soup", "tartare", "carpaccio")
_DESSERT_KEYWORDS = ("cake", "pie", "tart", "sundae", "ice cream", "fondant")


def route_dish(dish):
    """Return the kitchen station a dish is automatically routed to.

    Raise ValueError when no route can be derived from the dish name.
    """
    if dish in _EXACT_ROUTES:
        return _EXACT_ROUTES[dish]
    for keyword, station in _KEYWORD_ROUTES:
        if keyword in dish:
            return station
    raise ValueError("no route for dish '%s'" % (dish,))


def course_for(dish):
    """Return the course ('starter', 'main' or 'dessert') a dish belongs to."""
    if dish in _EXACT_COURSES:
        return _EXACT_COURSES[dish]
    for keyword in _STARTER_KEYWORDS:
        if keyword in dish:
            return "starter"
    for keyword in _DESSERT_KEYWORDS:
        if keyword in dish:
            return "dessert"
    return "main"


# ---------------------------------------------------------------------------
# Validation helpers
# ---------------------------------------------------------------------------

def _validate_base(order, version, allowed_keys):
    """Shared checks: dict-ness, unknown keys, ticket, table, server."""
    if not isinstance(order, dict):
        raise ValueError("order must be a dict")
    for key in order:
        if key not in allowed_keys:
            raise ValueError("%s order has unknown field '%s'" % (version, key))
    for field in ("ticket", "table", "server"):
        if field not in order:
            raise ValueError("%s order missing field '%s'" % (version, field))
    ticket = order["ticket"]
    if isinstance(ticket, bool) or not isinstance(ticket, int) or ticket <= 0:
        raise ValueError("field 'ticket' must be a positive integer")
    table = order["table"]
    if isinstance(table, bool) or not isinstance(table, int) or not 1 <= table <= 99:
        raise ValueError("field 'table' must be an integer between 1 and 99")
    server = order["server"]
    if not isinstance(server, str) or re.fullmatch(r"[a-z]+", server) is None:
