fn is_blank(s: &str) -> bool {
    s.trim().is_empty()
}

fn is_ascii_letter(c: char) -> bool {
    c.is_ascii_alphabetic()
}

fn is_key_body(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

/// A rule name or label/silence key: 1..=64 chars, first an ASCII letter,
/// the rest ASCII letters, digits or underscores.
fn is_valid_key(s: &str) -> bool {
    let mut chars = s.chars();
    match chars.next() {
        Some(c) if is_ascii_letter(c) => {}
        _ => return false,
    }
    if s.chars().count() > 64 {
        return false;
    }
    chars.all(is_key_body)
}

/// A metric name: 1..=100 chars, first an ASCII letter, the rest ASCII
/// letters, digits, underscores or dots.
fn is_valid_metric(s: &str) -> bool {
    let mut chars = s.chars();
    match chars.next() {
        Some(c) if is_ascii_letter(c) => {}
        _ => return false,
    }
    if s.chars().count() > 100 {
        return false;
    }
    chars.all(|c| is_key_body(c) || c == '.')
}

