/// Validates `rules` against `config`, returning every problem found,
/// in the deterministic order specified in the task description.
pub fn validate(rules: &[Rule], config: &Config) -> Vec<Problem> {
    let mut problems: Vec<Problem> = Vec::new();
    let mut seen_names: Vec<String> = Vec::new();

    for rule in rules {
        // Group 1: rule name.
        if is_blank(&rule.name) {
            push(
                &mut problems,
                &rule.name,
                ProblemCode::EmptyRuleName,
                "rule name is blank".to_string(),
            );
        } else if !is_valid_key(&rule.name) {
            push(
                &mut problems,
                &rule.name,
                ProblemCode::InvalidRuleName,
                format!("rule name {:?} does not match the required pattern", rule.name),
            );
        } else if seen_names.iter().any(|n| n == &rule.name) {
            push(
                &mut problems,
                &rule.name,
                ProblemCode::DuplicateRuleName,
                format!("rule name {:?} is used more than once", rule.name),
            );
        }
        if !is_blank(&rule.name) {
            seen_names.push(rule.name.clone());
        }

        // Group 2: metric.
        let metric_ok = if is_blank(&rule.metric) {
            push(
                &mut problems,
                &rule.name,
                ProblemCode::EmptyMetric,
                "metric name is blank".to_string(),
            );
            false
        } else if !is_valid_metric(&rule.metric) {
            push(
                &mut problems,
                &rule.name,
                ProblemCode::InvalidMetric,
                format!("metric name {:?} does not match the required pattern", rule.metric),
            );
            false
        } else {
            true
        };

        // Group 3: comparison.
        if rule.comparison == Comparison::Equal {
            push(
                &mut problems,
                &rule.name,
                ProblemCode::UnsupportedComparison,
                "the Equal comparison is not supported".to_string(),
            );
        }

        // Group 4: threshold finiteness.
        let threshold_finite = if rule.threshold.is_nan() || rule.threshold.is_infinite() {
            push(
                &mut problems,
                &rule.name,
                ProblemCode::NonFiniteThreshold,
                "threshold must be a finite number".to_string(),
            );
            false
        } else {
            true
        };

        // Group 5: threshold range (only if metric valid and threshold finite).
        if metric_ok && threshold_finite {
            let max = if rule.metric.ends_with("_ratio") {
                Some(1.0f64)
            } else if rule.metric.ends_with("_percent") {
                Some(100.0f64)
            } else {
                None
            };
            if let Some(max) = max {
                if !(0.0..=max).contains(&rule.threshold) {
                    push(
                        &mut problems,
                        &rule.name,
                        ProblemCode::ThresholdOutOfRange,
                        format!(
                            "threshold {} is out of the allowed range 0..={}",
                            rule.threshold, max
                        ),
                    );
                }
            }
        }

        // Group 6: labels.
        let mut seen_label_keys: Vec<&str> = Vec::new();
        for (key, _value) in &rule.labels {
            if is_blank(key) {
                push(
                    &mut problems,
                    &rule.name,
                    ProblemCode::EmptyLabelKey,
                    "label key is blank".to_string(),
                );
            } else if !is_valid_key(key) {
                push(
                    &mut problems,
                    &rule.name,
                    ProblemCode::InvalidLabelKey,
                    format!("label key {:?} does not match the required pattern", key),
                );
            } else if seen_label_keys.contains(&key.as_str()) {
                push(
                    &mut problems,
                    &rule.name,
                    ProblemCode::DuplicateLabelKey,
                    format!("label key {:?} appears more than once", key),
                );
            } else {
                seen_label_keys.push(key.as_str());
            }
        }

        // Group 7: duration.
        if rule.duration_secs < config.min_duration_secs {
            push(
                &mut problems,
                &rule.name,
                ProblemCode::DurationTooShort,
                format!(
                    "duration {}s is shorter than the minimum of {}s",
                    rule.duration_secs, config.min_duration_secs
                ),
            );
        }
        if rule.duration_secs > config.max_duration_secs {
            push(
                &mut problems,
                &rule.name,
                ProblemCode::DurationTooLong,
                format!(
                    "duration {}s is longer than the maximum of {}s",
                    rule.duration_secs, config.max_duration_secs
                ),
            );
        }
        if config.evaluation_interval_secs > 0
            && rule.duration_secs % config.evaluation_interval_secs != 0
        {
            push(
                &mut problems,
                &rule.name,
                ProblemCode::DurationNotMultipleOfInterval,
                format!(
                    "duration {}s is not a multiple of the evaluation interval {}s",
                    rule.duration_secs, config.evaluation_interval_secs
                ),
            );
        }

        // Group 8: per-silence checks.
        for silence in &rule.silences {
            // Key part.
            let key_valid = if is_blank(&silence.label_key) {
                push(
                    &mut problems,
                    &rule.name,
                    ProblemCode::EmptySilenceKey,
                    "silence label key is blank".to_string(),
                );
                false
            } else if !is_valid_key(&silence.label_key) {
                push(
                    &mut problems,
                    &rule.name,
                    ProblemCode::InvalidSilenceKey,
                    format!(
                        "silence label key {:?} does not match the required pattern",
                        silence.label_key
                    ),
                );
                false
            } else {
                true
            };
            if key_valid {
                match rule
                    .labels
                    .iter()
                    .find(|(k, _)| k == &silence.label_key)
                {
                    None => {
                        push(
                            &mut problems,
                            &rule.name,
                            ProblemCode::SilenceUnknownLabel,
                            format!(
                                "silence refers to unknown label key {:?}",
                                silence.label_key
                            ),
                        );
                    }
                    Some((_, value)) => {
                        if value != &silence.label_value {
                            push(
                                &mut problems,
                                &rule.name,
                                ProblemCode::SilenceValueMismatch,
                                format!(
                                    "silence value {:?} does not match label value {:?}",
                                    silence.label_value, value
                                ),
                            );
                        }
                    }
                }
            }

            // Window part.
            let non_inverted = silence.end_secs > silence.start_secs;
            if !non_inverted {
                push(
                    &mut problems,
                    &rule.name,
                    ProblemCode::SilenceWindowInverted,
                    format!(
                        "silence window [{}, {}) is inverted or empty",
                        silence.start_secs, silence.end_secs
                    ),
                );
            } else if silence.end_secs - silence.start_secs > config.max_silence_secs {
                push(
                    &mut problems,
                    &rule.name,
                    ProblemCode::SilenceTooLong,
                    format!(
                        "silence window of {}s exceeds the maximum of {}s",
                        silence.end_secs - silence.start_secs,
                        config.max_silence_secs
                    ),
                );
            }
        }

        // Group 9: silence pairs (increasing j, then increasing i).
        let n = rule.silences.len();
        for j in 1..n {
            for i in 0..j {
                let a = &rule.silences[i];
                let b = &rule.silences[j];
                if !is_valid_key(&a.label_key) || !is_valid_key(&b.label_key) {
                    continue;
                }
                if a.label_key != b.label_key || a.label_value != b.label_value {
                    continue;
                }
                if !(a.end_secs > a.start_secs) || !(b.end_secs > b.start_secs) {
                    continue;
                }
                let a_contains_b = a.start_secs <= b.start_secs && b.end_secs <= a.end_secs;
                let b_contains_a = b.start_secs <= a.start_secs && a.end_secs <= b.end_secs;
                if a_contains_b || b_contains_a {
                    push(
                        &mut problems,
                        &rule.name,
                        ProblemCode::RedundantSilence,
                        format!(
                            "silences {} and {} are redundant (one contains the other)",
                            i, j
                        ),
                    );
                } else if a.start_secs < b.end_secs && b.start_secs < a.end_secs {
                    push(
                        &mut problems,
                        &rule.name,
                        ProblemCode::OverlappingSilence,
                        format!("silences {} and {} overlap", i, j),
                    );
                }
            }
        }
    }

    problems
}
```

A few implementation notes:

- **Group order & independence**: every group appends its problems even if earlier groups fired — the only stated exceptions are respected: group 5 is skipped when the threshold is non-finite (group 4) or the metric check (group 2) failed, and a silence's label lookup is skipped on a blank/invalid key.
- **Duplicate name registration**: non-blank names are registered immediately after their own check, so a second rule with an invalid-but-nonblank name still gets `DuplicateRuleName` if it matches.
- **Length checks** use `chars().count()` so multi-byte characters can't sneak past the 64/100 limits.
- **Pair iteration** is `j` outer, `i` inner (`0..j`), matching "increasing `j`, then increasing `i`".
- It never panics: all indexing is bounds-safe and there is no arithmetic that can overflow (the subtraction `end - start` only happens when `end > start`).

