/// Everything that can go wrong while migrating a TripLedger export.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MigrationError {
    /// The first significant line was not `v1` or `v2`.
    UnknownHeader(String),
    /// The line after the header was not a members line.
    MissingMembersLine,
    /// A second `members:` line was found.
    DuplicateMembersLine { line_number: usize },
    /// The members list was empty.
    NoMembers,
    /// A member name did not match the naming rules.
    InvalidMemberName { line_number: usize, name: String },
    /// The same member appeared twice in the members list.
    DuplicateMember { line_number: usize, name: String },
    /// A `*weight` suffix in v2 was not a positive integer.
    InvalidWeight { line_number: usize, name: String, weight: String },
    /// A line was not recognisable, or an expense line had bad structure.
    MalformedLine { line_number: usize, content: String },
    /// The amount field was not a non-negative integer.
    InvalidAmount { line_number: usize, amount: String },
    /// The payer or a participant is not a member of the group.
    UnknownMember { line_number: usize, name: String },
    /// A share in a shares section was not a positive integer.
    InvalidShare { line_number: usize, name: String, share: String },
    /// The same participant appeared twice in one shares section.
    DuplicateParticipant { line_number: usize, name: String },
    /// A v1 document used the v2-only `|` shares syntax.
    SharesNotAllowed { line_number: usize },
}

struct Member {
    name: String,
    weight: u32,
}

struct ParsedExpense {
    payer: usize,
    amount: u64,
    description: String,
    /// (member index, cents) sorted by member name.
    allocations: Vec<(usize, u64)>,
}

/// A valid name is 1..=24 chars, starts with an ASCII lowercase letter,
/// and contains only ASCII lowercase letters, digits, or `_`.
fn is_valid_name(name: &str) -> bool {
    let bytes = name.as_bytes();
    if bytes.is_empty() || bytes.len() > 24 {
        return false;
    }
    if !bytes[0].is_ascii_lowercase() {
        return false;
    }
    bytes
        .iter()
        .all(|&b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'_')
}

/// Index of the entry with the largest amount; ties broken by the
/// lexicographically smallest member name.
fn pick_largest(list: &[(usize, i128)], members: &[Member]) -> usize {
    let mut best = 0usize;
    for i in 1..list.len() {
        let best_amt = list[best].1;
        let (idx, amt) = list[i];
        if amt > best_amt || (amt == best_amt && members[idx].name < members[list[best].0].name) {
            best = i;
        }
    }
    best
}

/// Upgrades a TripLedger v1 or v2 export to the v3 format.
pub fn migrate(input: &str) -> Result<String, MigrationError> {
    // Collect significant lines with their 1-based line numbers.
    let significant: Vec<(usize, &str)> = input
        .split('\n')
        .enumerate()
        .map(|(i, raw)| (i + 1, raw.trim()))
        .filter(|(_, line)| !line.is_empty())
        .collect();

    // Header.
    let &(header_line_number, header) = significant
        .first()
        .ok_or_else(|| MigrationError::UnknownHeader(String::new()))?;
    let _ = header_line_number;
    let version: u8 = match header {
        "v1" => 1,
        "v2" => 2,
        other => return Err(MigrationError::UnknownHeader(other.to_string())),
    };

    // Members line.
    let &(members_line_number, members_line) =
        significant.get(1).ok_or(MigrationError::MissingMembersLine)?;
    if !members_line.starts_with("members:") {
        return Err(MigrationError::MissingMembersLine);
    }

    let mut members: Vec<Member> = Vec::new();
    let members_body = members_line["members:".len()..].trim();
    if members_body.is_empty() {
        return Err(MigrationError::NoMembers);
    }
    for piece in members_body.split(',') {
        let piece = piece.trim();
        let (name, weight) = if version == 2 {
            match piece.find('*') {
                Some(pos) => {
                    let name = piece[..pos].trim();
                    let weight_text = piece[pos + 1..].trim();
                    match weight_text.parse::<u32>() {
                        Ok(w) if w >= 1 => (name, w),
                        _ => {
                            return Err(MigrationError::InvalidWeight {
                                line_number: members_line_number,
                                name: name.to_string(),
                                weight: weight_text.to_string(),
                            })
                        }
                    }
                }
                None => (piece, 1),
            }
        } else {
            // v1 has no weight syntax: the whole piece is the name.
            (piece, 1)
        };
        if !is_valid_name(name) {
            return Err(MigrationError::InvalidMemberName {
                line_number: members_line_number,
                name: name.to_string(),
            });
        }
        if members.iter().any(|m| m.name == name) {
            return Err(MigrationError::DuplicateMember {
                line_number: members_line_number,
                name: name.to_string(),
            });
        }
        members.push(Member {
            name: name.to_string(),
            weight,
        });
    }

    // Expense lines.
    let mut expenses: Vec<ParsedExpense> = Vec::new();
    let mut nets: Vec<i128> = vec![0; members.len()];

    for &(line_number, line) in &significant[2..] {
        if line.starts_with("members:") {
            return Err(MigrationError::DuplicateMembersLine { line_number });
        }
        if !line.starts_with("expense:") {
            return Err(MigrationError::MalformedLine {
                line_number,
                content: line.to_string(),
            });
        }

        let body = &line["expense:".len()..];
        let (main, shares_section) = match body.find('|') {
            Some(pos) => {
                if version == 1 {
                    return Err(MigrationError::SharesNotAllowed { line_number });
                }
                (&body[..pos], Some(&body[pos + 1..]))
            }
            None => (body, None),
        };

        let fields: Vec<&str> = main.split(';').collect();
        if fields.len() != 3 {
            return Err(MigrationError::MalformedLine {
                line_number,
                content: line.to_string(),
            });
        }
        let payer_text = fields[0].trim();
        let amount_text = fields[1].trim();
        let description = fields[2].trim();

        let payer = match members.iter().position(|m| m.name == payer_text) {
            Some(i) => i,
            None => {
                return Err(MigrationError::UnknownMember {
                    line_number,
                    name: payer_text.to_string(),
                })
            }
        };

        // Digits only, no sign, no separators.
        let amount = if !amount_text.is_empty() && amount_text.bytes().all(|b| b.is_ascii_digit())
        {
            match amount_text.parse::<u64>() {
                Ok(a) => a,
                Err(_) => {
                    return Err(MigrationError::InvalidAmount {
                        line_number,
                        amount: amount_text.to_string(),
                    })
                }
            }
        } else {
            return Err(MigrationError::InvalidAmount {
                line_number,
                amount: amount_text.to_string(),
            });
        };

        if description.is_empty() {
            return Err(MigrationError::MalformedLine {
                line_number,
                content: line.to_string(),
            });
        }

        // Participants as (member index, share).
        let mut participants: Vec<(usize, u32)> = Vec::new();
        match shares_section {
            None => {
                for (i, m) in members.iter().enumerate() {
                    participants.push((i, m.weight));
                }
            }
            Some(section) => {
                let section = section.trim();
                if section.is_empty() {
                    return Err(MigrationError::MalformedLine {
                        line_number,
                        content: line.to_string(),
                    });
                }
                for piece in section.split(',') {
                    let piece = piece.trim();
                    let colon = match piece.find(':') {
                        Some(c) => c,
                        None => {
                            return Err(MigrationError::MalformedLine {
                                line_number,
                                content: line.to_string(),
                            })
                        }
                    };
                    let name = piece[..colon].trim();
                    let share_text = piece[colon + 1..].trim();
                    let idx = match members.iter().position(|m| m.name == name) {
                        Some(i) => i,
                        None => {
                            return Err(MigrationError::UnknownMember {
                                line_number,
                                name: name.to_string(),
                            })
                        }
                    };
                    if participants.iter().any(|(i, _)| *i == idx) {
                        return Err(MigrationError::DuplicateParticipant {
                            line_number,
                            name: name.to_string(),
                        });
                    }
                    let share = match share_text.parse::<u32>() {
                        Ok(s) if s >= 1 => s,
                        _ => {
                            return Err(MigrationError::InvalidShare {
                                line_number,
                                name: name.to_string(),
                                share: share_text.to_string(),
                            })
                        }
                    };
                    participants.push((idx, share));
                }
            }
        }

        // Split the amount across the participants.
        let total: u128 = participants.iter().map(|&(_, s)| s as u128).sum();
        let mut allocations: Vec<(usize, u64)> = participants
            .iter()
            .map(|&(i, s)| (i, ((amount as u128 * s as u128) / total) as u64))
            .collect();
        allocations.sort_by(|a, b| members[a.0].name.cmp(&members[b.0].name));

        let bases_sum: u64 = allocations.iter().map(|&(_, a)| a).sum();
        let mut remainder = amount - bases_sum;
        let mut cursor = 0usize;
        while remainder > 0 {
            allocations[cursor % allocations.len()].1 += 1;
            remainder -= 1;
            cursor += 1;
        }

        nets[payer] += amount as i128;
        for &(i, cents) in &allocations {
            nets[i] -= cents as i128;
        }

        expenses.push(ParsedExpense {
            payer,
            amount,
            description: description.to_string(),
            allocations,
        });
    }

    // Settlement plan.
    let mut debtors: Vec<(usize, i128)> = nets
        .iter()
        .enumerate()
        .filter_map(|(i, &n)| if n < 0 { Some((i, -n)) } else { None })
        .collect();
    let mut creditors: Vec<(usize, i128)> = nets
        .iter()
        .enumerate()
        .filter_map(|(i, &n)| if n > 0 { Some((i, n)) } else { None })
        .collect();

    let mut settlements: Vec<(usize, usize, i128)> = Vec::new();
    while !debtors.is_empty() && !creditors.is_empty() {
        let di = pick_largest(&debtors, &members);
        let ci = pick_largest(&creditors, &members);
        let transfer = debtors[di].1.min(creditors[ci].1);
        settlements.push((debtors[di].0, creditors[ci].0, transfer));
        debtors[di].1 -= transfer;
        creditors[ci].1 -= transfer;
        if debtors[di].1 == 0 {
            debtors.remove(di);
        }
        if creditors[ci].1 == 0 {
            creditors.remove(ci);
        }
    }

    // Build the v3 output.
    let mut out_lines: Vec<String> = vec!["v3".to_string()];

    let member_strings: Vec<String> = members
        .iter()
        .map(|m| {
            if m.weight == 1 {
                m.name.clone()
            } else {
                format!("{}*{}", m.name, m.weight)
            }
        })
        .collect();
    out_lines.push(format!("members: {}", member_strings.join(", ")));

    for e in &expenses {
        let alloc_strings: Vec<String> = e
            .allocations
            .iter()
            .map(|&(i, cents)| format!("{}={}", members[i].name, cents))
            .collect();
        out_lines.push(format!(
            "expense: {}; {}; {} | {}",
            members[e.payer].name,
            e.amount,
            e.description,
            alloc_strings.join(", ")
        ));
    }

    let mut balance_order: Vec<usize> = (0..members.len()).collect();
    balance_order.sort_by(|&a, &b| members[a].name.cmp(&members[b].name));
    for &i in &balance_order {
        out_lines.push(format!("balance: {}; {}", members[i].name, nets[i]));
    }

    for &(from, to, cents) in &settlements {
        out_lines.push(format!(
            "settle: {} -> {}; {}",
            members[from].name, members[to].name, cents
        ));
    }

    Ok(out_lines.join("\n"))
}

