/// Everything that can go wrong while migrating a TripLedger export.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MigrationError {
    /// The first significant line was not `v1` or `v2`.
    UnknownHeader(String),
    /// The line after the header was not a members line.
    MissingMembersLine,
    /// A second `members:` line was found.
    DuplicateMembersLine { line_number: usize },
    /// The members list was empty.
    NoMembers,
    /// A member name did not match the naming rules.
    InvalidMemberName { line_number: usize, name: String },
    /// The same member appeared twice in the members list.
    DuplicateMember { line_number: usize, name: String },
    /// A `*weight` suffix in v2 was not a positive integer.
    InvalidWeight { line_number: usize, name: String, weight: String },
    /// A line was not recognisable, or an expense line had bad structure.
    MalformedLine { line_number: usize, content: String },
    /// The amount field was not a non-negative integer.
    InvalidAmount { line_number: usize, amount: String },
    /// The payer or a participant is not a member of the group.
    UnknownMember { line_number: usize, name: String },
    /// A share in a shares section was not a positive integer.
    InvalidShare { line_number: usize, name: String, share: String },
    /// The same participant appeared twice in one shares section.
    DuplicateParticipant { line_number: usize, name: String },
    /// A v1 document used the v2-only `|` shares syntax.
    SharesNotAllowed { line_number: usize },
}

struct Member {
    name: String,
    weight: u32,
}

struct ParsedExpense {
    payer: usize,
    amount: u64,
    description: String,
    /// (member index, cents) sorted by member name.
    allocations: Vec<(usize, u64)>,
}

/// A valid name is 1..=24 chars, starts with an ASCII lowercase letter,
/// and contains only ASCII lowercase letters, digits, or `_`.
fn is_valid_name(name: &str) -> bool {
    let bytes = name.as_bytes();
    if bytes.is_empty() || bytes.len() > 24 {
        return false;
    }
    if !bytes[0].is_ascii_lowercase() {
        return false;
    }
    bytes
        .iter()
        .all(|&b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'_')
}

/// Index of the entry with the largest amount; ties broken by the
/// lexicographically smallest member name.
fn pick_largest(list: &[(usize, i128)], members: &[Member]) -> usize {
    let mut best = 0usize;
    for i in 1..list.len() {
        let best_amt = list[best].1;
        let (idx, amt) = list[i];
        if amt > best_amt || (amt == best_amt && members[idx].name < members[list[best].0].name) {
            best = i;
        }
    }
    best
}

/// Upgrades a TripLedger v1 or v2 export to the v3 format.
pub fn migrate(input: &str) -> Result<String, MigrationError> {
    // Collect significant lines with their 1-based line numbers.
    let significant: Vec<(usize, &str)> = input
