    let &(header_line_number, header) = significant
        .first()
        .ok_or_else(|| MigrationError::UnknownHeader(String::new()))?;
    let _ = header_line_number;
    let version: u8 = match header {
        "v1" => 1,
        "v2" => 2,
        other => return Err(MigrationError::UnknownHeader(other.to_string())),
    };

    // Members line.
    let &(members_line_number, members_line) =
        significant.get(1).ok_or(MigrationError::MissingMembersLine)?;
    if !members_line.starts_with("members:") {
        return Err(MigrationError::MissingMembersLine);
    }

    let mut members: Vec<Member> = Vec::new();
    let members_body = members_line["members:".len()..].trim();
    if members_body.is_empty() {
        return Err(MigrationError::NoMembers);
    }
    for piece in members_body.split(',') {
        let piece = piece.trim();
        let (name, weight) = if version == 2 {
            match piece.find('*') {
                Some(pos) => {
                    let name = piece[..pos].trim();
                    let weight_text = piece[pos + 1..].trim();
                    match weight_text.parse::<u32>() {
                        Ok(w) if w >= 1 => (name, w),
                        _ => {
                            return Err(MigrationError::InvalidWeight {
                                line_number: members_line_number,
                                name: name.to_string(),
                                weight: weight_text.to_string(),
                            })
                        }
