use std::collections::HashMap;

#[derive(Debug, PartialEq, Eq)]
pub enum KanbanError {
    InvalidCommand(String),
    InvalidLimit(String),
    DuplicateColumn(String),
    UnknownColumn(String),
    DuplicateCard(String),
    UnknownCard(String),
    WipLimitExceeded { column: String, limit: usize },
    LimitBelowCount { column: String, count: usize, limit: usize },
}

struct Column {
    name: String,
    limit: Option<usize>,
    cards: Vec<String>,
}

pub struct Board {
    columns: Vec<Column>,
    /// Maps card id -> index of the column containing it.
    card_index: HashMap<String, usize>,
}

impl Board {
    pub fn new() -> Self {
        Board {
            columns: Vec::new(),
            card_index: HashMap::new(),
        }
    }

    fn find_column(&self, name: &str) -> Option<usize> {
        self.columns.iter().position(|c| c.name == name)
    }

    fn parse_limit_token(token: &str) -> Result<usize, KanbanError> {
        match token.parse::<usize>() {
            Ok(n) if n >= 1 => Ok(n),
            _ => Err(KanbanError::InvalidLimit(token.to_string())),
        }
    }

    pub fn execute(&mut self, line: &str) -> Result<String, KanbanError> {
        let trimmed = line.trim();
        let tokens: Vec<&str> = trimmed.split_whitespace().collect();

        match tokens.as_slice() {
            ["show"] => Ok(self.render()),
            ["column", name] => {
                if self.find_column(name).is_some() {
                    return Err(KanbanError::DuplicateColumn(name.to_string()));
                }
                self.columns.push(Column {
                    name: name.to_string(),
                    limit: None,
                    cards: Vec::new(),
                });
                Ok(format!("column {} created", name))
            }
            ["column", name, "limit", n] => {
                let n = Self::parse_limit_token(n)?;
                if self.find_column(name).is_some() {
                    return Err(KanbanError::DuplicateColumn(name.to_string()));
                }
                self.columns.push(Column {
                    name: name.to_string(),
                    limit: Some(n),
                    cards: Vec::new(),
                });
                Ok(format!("column {} created (limit {})", name, n))
            }
            ["card", id, col] => {
                if self.find_column(col).is_none() {
                    return Err(KanbanError::UnknownColumn(col.to_string()));
                }
                if self.card_index.contains_key(*id) {
                    return Err(KanbanError::DuplicateCard(id.to_string()));
                }
                let idx = self.find_column(col).unwrap();
                if let Some(l) = self.columns[idx].limit {
                    if self.columns[idx].cards.len() >= l {
                        return Err(KanbanError::WipLimitExceeded {
                            column: col.to_string(),
                            limit: l,
                        });
                    }
                }
                self.columns[idx].cards.push(id.to_string());
                self.card_index.insert(id.to_string(), idx);
                Ok(format!("card {} added to {}", id, col))
            }
            ["move", id, col] => {
                let src = match self.card_index.get(*id) {
                    Some(&i) => i,
                    None => return Err(KanbanError::UnknownCard(id.to_string())),
                };
                let dst = match self.find_column(col) {
                    Some(i) => i,
                    None => return Err(KanbanError::UnknownColumn(col.to_string())),
                };
                if let Some(l) = self.columns[dst].limit {
                    if self.columns[dst].cards.len() >= l {
                        return Err(KanbanError::WipLimitExceeded {
                            column: col.to_string(),
                            limit: l,
                        });
                    }
                }
                if src == dst {
                    return Ok(format!("card {} moved to {}", id, col));
                }
                self.columns[src].cards.retain(|c| c != id);
                self.columns[dst].cards.push(id.to_string());
                self.card_index.insert(id.to_string(), dst);
                Ok(format!("card {} moved to {}", id, col))
            }
            ["remove", id] => {
                let idx = match self.card_index.remove(*id) {
                    Some(i) => i,
                    None => return Err(KanbanError::UnknownCard(id.to_string())),
                };
                self.columns[idx].cards.retain(|c| c != id);
                Ok(format!("card {} removed", id))
            }
            ["limit", col, n] => {
                let n = Self::parse_limit_token(n)?;
                let idx = match self.find_column(col) {
                    Some(i) => i,
                    None => return Err(KanbanError::UnknownColumn(col.to_string())),
                };
                let count = self.columns[idx].cards.len();
                if n < count {
                    return Err(KanbanError::LimitBelowCount {
                        column: col.to_string(),
                        count,
                        limit: n,
                    });
                }
                self.columns[idx].limit = Some(n);
                Ok(format!("limit for {} set to {}", col, n))
            }
            _ => Err(KanbanError::InvalidCommand(trimmed.to_string())),
        }
    }

    pub fn run(&mut self, script: &str) -> Result<Vec<String>, KanbanError> {
        let mut outputs = Vec::new();
        for line in script.lines() {
            if line.trim().is_empty() {
                continue;
            }
            let out = self.execute(line)?;
            outputs.push(out);
        }
        Ok(outputs)
    }

    fn render(&self) -> String {
        let parts: Vec<String> = self
            .columns
            .iter()
            .map(|c| {
                let lim = match c.limit {
                    Some(l) => l.to_string(),
                    None => "-".to_string(),
                };
                let mut s = format!("{}[{}/{}]", c.name, c.cards.len(), lim);
                if !c.cards.is_empty() {
                    s.push_str(": ");
                    s.push_str(&c.cards.join(","));
                }
                s
            })
            .collect();
        parts.join(" | ")
    }
}
