use std::collections::HashMap;

/// Fixed application fee, in whole currency units, charged per permit.
pub const PERMIT_FEE: u32 = 150;

/// Maximum number of times a reviewer may send an application back for revisions.
pub const MAX_REVISION_ROUNDS: u32 = 3;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PermitStatus {
    Draft,
    Submitted,
    UnderReview,
    RevisionsRequested,
    Approved,
    Rejected,
    Withdrawn,
    Expired,
}

impl PermitStatus {
    fn is_terminal(self) -> bool {
        matches!(
            self,
            PermitStatus::Approved
                | PermitStatus::Rejected
                | PermitStatus::Withdrawn
                | PermitStatus::Expired
        )
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
