        current: PermitStatus,
    },
    NotSubmitted {
        id: u32,
        current: PermitStatus,
    },
    NotUnderReview {
        id: u32,
        current: PermitStatus,
    },
    NotRevisionsRequested {
        id: u32,
        current: PermitStatus,
    },
    NotWithdrawable {
        id: u32,
        current: PermitStatus,
    },
