    pub loan_id: String,
    pub patron_id: String,
    pub copy_id: String,
    pub borrowed_on: u32,
    pub due_on: u32,
    pub returned_on: Option<u32>,
}

/// A fine as recorded by the billing system.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Fine {
    pub loan_id: String,
    pub patron_id: String,
    pub amount_cents: u32,
}

/// A hold as recorded by the circulation system.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Hold {
    pub hold_id: String,
    pub copy_id: String,
    pub patron_id: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Discrepancy {
    LoanWithoutFine { loan_id: String },
    FineWithoutLoan { loan_id: String },
    PatronMismatch { loan_id: String, loan_patron_id: String, fine_patron_id: String },
    FineAmountMismatch { loan_id: String, expected_cents: u32, billed_cents: u32 },
    HoldOnReturnedCopy { hold_id: String, copy_id: String },
    HoldOnUnknownCopy { hold_id: String, copy_id: String },
    DuplicateHold { copy_id: String, hold_ids: Vec<String> },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ReconcileError {
    DuplicateLoanId { loan_id: String },
    DuplicateFineForLoan { loan_id: String },
    DuplicateHoldId { hold_id: String },
    DueBeforeBorrowed { loan_id: String },
    ReturnedBeforeBorrowed { loan_id: String },
}

pub fn expected_fine_cents(loan: &Loan, as_of_day: u32) -> u32;

pub fn reconcile(
    loans: &[Loan],
    fines: &[Fine],
    holds: &[Hold],
    as_of_day: u32,
) -> Result<Vec<Discrepancy>, ReconcileError>;
```

## Fine rule

The fine for a loan is `FINE_CENTS_PER_DAY` cents for each full day past `due_on`, capped at `FINE_CAP_CENTS`:

- The *end day* is `returned_on` when the loan has been returned, otherwise `as_of_day`.
- The number of overdue days is `end_day - due_on`, or `0` if that difference would be negative (returned early, on time, or not yet due).
- The fine in cents is the minimum of `overdue_days * FINE_CENTS_PER_DAY` and `FINE_CAP_CENTS`.

`expected_fine_cents` implements exactly this rule, and `reconcile` must use the same rule.

Consequences worth noting: a loan returned exactly on its due date owes nothing; a loan still out with `as_of_day <= due_on` owes nothing; once returned, a later `as_of_day` never increases the fine.

## Matching loans against fines

- Loans and fines are matched by `loan_id`. Every loan must have exactly one fine record — **even a loan that owes nothing must have a `0`-cent fine record**.
- A loan with no fine record yields `LoanWithoutFine { loan_id }`.
- A fine record whose `loan_id` matches no loan yields `FineWithoutLoan { loan_id }`.
- When both sides exist, patron ids are compared first. If they differ, report `PatronMismatch { loan_id, loan_patron_id, fine_patron_id }` and do **not** compare amounts. If the patron ids match but the billed amount differs from the expected fine, report `FineAmountMismatch { loan_id, expected_cents, billed_cents }`.

## Hold checks

A copy is **known** if any loan record references its `copy_id`. A known copy is **active** if at least one loan on that copy has `returned_on == None`; otherwise (known, but every loan on it was returned) it is **returned**. A copy may legitimately appear in several loans (borrowed, returned, borrowed again) — a hold is fine as long as any one of those loans is still open.

- A hold whose copy is unknown yields `HoldOnUnknownCopy { hold_id, copy_id }`.
- A hold whose copy is returned yields `HoldOnReturnedCopy { hold_id, copy_id }`.
- A hold on an active copy produces no discrepancy, regardless of who placed the hold.
- If two or more holds target the same copy, report exactly one `DuplicateHold { copy_id, hold_ids }` for that copy, where `hold_ids` is the full list of hold ids on that copy, sorted ascending (lexicographic string order).

## Input validation

Validation happens before any matching: if any input is invalid, `reconcile` returns `Err` and performs no discrepancy reporting.

1. Loans are scanned in slice order. For each loan, in this order: if its `loan_id` was already seen, return `Err(DuplicateLoanId { loan_id })`; if `due_on < borrowed_on`, return `Err(DueBeforeBorrowed { loan_id })`; if `returned_on` is `Some(r)` with `r < borrowed_on`, return `Err(ReturnedBeforeBorrowed { loan_id })`. The first problem found wins.
2. Fines are scanned in slice order; a `loan_id` seen twice returns `Err(DuplicateFineForLoan { loan_id })`.
3. Holds are scanned in slice order; a `hold_id` seen twice returns `Err(DuplicateHoldId { hold_id })`.

## Ordering of the result

`Ok` contains all discrepancies in this deterministic order:

1. All loan-level discrepancies (`LoanWithoutFine`, `FineWithoutLoan`, `PatronMismatch`, `FineAmountMismatch`) sorted ascending by `loan_id`.
2. All per-hold discrepancies (`HoldOnUnknownCopy`, `HoldOnReturnedCopy`) sorted ascending by `hold_id`.
3. All `DuplicateHold` entries sorted ascending by `copy_id`.

No other discrepancies exist, and no discrepancy is ever duplicated.

