//! Reconciles the Smalltown Library circulation system (loans and holds)
//! against its billing system (fines).

use std::collections::{HashMap, HashSet};

/// Fine charged for each full day a loan is overdue.
pub const FINE_CENTS_PER_DAY: u32 = 25;

/// Maximum fine that can be charged for a single loan.
pub const FINE_CAP_CENTS: u32 = 500;

/// A loan as recorded by the circulation system.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Loan {
    pub loan_id: String,
    pub patron_id: String,
    pub copy_id: String,
    pub borrowed_on: u32,
    pub due_on: u32,
    pub returned_on: Option<u32>,
}

/// A fine as recorded by the billing system.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Fine {
    pub loan_id: String,
    pub patron_id: String,
    pub amount_cents: u32,
}

/// A hold as recorded by the circulation system.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Hold {
    pub hold_id: String,
    pub copy_id: String,
    pub patron_id: String,
}

/// A single difference between the two data sets.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Discrepancy {
    LoanWithoutFine {
        loan_id: String,
    },
    FineWithoutLoan {
        loan_id: String,
    },
    PatronMismatch {
        loan_id: String,
        loan_patron_id: String,
        fine_patron_id: String,
    },
    FineAmountMismatch {
        loan_id: String,
        expected_cents: u32,
        billed_cents: u32,
    },
    HoldOnReturnedCopy {
        hold_id: String,
        copy_id: String,
    },
    HoldOnUnknownCopy {
        hold_id: String,
        copy_id: String,
    },
    DuplicateHold {
        copy_id: String,
        hold_ids: Vec<String>,
    },
}

/// An error caused by invalid input data.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ReconcileError {
    DuplicateLoanId {
        loan_id: String,
    },
    DuplicateFineForLoan {
        loan_id: String,
    },
    DuplicateHoldId {
        hold_id: String,
    },
    DueBeforeBorrowed {
        loan_id: String,
    },
    ReturnedBeforeBorrowed {
        loan_id: String,
    },
}

/// The fine owed for `loan`, computed as of `as_of_day`.
///
/// The end day is `returned_on` when the loan has been returned, otherwise
/// `as_of_day`. Each full day past `due_on` costs [`FINE_CENTS_PER_DAY`]
/// cents, capped at [`FINE_CAP_CENTS`].
pub fn expected_fine_cents(loan: &Loan, as_of_day: u32) -> u32 {
    let end_day = loan.returned_on.unwrap_or(as_of_day);
    let overdue_days = end_day.saturating_sub(loan.due_on);
    (overdue_days * FINE_CENTS_PER_DAY).min(FINE_CAP_CENTS)
}

/// Matches loans, fines and holds and reports every difference.
pub fn reconcile(
    loans: &[Loan],
    fines: &[Fine],
    holds: &[Hold],
    as_of_day: u32,
) -> Result<Vec<Discrepancy>, ReconcileError> {
    // ---- Validation (before any matching) ----

    // 1. Loans, in slice order, checking in this order per loan:
    //    duplicate id, due before borrowed, returned before borrowed.
    let mut seen_loan_ids: HashSet<&str> = HashSet::new();
    for loan in loans {
        if !seen_loan_ids.insert(loan.loan_id.as_str()) {
            return Err(ReconcileError::DuplicateLoanId {
                loan_id: loan.loan_id.clone(),
            });
        }
        if loan.due_on < loan.borrowed_on {
            return Err(ReconcileError::DueBeforeBorrowed {
                loan_id: loan.loan_id.clone(),
            });
        }
        if let Some(returned) = loan.returned_on {
            if returned < loan.borrowed_on {
                return Err(ReconcileError::ReturnedBeforeBorrowed {
                    loan_id: loan.loan_id.clone(),
                });
            }
        }
    }

    // 2. Fines: duplicate loan_id.
    let mut seen_fine_loan_ids: HashSet<&str> = HashSet::new();
    for fine in fines {
        if !seen_fine_loan_ids.insert(fine.loan_id.as_str()) {
            return Err(ReconcileError::DuplicateFineForLoan {
                loan_id: fine.loan_id.clone(),
            });
        }
    }

    // 3. Holds: duplicate hold_id.
    let mut seen_hold_ids: HashSet<&str> = HashSet::new();
    for hold in holds {
        if !seen_hold_ids.insert(hold.hold_id.as_str()) {
            return Err(ReconcileError::DuplicateHoldId {
                hold_id: hold.hold_id.clone(),
            });
        }
    }

    // ---- Loan/fine matching ----

    let loans_by_id: HashMap<&str, &Loan> =
        loans.iter().map(|loan| (loan.loan_id.as_str(), loan)).collect();
    let fines_by_id: HashMap<&str, &Fine> =
        fines.iter().map(|fine| (fine.loan_id.as_str(), fine)).collect();

    // Loan-level discrepancies, each tagged with its loan_id for sorting.
    let mut loan_level: Vec<(&str, Discrepancy)> = Vec::new();

    for loan in loans {
        match fines_by_id.get(loan.loan_id.as_str()) {
            None => loan_level.push((
                loan.loan_id.as_str(),
                Discrepancy::LoanWithoutFine {
                    loan_id: loan.loan_id.clone(),
                },
            )),
            Some(fine) => {
                if loan.patron_id != fine.patron_id {
                    loan_level.push((
                        loan.loan_id.as_str(),
                        Discrepancy::PatronMismatch {
                            loan_id: loan.loan_id.clone(),
                            loan_patron_id: loan.patron_id.clone(),
                            fine_patron_id: fine.patron_id.clone(),
                        },
                    ));
                } else {
                    let expected = expected_fine_cents(loan, as_of_day);
                    if fine.amount_cents != expected {
                        loan_level.push((
                            loan.loan_id.as_str(),
                            Discrepancy::FineAmountMismatch {
                                loan_id: loan.loan_id.clone(),
                                expected_cents: expected,
                                billed_cents: fine.amount_cents,
                            },
                        ));
                    }
                }
            }
        }
    }

    for fine in fines {
        if !loans_by_id.contains_key(fine.loan_id.as_str()) {
            loan_level.push((
                fine.loan_id.as_str(),
                Discrepancy::FineWithoutLoan {
                    loan_id: fine.loan_id.clone(),
                },
            ));
        }
    }

    loan_level.sort_by(|a, b| a.0.cmp(b.0));

    // ---- Copy status for hold checks ----
    //
    // A copy is known if any loan references it; a known copy is active if
    // at least one loan on it is still open.

    struct CopyStatus {
        known: bool,
        active: bool,
    }

    let mut copies: HashMap<&str, CopyStatus> = HashMap::new();
    for loan in loans {
        let status = copies.entry(loan.copy_id.as_str()).or_insert(CopyStatus {
            known: true,
            active: false,
        });
        if loan.returned_on.is_none() {
            status.active = true;
        }
    }

    // ---- Per-hold discrepancies ----

    let mut hold_level: Vec<(&str, Discrepancy)> = holds
        .iter()
        .filter_map(|hold| {
            match copies.get(hold.copy_id.as_str()) {
                None => Some((
                    hold.hold_id.as_str(),
                    Discrepancy::HoldOnUnknownCopy {
                        hold_id: hold.hold_id.clone(),
                        copy_id: hold.copy_id.clone(),
                    },
                )),
                Some(status) if !status.active => Some((
                    hold.hold_id.as_str(),
                    Discrepancy::HoldOnReturnedCopy {
                        hold_id: hold.hold_id.clone(),
                        copy_id: hold.copy_id.clone(),
                    },
                )),
                _ => None,
            }
        })
        .collect();

    hold_level.sort_by(|a, b| a.0.cmp(b.0));

    // ---- Duplicate holds ----

    let mut holds_by_copy: HashMap<&str, Vec<&str>> = HashMap::new();
    for hold in holds {
        holds_by_copy
            .entry(hold.copy_id.as_str())
            .or_default()
            .push(hold.hold_id.as_str());
    }

    let mut duplicate_holds: Vec<(&str, Vec<String>)> = holds_by_copy
        .into_iter()
        .filter(|(_, hold_ids)| hold_ids.len() >= 2)
        .map(|(copy_id, mut hold_ids)| {
            hold_ids.sort_unstable();
            (copy_id, hold_ids.iter().map(|s| s.to_string()).collect())
        })
        .collect();
    duplicate_holds.sort_by(|a, b| a.0.cmp(b.0));

    // ---- Assemble the result in the required order ----

    let mut result: Vec<Discrepancy> = Vec::new();
    result.extend(loan_level.into_iter().map(|(_, d)| d));
    result.extend(hold_level.into_iter().map(|(_, d)| d));
    result.extend(
        duplicate_holds
            .into_iter()
            .map(|(copy_id, hold_ids)| Discrepancy::DuplicateHold {
                copy_id: copy_id.to_string(),
                hold_ids,
            }),
    );

    Ok(result)
}
```

A few notes on the implementation:

- **Validation order is preserved exactly**: loans are scanned first (duplicate id, then due-date, then return-date checks, in that order per loan), then fines, then holds. The first error found short-circuits before any matching happens.
- **`expected_fine_cents`** uses `saturating_sub` so early returns / not-yet-due loans yield `0` days overdue, and `.min(FINE_CAP_CENTS)` applies the cap. It's also the single source of truth used by `reconcile`, so the two can never drift apart.
- **Loan-level discrepancies** are collected as `(loan_id, Discrepancy)` pairs so they can be sorted by `loan_id` regardless of variant. Since duplicate loan ids and duplicate fines per loan are rejected in validation, each `loan_id` appears at most once in this group, so the sort is unambiguous.
- **Copy status** tracks "known" (any loan references it) and "active" (at least one open loan). A copy with a returned loan *and* an open loan correctly counts as active, so re-borrowed copies don't trigger `HoldOnReturnedCopy`.
- **Duplicate holds** are grouped per copy, filtered to groups of two or more, with `hold_ids` sorted lexicographically, and the groups themselves sorted by `copy_id`.
- Everything borrows from the input slices via `&str` keys; no input is mutated, and the only allocations are for the returned values (and internal index maps), keeping it pure and deterministic.

