use std::collections::BTreeMap;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RolloutRule {
    pub segment: String,
    pub percentage: i32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Flag {
    pub name: String,
    pub enabled: bool,
    pub rules: Vec<RolloutRule>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Difference {
    MissingInDeclared { flag: String },
    MissingInLive { flag: String },
    EnabledMismatch { flag: String, declared: bool, live: bool },
    RuleMissingInDeclared { flag: String, segment: String },
    RuleMissingInLive { flag: String, segment: String },
    PercentageMismatch { flag: String, segment: String, declared: i32, live: i32 },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ValidationError {
    EmptyFlagName,
    EmptySegmentName { flag: String },
    PercentageOutOfRange { flag: String, segment: String, percentage: i32 },
    DuplicateSegment { flag: String, segment: String },
    DuplicateFlag { name: String },
}

#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct Summary {
    pub missing_in_declared: usize,
    pub missing_in_live: usize,
    pub enabled_mismatches: usize,
    pub rule_missing_in_declared: usize,
    pub rule_missing_in_live: usize,
    pub percentage_mismatches: usize,
}

pub fn validate_snapshot(flags: &[Flag]) -> Result<(), ValidationError> {
    let mut seen_flags: Vec<&str> = Vec::new();

    for flag in flags {
        if flag.name.is_empty() {
            return Err(ValidationError::EmptyFlagName);
        }
        if seen_flags.contains(&flag.name.as_str()) {
            return Err(ValidationError::DuplicateFlag {
                name: flag.name.clone(),
            });
        }
        seen_flags.push(flag.name.as_str());

        let mut seen_segments: Vec<&str> = Vec::new();
        for rule in &flag.rules {
            if rule.segment.is_empty() {
                return Err(ValidationError::EmptySegmentName {
                    flag: flag.name.clone(),
                });
            }
            if !(0..=100).contains(&rule.percentage) {
                return Err(ValidationError::PercentageOutOfRange {
                    flag: flag.name.clone(),
                    segment: rule.segment.clone(),
                    percentage: rule.percentage,
                });
            }
            if seen_segments.contains(&rule.segment.as_str()) {
                return Err(ValidationError::DuplicateSegment {
                    flag: flag.name.clone(),
                    segment: rule.segment.clone(),
                });
            }
            seen_segments.push(rule.segment.as_str());
        }
    }

    Ok(())
}

pub fn reconcile(declared: &[Flag], live: &[Flag]) -> Result<Vec<Difference>, ValidationError> {
    validate_snapshot(declared)?;
    validate_snapshot(live)?;

    let declared_map: BTreeMap<&str, &Flag> =
        declared.iter().map(|f| (f.name.as_str(), f)).collect();
    let live_map: BTreeMap<&str, &Flag> = live.iter().map(|f| (f.name.as_str(), f)).collect();

    let mut flag_names: Vec<&str> = Vec::new();
    for name in declared_map.keys() {
        flag_names.push(name);
    }
    for name in live_map.keys() {
        if !declared_map.contains_key(name) {
            flag_names.push(name);
        }
    }
    flag_names.sort_unstable();

    let mut differences = Vec::new();

    for name in flag_names {
        match (declared_map.get(name), live_map.get(name)) {
            (Some(_), None) => {
                differences.push(Difference::MissingInLive {
                    flag: name.to_string(),
                });
            }
            (None, Some(_)) => {
                differences.push(Difference::MissingInDeclared {
                    flag: name.to_string(),
                });
            }
            (Some(d), Some(l)) => {
                if d.enabled != l.enabled {
                    differences.push(Difference::EnabledMismatch {
                        flag: name.to_string(),
                        declared: d.enabled,
                        live: l.enabled,
                    });
                }

                let d_rules: BTreeMap<&str, i32> =
                    d.rules.iter().map(|r| (r.segment.as_str(), r.percentage)).collect();
                let l_rules: BTreeMap<&str, i32> =
                    l.rules.iter().map(|r| (r.segment.as_str(), r.percentage)).collect();

                let mut segments: Vec<&str> = Vec::new();
                for seg in d_rules.keys() {
                    segments.push(seg);
                }
                for seg in l_rules.keys() {
                    if !d_rules.contains_key(seg) {
                        segments.push(seg);
                    }
                }
                segments.sort_unstable();

                for seg in segments {
                    match (d_rules.get(seg), l_rules.get(seg)) {
                        (Some(_), None) => {
                            differences.push(Difference::RuleMissingInLive {
                                flag: name.to_string(),
                                segment: seg.to_string(),
                            });
                        }
                        (None, Some(_)) => {
                            differences.push(Difference::RuleMissingInDeclared {
                                flag: name.to_string(),
                                segment: seg.to_string(),
                            });
                        }
                        (Some(dp), Some(lp)) => {
                            if dp != lp {
                                differences.push(Difference::PercentageMismatch {
                                    flag: name.to_string(),
                                    segment: seg.to_string(),
                                    declared: *dp,
                                    live: *lp,
                                });
                            }
                        }
                    }
                }
            }
            (None, None) => unreachable!(),
        }
    }

    Ok(differences)
}

pub fn summarize(differences: &[Difference]) -> Summary {
    let mut summary = Summary::default();
    for diff in differences {
        match diff {
            Difference::MissingInDeclared { .. } => summary.missing_in_declared += 1,
            Difference::MissingInLive { .. } => summary.missing_in_live += 1,
            Difference::EnabledMismatch { .. } => summary.enabled_mismatches += 1,
            Difference::RuleMissingInDeclared { .. } => summary.rule_missing_in_declared += 1,
            Difference::RuleMissingInLive { .. } => summary.rule_missing_in_live += 1,
            Difference::PercentageMismatch { .. } => summary.percentage_mismatches += 1,
        }
    }
    summary
}
