use std::collections::{BTreeMap, BTreeSet};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Course {
    pub code: String,
    pub capacity: usize,
    pub prerequisites: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Catalog {
    pub courses: BTreeMap<String, Course>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParseError {
    UnknownDirective { line: usize, directive: String },
    MissingCourseCode { line: usize },
    InvalidCourseCode { line: usize, code: String },
    MissingCapacity { line: usize },
    InvalidCapacity { line: usize, value: String },
    MissingPrerequisite { line: usize },
    DuplicateCourse { line: usize, code: String },
    DuplicatePrerequisite { line: usize, code: String },
    UnexpectedToken { line: usize, token: String },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ValidationError {
    SelfPrerequisite { code: String },
    UnknownPrerequisite { course: String, prerequisite: String },
    PrerequisiteCycle { course: String },
}

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct RegistrationState {
    pub enrolled: BTreeMap<String, BTreeSet<String>>,
    pub completed: BTreeMap<String, BTreeSet<String>>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RegistrationError {
    Catalog(ValidationError),
    UnknownDirective { line: usize, directive: String },
    MissingStudent { line: usize },
    MissingCourse { line: usize },
    UnexpectedToken { line: usize, token: String },
    InvalidStudent { line: usize, student: String },
    UnknownCourse { line: usize, course: String },
    AlreadyEnrolled { line: usize, student: String, course: String },
    AlreadyCompleted { line: usize, student: String, course: String },
    NotEnrolled { line: usize, student: String, course: String },
    PrerequisiteMissing { line: usize, student: String, course: String, missing: String },
    CourseFull { line: usize, student: String, course: String },
}

/// Trim leading/trailing ASCII whitespace (spaces, tabs, `\r`).
fn trim_line(line: &str) -> &str {
    line.trim_matches(|c: char| c == ' ' || c == '\t' || c == '\r')
}

/// 2 to 8 characters; first is `A`-`Z`, the rest are `A`-`Z` or `0`-`9`.
fn is_valid_course_code(s: &str) -> bool {
    let b = s.as_bytes();
    (2..=8).contains(&b.len())
        && b[0].is_ascii_uppercase()
        && b[1..]
            .iter()
            .all(|&c| c.is_ascii_uppercase() || c.is_ascii_digit())
}

/// 1 to 3 ASCII digits, first digit not `0` (value 1..=999).
fn is_valid_capacity(s: &str) -> bool {
    let b = s.as_bytes();
    (1..=3).contains(&b.len())
        && b[0] != b'0'
        && b.iter().all(|&c| c.is_ascii_digit())
}

/// 2 to 12 characters; first is `a`-`z`, the rest are `a`-`z` or `0`-`9`.
fn is_valid_student(s: &str) -> bool {
    let b = s.as_bytes();
    (2..=12).contains(&b.len())
        && b[0].is_ascii_lowercase()
        && b[1..]
            .iter()
            .all(|&c| c.is_ascii_lowercase() || c.is_ascii_digit())
}

pub fn parse_catalog(input: &str) -> Result<Catalog, ParseError> {
    let mut catalog = Catalog::default();

    for (idx, raw) in input.split('\n').enumerate() {
        let line_no = idx + 1;
        let line = trim_line(raw);
        if line.is_empty() {
            continue;
        }
        let tokens: Vec<&str> = line.split_whitespace().collect();

        // 1. First token must be `course`.
        if tokens[0] != "course" {
            return Err(ParseError::UnknownDirective {
                line: line_no,
                directive: tokens[0].to_string(),
            });
        }

        // 2. Course code must exist.
        let code = match tokens.get(1) {
            Some(c) => *c,
            None => return Err(ParseError::MissingCourseCode { line: line_no }),
        };

        // 3. Course code must be valid.
        if !is_valid_course_code(code) {
            return Err(ParseError::InvalidCourseCode {
                line: line_no,
                code: code.to_string(),
            });
        }

        // 4. Capacity must exist.
        let cap = match tokens.get(2) {
            Some(c) => *c,
            None => return Err(ParseError::MissingCapacity { line: line_no }),
        };

        // 5. Capacity must be valid.
        if !is_valid_capacity(cap) {
            return Err(ParseError::InvalidCapacity {
                line: line_no,
                value: cap.to_string(),
            });
        }

        // 6. Optional `requires` list.
        let mut prerequisites: Vec<String> = Vec::new();
        if let Some(&fourth) = tokens.get(3) {
            if fourth == "requires" {
                if tokens.len() < 5 {
                    return Err(ParseError::MissingPrerequisite { line: line_no });
                }
                let mut seen: BTreeSet<&str> = BTreeSet::new();
                for &t in &tokens[4..] {
                    if !is_valid_course_code(t) {
                        return Err(ParseError::InvalidCourseCode {
                            line: line_no,
                            code: t.to_string(),
                        });
                    }
                    if !seen.insert(t) {
                        return Err(ParseError::DuplicatePrerequisite {
                            line: line_no,
                            code: t.to_string(),
                        });
                    }
                    prerequisites.push(t.to_string());
                }
            } else {
                return Err(ParseError::UnexpectedToken {
                    line: line_no,
                    token: fourth.to_string(),
                });
            }
        }

        // 7. Duplicate course check (after all syntactic checks).
        if catalog.courses.contains_key(code) {
            return Err(ParseError::DuplicateCourse {
                line: line_no,
                code: code.to_string(),
            });
        }

        catalog.courses.insert(
            code.to_string(),
            Course {
                code: code.to_string(),
                capacity: cap.parse::<usize>().expect("validated capacity"),
                prerequisites,
            },
        );
    }

    Ok(catalog)
}

impl Catalog {
    pub fn course(&self, code: &str) -> Option<&Course> {
        self.courses.get(code)
    }

    pub fn validate(&self) -> Result<(), ValidationError> {
        // 1. Self-prerequisite: lexicographically smallest such code.
        for (code, course) in &self.courses {
            if course.prerequisites.iter().any(|p| p == code) {
                return Err(ValidationError::SelfPrerequisite { code: code.clone() });
            }
        }

        // 2. Unknown prerequisite: courses in ascending order, prereqs in declared order.
        for (code, course) in &self.courses {
            for p in &course.prerequisites {
                if !self.courses.contains_key(p) {
                    return Err(ValidationError::UnknownPrerequisite {
                        course: code.clone(),
                        prerequisite: p.clone(),
                    });
                }
            }
        }

        // 3. Cycle of two or more courses: smallest code on a cycle.
        for code in self.courses.keys() {
            if self.on_cycle(code) {
                return Err(ValidationError::PrerequisiteCycle {
                    course: code.clone(),
                });
            }
        }

        Ok(())
    }

    /// Returns true iff `start` can reach itself by following prerequisite
    /// edges (course -> its prerequisites) through at least one edge.
    fn on_cycle(&self, start: &str) -> bool {
        let mut visited: BTreeSet<&str> = BTreeSet::new();
        let mut stack: Vec<&str> = Vec::new();
        if let Some(course) = self.courses.get(start) {
            for p in &course.prerequisites {
                stack.push(p.as_str());
            }
        }
        while let Some(node) = stack.pop() {
            if !visited.insert(node) {
                continue;
            }
            if node == start {
                return true;
            }
            if let Some(course) = self.courses.get(node) {
                for p in &course.prerequisites {
                    stack.push(p.as_str());
                }
            }
        }
        false
    }
}

pub fn register(catalog: &Catalog, plan: &str) -> Result<RegistrationState, RegistrationError> {
    catalog.validate().map_err(RegistrationError::Catalog)?;

    let mut state = RegistrationState::default();

    for (idx, raw) in plan.split('\n').enumerate() {
        let line_no = idx + 1;
        let line = trim_line(raw);
        if line.is_empty() {
            continue;
        }
        let tokens: Vec<&str> = line.split_whitespace().collect();
        let directive = tokens[0];

        // 1. Directive check.
        if directive != "enroll" && directive != "drop" && directive != "complete" {
            return Err(RegistrationError::UnknownDirective {
                line: line_no,
                directive: directive.to_string(),
            });
        }

        // 2. Token count.
        match tokens.len() {
            1 => return Err(RegistrationError::MissingStudent { line: line_no }),
            2 => return Err(RegistrationError::MissingCourse { line: line_no }),
            3 => {}
            _ => {
                return Err(RegistrationError::UnexpectedToken {
                    line: line_no,
                    token: tokens[3].to_string(),
                })
            }
        }

        let student = tokens[1];
        let course = tokens[2];

        // 3. Student id validity.
        if !is_valid_student(student) {
            return Err(RegistrationError::InvalidStudent {
                line: line_no,
                student: student.to_string(),
            });
        }

        // 4. Course must exist in the catalog.
        if catalog.course(course).is_none() {
            return Err(RegistrationError::UnknownCourse {
                line: line_no,
                course: course.to_string(),
            });
        }

        match directive {
            "enroll" => {
                if state.is_enrolled(student, course) {
                    return Err(RegistrationError::AlreadyEnrolled {
                        line: line_no,
                        student: student.to_string(),
                        course: course.to_string(),
                    });
                }
                if state.has_completed(student, course) {
                    return Err(RegistrationError::AlreadyCompleted {
                        line: line_no,
                        student: student.to_string(),
                        course: course.to_string(),
                    });
                }
                let course_info = catalog.course(course).expect("checked above");
                for p in &course_info.prerequisites {
                    if !state.has_completed(student, p) {
                        return Err(RegistrationError::PrerequisiteMissing {
                            line: line_no,
                            student: student.to_string(),
                            course: course.to_string(),
                            missing: p.clone(),
                        });
                    }
                }
                let enrollees = state
                    .enrolled
                    .values()
                    .filter(|s| s.contains(course))
                    .count();
                if enrollees >= course_info.capacity {
                    return Err(RegistrationError::CourseFull {
                        line: line_no,
                        student: student.to_string(),
                        course: course.to_string(),
                    });
                }
                state
                    .enrolled
                    .entry(student.to_string())
                    .or_default()
                    .insert(course.to_string());
            }
            "drop" => {
                if !state.is_enrolled(student, course) {
                    return Err(RegistrationError::NotEnrolled {
                        line: line_no,
                        student: student.to_string(),
                        course: course.to_string(),
                    });
                }
                let set = state.enrolled.get_mut(student).expect("is_enrolled was true");
                set.remove(course);
                let now_empty = set.is_empty();
                if now_empty {
                    state.enrolled.remove(student);
                }
            }
            "complete" => {
                if state.has_completed(student, course) {
                    return Err(RegistrationError::AlreadyCompleted {
                        line: line_no,
                        student: student.to_string(),
                        course: course.to_string(),
                    });
                }
                if state.is_enrolled(student, course) {
                    let set = state
                        .enrolled
                        .get_mut(student)
                        .expect("is_enrolled was true");
                    set.remove(course);
                    let now_empty = set.is_empty();
                    if now_empty {
                        state.enrolled.remove(student);
                    }
                }
                state
                    .completed
                    .entry(student.to_string())
                    .or_default()
                    .insert(course.to_string());
            }
            _ => unreachable!("directive checked above"),
        }
    }

    Ok(state)
}

impl RegistrationState {
    pub fn is_enrolled(&self, student: &str, course: &str) -> bool {
        self.enrolled
            .get(student)
            .map_or(false, |s| s.contains(course))
    }

    pub fn has_completed(&self, student: &str, course: &str) -> bool {
        self.completed
            .get(student)
            .map_or(false, |s| s.contains(course))
    }

    pub fn enrolled_students(&self, course: &str) -> Vec<String> {
        self.enrolled
            .iter()
            .filter(|(_, s)| s.contains(course))
            .map(|(student, _)| student.clone())
            .collect()
    }

    pub fn remaining_capacity(&self, catalog: &Catalog, course: &str) -> Option<usize> {
        let course_info = catalog.course(course)?;
        let enrollees = self
            .enrolled
            .values()
            .filter(|s| s.contains(course))
            .count();
        Some(course_info.capacity.saturating_sub(enrollees))
    }
}
```

