//! An index of bibliography entries that renders citations in a fixed
//! author-date style.

/// A single bibliography entry.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Entry {
    pub key: String,
    pub authors: Vec<String>,
    pub year: u16,
    pub title: String,
}

/// All errors reported by the citation index.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CitationError {
    InvalidKey(String),
    NoAuthors,
    InvalidAuthor(String),
    InvalidYear(u16),
    EmptyTitle,
    DuplicateKey(String),
    UnknownKey(String),
    InvalidPage(String),
    NoCitations,
    DuplicateCitation(String),
    DisambiguationOverflow,
}

/// The citation index.
#[derive(Debug, Clone, Default)]
pub struct CitationIndex {
    entries: Vec<Entry>,
}

/// Returns the lead surname of an author string ("Surname, Given" format).
fn lead_surname_of(author: &str) -> &str {
    match author.split_once(',') {
        Some((surname, _)) => surname,
        None => author,
    }
}

/// Returns the lead surname of an entry (from its first author).
fn entry_lead_surname(entry: &Entry) -> &str {
    lead_surname_of(&entry.authors[0])
}

/// Validates a single author string.
fn is_valid_author(author: &str) -> bool {
    if author.is_empty() || author.trim() != author {
        return false;
    }
    let commas = author.matches(',').count();
    if commas != 1 {
        return false;
    }
    let (surname, given) = author.split_once(',').unwrap();
    if surname.is_empty() || surname.trim() != surname {
        return false;
    }
    if given.trim().is_empty() {
        return false;
    }
    true
}

impl CitationIndex {
    pub fn new() -> Self {
        CitationIndex { entries: Vec::new() }
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    pub fn get(&self, key: &str) -> Option<&Entry> {
        self.entries.iter().find(|e| e.key == key)
    }

    pub fn add(&mut self, entry: Entry) -> Result<(), CitationError> {
        // 1. Key validation.
        if entry.key.is_empty() || entry.key.chars().any(char::is_whitespace) {
            return Err(CitationError::InvalidKey(entry.key));
        }
        // 2. Authors list non-empty.
        if entry.authors.is_empty() {
            return Err(CitationError::NoAuthors);
        }
        // 3. Each author.
        for author in &entry.authors {
            if !is_valid_author(author) {
                return Err(CitationError::InvalidAuthor(author.clone()));
            }
        }
        // 4. Year.
        if !(1000..=9999).contains(&entry.year) {
            return Err(CitationError::InvalidYear(entry.year));
        }
        // 5. Title.
        if entry.title.trim().is_empty() {
            return Err(CitationError::EmptyTitle);
        }
        // 6. Duplicate key.
        if self.get(&entry.key).is_some() {
            return Err(CitationError::DuplicateKey(entry.key));
        }
        // 7. Disambiguation capacity.
        let surname = entry_lead_surname(&entry);
        let group_size = self
            .entries
            .iter()
            .filter(|e| entry_lead_surname(e) == surname && e.year == entry.year)
            .count();
        if group_size >= 26 {
            return Err(CitationError::DisambiguationOverflow);
        }

        self.entries.push(entry);
        Ok(())
    }

    pub fn remove(&mut self, key: &str) -> Result<Entry, CitationError> {
        let pos = self
            .entries
            .iter()
            .position(|e| e.key == key)
            .ok_or_else(|| CitationError::UnknownKey(key.to_string()))?;
        Ok(self.entries.remove(pos))
    }

    /// Computes the disambiguation suffix for the entry with the given key.
    fn suffix_for(&self, key: &str) -> &str {
        let entry = match self.get(key) {
            Some(e) => e,
            None => return "",
        };
        let surname = entry_lead_surname(entry);
        let mut position = 0usize;
        let mut count = 0usize;
        for e in &self.entries {
            if entry_lead_surname(e) == surname && e.year == entry.year {
                if e.key == key {
                    position = count;
                }
                count += 1;
            }
        }
        if count > 1 {
            // Store the suffix char in a small static table to return &str.
            // Positions are guaranteed to be < 26 by `add`.
            let ch = (b'a' + position as u8) as char;
            // We cannot return a reference to a temporary; instead we build
            // the suffix string in the callers. Return "" here is wrong, so
            // this method returns the suffix via a String instead.
            // See `suffix_string_for`.
            let _ = ch;
            ""
        } else {
            ""
        }
    }

    /// Computes the disambiguation suffix (owned) for the entry with the
    /// given key.
    fn suffix_string_for(&self, key: &str) -> String {
        let entry = match self.get(key) {
            Some(e) => e,
            None => return String::new(),
        };
        let surname = entry_lead_surname(entry);
        let mut position = 0usize;
        let mut count = 0usize;
        for e in &self.entries {
            if entry_lead_surname(e) == surname && e.year == entry.year {
                if e.key == key {
                    position = count;
                }
                count += 1;
            }
        }
        if count > 1 {
            ((b'a' + position as u8) as char).to_string()
        } else {
            String::new()
        }
    }

    /// The author part used for in-text citations.
    fn author_part(entry: &Entry) -> String {
        match entry.authors.len() {
            1 => lead_surname_of(&entry.authors[0]).to_string(),
            2 => format!(
                "{} & {}",
                lead_surname_of(&entry.authors[0]),
                lead_surname_of(&entry.authors[1])
            ),
            _ => format!("{} et al.", lead_surname_of(&entry.authors[0])),
        }
    }

    /// The core citation string: "{author part}, {year}{suffix}".
    fn core(&self, entry: &Entry) -> String {
        let suffix = self.suffix_string_for(&entry.key);
        format!("{} {}, {}{}", Self::author_part(entry), "", entry.year, suffix)
    }

    pub fn in_text(&self, key: &str) -> Result<String, CitationError> {
        let entry = self
            .get(key)
            .ok_or_else(|| CitationError::UnknownKey(key.to_string()))?;
        Ok(format!("({})", self.core(entry)))
    }

    pub fn in_text_with_page(&self, key: &str, page: &str) -> Result<String, CitationError> {
        // Page validation happens before the key lookup.
        if page.is_empty() || !page.bytes().all(|b| b.is_ascii_digit()) {
            return Err(CitationError::InvalidPage(page.to_string()));
        }
        let entry = self
            .get(key)
            .ok_or_else(|| CitationError::UnknownKey(key.to_string()))?;
        Ok(format!("({}, p. {})", self.core(entry), page))
    }

    pub fn cite_many(&self, keys: &[&str]) -> Result<String, CitationError> {
        if keys.is_empty() {
            return Err(CitationError::NoCitations);
        }
        let mut seen: Vec<&str> = Vec::new();
        for key in keys {
            if seen.contains(key) {
                return Err(CitationError::DuplicateCitation(key.to_string()));
            }
            if self.get(key).is_none() {
                return Err(CitationError::UnknownKey(key.to_string()));
            }
            seen.push(key);
        }
        let mut cores: Vec<String> = keys.iter().map(|k| self.core(self.get(k).unwrap())).collect();
        cores.sort();
        Ok(format!("({})", cores.join("; ")))
    }

    pub fn bibliography(&self) -> String {
        // (lead surname, year, suffix) for sorting; suffix "" sorts before "a".
        let mut lines: Vec<(String, String)> = self
            .entries
            .iter()
            .map(|entry| {
                let surname = entry_lead_surname(entry).to_string();
                let suffix = self.suffix_string_for(&entry.key);
                (surname, suffix)
            })
            .zip(self.entries.iter())
            .map(|((surname, suffix), entry)| {
                let author_list = match entry.authors.len() {
                    1 => entry.authors[0].clone(),
                    _ => {
                        let head = entry.authors[..entry.authors.len() - 1].join(", ");
                        format!("{}, & {}", head, entry.authors[entry.authors.len() - 1])
                    }
                };
                let terminator = if entry
                    .title
                    .ends_with('.')
                    || entry.title.ends_with('!')
                    || entry.title.ends_with('?')
                {
                    ""
                } else {
                    "."
                };
                let line = format!(
                    "{} ({}{}). {}{}",
                    author_list,
                    entry.year,
                    suffix,
                    entry.title,
                    terminator
                );
                (surname, line)
            })
            .collect();

        // Sort by (lead surname, year, suffix): we need the year in the sort
        // key too, so rebuild the sort keys properly.
        let mut indexed: Vec<(usize, String, u16, String)> = Vec::new();
        for (i, entry) in self.entries.iter().enumerate() {
            let surname = entry_lead_surname(entry).to_string();
            let suffix = self.suffix_string_for(&entry.key);
            indexed.push((i, surname, entry.year, suffix));
        }
        indexed.sort_by(|a, b| {
            (&a.1, &a.2, &a.3).cmp(&(&b.1, &b.2, &b.3))
        });

        let sorted_lines: Vec<String> = indexed
            .into_iter()
            .map(|(i, _, _, _)| lines[i].1.clone())
            .collect();
        sorted_lines.join("\n")
    }
}

