    fn validation_order() {
        let mut index = CitationIndex::new();
        assert_eq!(
            index.add(Entry {
                key: "bad key".to_string(),
                authors: vec![],
                year: 999,
                title: "  ".to_string(),
            }),
            Err(CitationError::InvalidKey("bad key".to_string()))
        );
        assert_eq!(
            index.add(Entry {
                key: "k".to_string(),
                authors: vec![],
                year: 999,
                title: String::new(),
            }),
            Err(CitationError::NoAuthors)
        );
        assert_eq!(
            index.add(Entry {
                key: "k".to_string(),
                authors: vec!["Knuth".to_string()],
                year: 999,
                title: String::new(),
            }),
            Err(CitationError::InvalidAuthor("Knuth".to_string()))
        );
        assert_eq!(
            index.add(Entry {
                key: "k".to_string(),
                authors: vec!["Knuth, D.".to_string()],
                year: 999,
                title: String::new(),
            }),
            Err(CitationError::InvalidYear(999))
        );
        assert_eq!(
            index.add(Entry {
                key: "k".to_string(),
                authors: vec!["Knuth, D.".to_string()],
                year: 1984,
                title: "  ".to_string(),
            }),
            Err(CitationError::EmptyTitle)
        );
    }

    #[test]
    fn suffixes_shift_on_remove() {
        let mut index = CitationIndex::new();
        index.add(sample("a")).unwrap();
        index.add(sample("b")).unwrap();
        index.add(sample("c")).unwrap();
        assert_eq!(index.in_text("a").unwrap(), "(Knuth, 1984a)");
        index.remove("a").unwrap();
        assert_eq!(index.in_text("b").unwrap(), "(Knuth, 1984a)");
        assert_eq!(index.in_text("c").unwrap(), "(Knuth, 1984b)");
