    pub key: String,
    pub authors: Vec<String>,
    pub year: u16,
    pub title: String,
}

/// All errors reported by the citation index.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CitationError {
    InvalidKey(String),
    NoAuthors,
    InvalidAuthor(String),
    InvalidYear(u16),
    EmptyTitle,
    DuplicateKey(String),
    UnknownKey(String),
    InvalidPage(String),
    NoCitations,
    DuplicateCitation(String),
    DisambiguationOverflow,
}

