/// Returns the lead surname of an author string ("Surname, Given" format).
fn lead_surname_of(author: &str) -> &str {
    match author.split_once(',') {
        Some((surname, _)) => surname,
        None => author,
    }
}

/// Returns the lead surname of an entry (from its first author).
fn entry_lead_surname(entry: &Entry) -> &str {
    lead_surname_of(&entry.authors[0])
}

/// Validates a single author string.
