    if author.is_empty() || author.trim() != author {
        return false;
    }
    if author.matches(',').count() != 1 {
        return false;
    }
    let (surname, given) = author.split_once(',').unwrap();
    if surname.is_empty() || surname.trim() != surname {
        return false;
    }
    if given.trim().is_empty() {
        return false;
    }
    true
}

