    pub fn bibliography(&self) -> String {
        // Build (sort key, line) pairs for each entry.
        let mut lines: Vec<((String, u16, String), String)> = self
            .entries
            .iter()
            .map(|entry| {
                let surname = entry_lead_surname(entry).to_string();
                let suffix = self.suffix_string_for(&entry.key);
